window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["medcurso:medcurso-pediatria-ped-5"]={"block":"medcurso:medcurso-pediatria-ped-5","label":"Medcurso · PED 5","count":437,"questions":[{"id":"medcurso-pediatria-ped-5-343781","number":"343781","sourceNumber":"343781","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"As cardiopatias congênitas ocorrem em nove de cada mil nascidos vivos e\naproximadamente 25% deles necessitarão de intervenção ainda no primeiro ano de vida. A\napresentação clínica e a evolução dos sintomas dependem da natureza e gravidade do defeito\nanatômico e das alterações na fisiologia cardiovascular secundárias aos efeitos da circulação\ntransitória. Sobre as cardiopatias congênitas marque abaixo a resposta correta.","options":{"A":"A transposição das grandes artérias é uma cardiopatia congênita que se manifesta sem cianose.","B":"A dextroposição da aorta está presente na Tetralogia de Fallot.","C":"O teste do coraçãozinho diagnostica cardiopatias congênitas.","D":"A comunicação interatrial (CIA) é a cardiopatia congênita mais frequente entre os\nrecém-nascidos."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-343788","number":"343788","sourceNumber":"343788","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O Parvovírus Humano B19 é um vírus que provoca uma doença infecciosa frequente\nem pré-escolares, qual das opções abaixo é essa\ndoença?","options":{"A":"Rubéola.","B":"Sarampo.","C":"Eritema infeccioso.","D":"Escarlatina."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-345490","number":"345490","sourceNumber":"345490","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança, 7 anos, chega para consulta de rotina na UBS com história de febre de 38,5ºC,\ntosse produtiva, coriza, conjuntivite há 4\ndias, que evoluiu com exantema máculo-papular. Frente ao\nquadro, a principal hipótese diagnóstica e conduta inicial é:","options":{"A":"Sarampo - Colher sorologias para diagnóstico. Administrar vitamina A no mesmo dia do\ndiagnóstico. Notificação compulsória do caso suspeito. Vacinação de bloqueio dos contatos\nsuscetíveis em até 72 horas.","B":"Rubéola - sintomáticos e realizar vacinação de bloqueio nos contactantes. Não é necessário\nnotificação compulsória.","C":"Exantema súbito - sintomáticos. Não é necessário notificação compulsória.","D":"Eritema infeccioso - sintomáticos. Não é necessário notificação compulsória."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-345499","number":"345499","sourceNumber":"345499","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de 06 anos há 04 dias apresenta erupção maculopapular no rosto, com\naspecto de \"face esbofeteada\". Há 2 dias as\nlesões disseminaram-se para o tronco e extremidades,\ncom aspecto rendado e sem outros sinais ou sintomas. Qual é o agente etiológico mais provável\nneste caso?","options":{"A":"Paramixovírus.","B":"Togavírus.","C":"Parvovírus B19.","D":"Herpes Vírus Humano 6."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-283303","number":"283303","sourceNumber":"283303","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Escolar de 7 anos, com história de febre elevada, 39°C, há 3 dias, associada com\nexantema que iniciou no tronco e face e\nespalhou para os membros, além de falta de apetite e\ninapetência. Ao exame físico, encontra-se um exatema eritematoso, formada por pápulas pequenas\ne não confluentes, promovendo aspecto de lixa na pele e os sinais de Filatow e Pastia. Qual a\ndoença exantemática?","options":{"A":"Rubéola.","B":"Escarlatina.","C":"Sarampo.","D":"Varicela."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-247139","number":"247139","sourceNumber":"247139","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente jovem, com antecedente de doença reumática que se submeteu a tratamento\nodontológico há cinco dias, procura o pronto socorro com quadro de febre, astenia, anorexia,\ntaquicardia e sopro diastólico aspirativo no 2º espaço intercostal direito. O diagnóstico mais\nprovável é:","options":{"A":"Fístula arteriovenosa pulmonar.","B":"Anemia hemolítica.","C":"Pneumonia.","D":"Endocardite bacteriana.","E":"Arterite de canal arterial persistente."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-247159","number":"247159","sourceNumber":"247159","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança com 5 anos de idade e com corpo estranho intrabrônquico. O radiograma de\ntórax pode revelar.","options":{"A":"Pneumotórax e desvio mediastinal contralateral.","B":"Atelectasia pulmonar e desvio mediastinal contralateral.","C":"Atelectasia pulmonar e desvio mediastinal ipsilateral.","D":"Pneumotórax e desvio mediatinal ipsilateral.","E":"Pneumotórax e derrame pleural."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-247179","number":"247179","sourceNumber":"247179","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O achado de onda T positiva em todas as derivações precordiais em uma criança de 45\ndias de vida pode ser sinal de","options":{"A":"Normalidade para a faixa etária.","B":"Sobrecarga ventricular esquerda.","C":"Sobrecarga atrial esquerda.","D":"Sobrecarga biventricular.","E":"Sobrecarga ventricular direita."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-247180","number":"247180","sourceNumber":"247180","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 2 meses apresenta na ausculta cardíaca sopro holossistólico rude +++/6+\nem borda esternal esquerda média que pode\ncorresponder a","options":{"A":"Estenose da valva tricúspide.","B":"Estenose valvar aórtica.","C":"Comunicação interventricular.","D":"Sopro funcional.","E":"Fistula arteriovenosa pulmonar."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-251936","number":"251936","sourceNumber":"251936","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual dos abaixo NÃO é sinal de alerta para reconhecer a possibilidade de câncer na\ninfância?","options":{"A":"Reflexo branco na pupila.","B":"Manchas roxas no corpo.","C":"Fraturas ósseas sem trauma.","D":"Cefaléia esporádica."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-251937","number":"251937","sourceNumber":"251937","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A Escherichia coli é o agente etiológico mais encontrado em 80 a 90 % dos casos no\nprimeiro surto de infecção do trato urinário (ITU) na infância. Considerando isso, o tratamento pode\nser feito, como primeira escolha com todos os antibióticos abaixo, EXCETO:","options":{"A":"Ampicilina.","B":"Cefalexina.","C":"Sulfametoxazol+trimetropim.","D":"Gentamicina."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-217715","number":"217715","sourceNumber":"217715","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menor de 10 meses inicia um quadro de febre elevada (39,5°C) por 3 dias associado à\nirritabilidade, sem alterações no exame físico. No 4º dia da doença, a febre desaparece e inicia-se\num exantema em tronco que se espalha pela face e pelas extremidades. Esse quadro clínico é\nsugestivo de qual doença exantemática?","options":{"A":"Sarampo.","B":"Exantema Súbito.","C":"Eritema infeccioso.","D":"Rubéola."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-217709","number":"217709","sourceNumber":"217709","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O Sarampo é uma doença infecciosa grave, extremamente contagiosa, que pode\nevoluir com complicações e óbitos. No Brasil,\nos últimos casos haviam sido registrados em 2015,\nassociados a um surto ocorrido no Estado do Ceará. O surto de sarampo que a Venezuela vem\nenfrentando desde Julho de 2017, associado à atual situação sociopolítica desse país, com intenso\nmovimento migratório de venezuelanos, contribuiu para a propagação do vírus para o Brasil. Em\nrelação ao sarampo é CORRETO afirmar:","options":{"A":"O contágio se dá desde 2 dias antes do início dos pródromos até 4 dias após o aparecimento do\nexantema.","B":"O isolamento respiratório é necessário até 10 dias após o aparecimento do exantema.","C":"A febre, quando presente, é baixa e surge quando desaparece o exantema.","D":"O enantema é a última manifestação mucocutânea a aparecer."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-217729","number":"217729","sourceNumber":"217729","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Com relação às cardiopatias congênitas, marque aquela que cursa com cianose:","options":{"A":"Persistência do canal arterial.","B":"Coarctação da aorta.","C":"Estenose aórtica.","D":"Transposição de grandes artérias."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-182692","number":"182692","sourceNumber":"182692","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Com relação à ITU (Infecção do trato urinário) na infância marque a alternativa\nERRADA:","options":{"A":"A importância do diagnóstico precoce da ITU é prevenir e minimizar a formação e progressão da\ncicatriz renal, principalmente, no neonato e lactentes.","B":"O tratamento inicial com antibióticos é empírico, observando o estado geral e a idade do\npaciente, devendo o fármaco escolhido ser\nbactericida ou bacteriostático e administrado por um\nperíodo que não ultrapasse 7 dias.","C":"O exame de urina não substitui a urocultura no diagnóstico de ITU, mas pode apresentar\nalterações que permitem iniciar precocemente o tratamento.","D":"A urocultura, nas crianças sem controle esfincteriano, deve ser realizada por meio de punção\nsupra púbica ou sondagem vesical para\nconfirmação de ITU."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-183217","number":"183217","sourceNumber":"183217","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A chamada \"lingua em framboesa\", geralmente, é encontrada em qual das doenças\nexantemáticas abaixo enumeradas:","options":{"A":"Sarampo.","B":"Rubéola.","C":"Escarlatina.","D":"Exantema Súbito.","E":"Varicela."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-159069","number":"159069","sourceNumber":"159069","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 1 ano e 10 meses de vida, sexo masculino, chega à consulta ambulatorial\nacompanhado da mãe, com história de febre alta nos últimos 3 dias. Hoje não teve febre porém\namanheceu com lesões exantemáticas no corpo. Mãe refere que durante todos esses dias a\ncriança permaneceu com estado geral preservado, aceitando bem a dieta. Você solicita\nhemograma que apresenta: hemácias 4,1 milhões/mm3 Hb - 11,5 g/dl, Hto 35%, Leucócitos\n5.200/mm³ (Bastões 0, Segmentados 52%, Linfócitos típicos 73%), Plaquetas 251.000/mm³. EAS:\nsem alterações. Ao exame físico: BEG, eupneico, hidratado, corado, AP: MV +, sem RA, ACV: RCR\n2T, sem sopro, Abdome: flácido, indolor à palpação, sem visceromegalias palpáveis. A principal\nhipótese diagnóstica é:","options":{"A":"Exantema súbito.","B":"Rubéola.","C":"Dengue.","D":"Varicela."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-159074","number":"159074","sourceNumber":"159074","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"NÃO se constitui em critério para diagnóstico da Doença de Kawasaki:","options":{"A":"Febre por mais de 5 dias.","B":"Conjuntivite exudativa.","C":"Linfadenomegalia cervical.","D":"Descamação de extremidades."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-159082","number":"159082","sourceNumber":"159082","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de 8 anos, admitida no Pronto Socorro com quadro de dispnéia aos mínimos\nesforços, irritabilidade, enchimento capilar de 4 segundos, PA: 60 X 30 mmHg, FC: 150 bpm, FR:\n43 irpm, estertores bolhosos abundantes, pulsos finos, turgência jugular. Qual será a conduta\nterapêutica mais apropriada?","options":{"A":"Uso de beta bloqueador por via oral, pois, a frequência cardíaca está acima de 100 bpm.","B":"Internar na enfermaria com uso de vasodilatador (captopril), diurético e digoxina.","C":"Internar o paciente em unidade intensiva com monitorização contínua, drogas vasoativas e\ndiurético endovenoso.","D":"Indicar medidas gerais como repouso, restrição hídrica, dieta hipossódica, antes de iniciar\ntratamento farmacológico."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-159084","number":"159084","sourceNumber":"159084","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"NÃO se constitui em uma manifestação clínica da escarlatina:","options":{"A":"Febre baixa.","B":"Palidez perioral.","C":"Língua em framboesa.","D":"Exantema poupa palmas das mãos e plantas dos pés."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-159088","number":"159088","sourceNumber":"159088","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 2 meses é levado ao ambulatório por estar recusando o seio materno e não\nestar ganhando peso. Exame Físico: hidratado, febril (temperatura corporal 38°C), pálido 1+/4+ e\napático, bulhas rítmicas e normofonéticas. FC: 98 bpm, ausculta pulmonar normal, ausência de\nrigidez de nuca e fontanela anterior normotensa. O pediatra constata que o paciente perdeu 100 g\nem relação ao peso do mês anterior. Exames laboratoriais: Hemograma: 22.000 de leucócitos,\nbastões 7%, segmentados 76%, linfócitos 14%, exame simples de urina com mais de 30 leucócitos\npor campo, proteinúria 1+, presença de raras bactérias. A urinocultura só estará disponível em 72\nhoras. A conduta indicada nesse caso é:","options":{"A":"Iniciar sulfametoxazol-trimetroprim ou nitrofurantoína até resultado da urinocultura.","B":"Iniciar o antimicrobiano somente quando se obtiver o resultado da urinocultura positiva.","C":"Iniciar a investigação por imagem com urografia excretora, caso se confirme diagnóstico de\ninfecção urinária.","D":"Indicar internação e tratamento com antibioticoterapia sistêmica, pois o diagnóstico de infecção\nurinária é provável."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-135977","number":"135977","sourceNumber":"135977","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Pré-escolar de 4 anos dá entrada em unidade de saúde com queixa de febre diária\n38°C há 10 dias, dor em membros inferiores,\npetéquias difusas e aumento de volume abdominal.\nHemograma com 15.000 leucócitos, Bastões 0%, segmentados 10%, Linfócitos 85%, Monócitos\n\n5%, Hb 8,5%, VCM 90, HCM 32, Plaquetas 85.000. Qual o diagnóstico mais provável?","options":{"A":"Meningite meningocócica;","B":"Aplasia de medula óssea;","C":"Anemia carencial;","D":"Leucose aguda;"},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-135952","number":"135952","sourceNumber":"135952","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"São complicações da Glomerulonefrite difusa aguda, EXCETO:","options":{"A":"Insuficiência renal aguda;","B":"Encefalopatia hipertensiva;","C":"Taquidispneia;","D":"Proteinúria."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-135955","number":"135955","sourceNumber":"135955","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A causa mais comum de obstrução de vias aéreas superiores é:","options":{"A":"Laringotraqueite;","B":"Laringite;","C":"Resfriado comum;","D":"Amigdalite estreptocócica."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-135927","number":"135927","sourceNumber":"135927","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um lactante com 1 mês e 20 dias de vida é atendido na Unidade de Pronto\nAtendimento de seu bairro com história de\nvômitos alimentares em jato após as mamadas.\nEncontra-se abaixo do peso esperado para idade e desidratado. Após investigação, a ecografia\nabdominal firmou o diagnóstico de estenose hipertrófica de piloro. Quais os distúrbios acidobásicos\nque se espera encontrar?","options":{"A":"Alcalose respiratória;","B":"Alcalose metabólica;","C":"Acidose respiratória;","D":"Acidose metabólica."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-135980","number":"135980","sourceNumber":"135980","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considerando o quadro clínico da questão anterior e o diagnóstico, marque a\nalternativa que mostra os agentes etiológicos mais frequentes em ordem decrescente.","options":{"A":"Influenza, vírus sincicial respiratório e adenovírus;","B":"Streptococcus pneumoniae, Stafilococcus aureus e Haemophilus influenzae;","C":"Streptococcus pneumoniae, Haemophilus influenzae e moraxella catarrahalis;","D":"Influenza, Streptococcus pneumoniae e Haemophilus influenzae,"},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-135921","number":"135921","sourceNumber":"135921","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança do sexo masculino, com idade de 1 ano e 2 meses apresenta quadro\nrespiratório de evolução de 4 dias com tosse\ndesde o primeiro dia, secreção hialina nos primeiros 2\ndias e purulenta nos dias subsequentes. Há 1 dia, apresenta febre (39° C), aferida na Unidade de\nSaúde, frequência respiratória de 59 ipm e ausência de tiragem ao exame físico. Considerando os\ncritérios da OMS, adotados no Brasil pelo Ministério da Saúde, qual o diagnóstico mais provável?","options":{"A":"Pneumonia;","B":"Pneumonia atípica;","C":"Resfriado comum;","D":"Pneumonia grave;"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108696","number":"108696","sourceNumber":"108696","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre o tratamento da faringoamigdalite estreptocócica:","options":{"A":"O tratamento indicado para erradicar o estreptococo é o uso de azitromicina por três dias.","B":"O tratamento de escolha é a penicilina G benzatina por via intramuscular, dose única.","C":"Na criança é a tetraciclina por via oral, por dez dias.","D":"Não existem opções de tratamento oral na profilaxia primária da febre reumática."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108706","number":"108706","sourceNumber":"108706","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Na suspeita de S. pneumoniae com resistência intermediária à penicilina,\nrecomenda-se:","options":{"A":"Sulfametoxazol + trimetoprima.","B":"Azitromicina por cinco dias.","C":"Amoxicilina em dose usual (45 mg/kg/dia).","D":"Amoxicilina em altas doses (90 mg/kg/dia)."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108723","number":"108723","sourceNumber":"108723","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Entre os achados à Otoscopia, o mais indicativo de Otite Média Aguda é:","options":{"A":"Hiperemia do conduto;","B":"Otorréia;","C":"Perfuração do tímpano;","D":"Abaulamento do tímpano."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108732","number":"108732","sourceNumber":"108732","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Na suspeita clínica de infecção urinária em lactente febril, após coleta de urina I e\nurocultura e resultado da urina I sugestivo de infecção urinária, qual o procedimento mais\nadequado?","options":{"A":"Indicar internação para todas as crianças com faixa etária de risco de comprometimento renal\naté o término do tratamento;","B":"Iniciar tratamento antimicrobiano empírico e ambulatorial, exceto nos casos de comprometimento\ndo estado geral, vômitos, diarreia ou sinais de\ntoxemia;","C":"Aguardar o resultado da urocultura para prescrever o antibiótico mais adequado de acordo com\no antibiograma;","D":"Indicar internação apenas para lactentes jovens e neonatos febris já que representam o grupo\nde maior risco de pielonefrite aguda."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108640","number":"108640","sourceNumber":"108640","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Na USF Calafate, o médico de família e comunidade atende uma criança de 8 anos\ncom quadro diarreico há 10 dias, associado a\ndor abdominal, vômitos e febre nos primeiros dias. A\nmãe nega a presença de sangue, muco ou pus nas fezes. Ao exame físico, a criança apresenta um\nquadro de desidratação leve. Diante deste quadro, qual seria a conduta CORRETA, além da\nadministração de soro de reidratação oral?","options":{"A":"Prescrever antibiótico.","B":"Prescrever antiparasitário.","C":"Manter alimentação habitual.","D":"Prescrever antidiarreico da classe dos obstipantes."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-343171","number":"343171","sourceNumber":"343171","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre a principal causa de enucleação em crianças, assinale a alternativa correta.","options":{"A":"Trauma ocular","B":"Meduloepitelioma","C":"Astrocitoma pilocítico","D":"Retinoblastoma"},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-315172","number":"315172","sourceNumber":"315172","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Segundo o disque 100, foram mais de 3milhoes de telefonemas com denúncias de\nmaus-tratos (MT) a crianças e adolescentes. Relacione a alternativa CORRETA:","options":{"A":"A família é sempre um porto seguro sem questionamentos em casos de violência.","B":"Fraturas de costelas em lactentes é muito raro e sempre associada a trauma de grande\nintensidade, deve-se sempre pensar em possível MT se a cinética não é compatível.","C":"A notificação dos suspeitos de maus tratos no atendimento hospitalar não é obrigatória.","D":"Raramente a criança que sofreu violência apresenta alguma mudança de comportamento.","E":"A violência sexual contra a criança acontece mais frequentemente por estranhos."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-315173","number":"315173","sourceNumber":"315173","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa FALSA:","options":{"A":"Déficit podero-estatural pode ser um dos achados em crianças cardiopatas.","B":"A posição de cócoras adotadas por crianças com Tetralogia de Fallot piora a hipóxia.","C":"A facies de S de Down sinaliza a necessidade de avaliação cardíaca completa.","D":"A língua é o melhor local para observar cianose central.","E":"A ausência de pulsos em membros inferiores podem indicar coarctação de aorta."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-314204","number":"314204","sourceNumber":"314204","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Das afirmativas apresentadas abaixo, assinale a incorreta em relação às orientações\nterapêuticas frente a um caso de sarampo.","options":{"A":"A transmissão do sarampo ocorre de quatro a seis dias antes até 4 dias após o aparecimento do\nexantema.","B":"A avaliação da possibilidade de complicações é fundamental, pois, mesmo em crianças\npreviamente saudáveis, o sarampo pode ter manifestações clínicas severas.","C":"A análise molecular pode ser utilizada para determinar o genótipo do vírus do sarampo\ncirculante.","D":"A vitamina A deve ser prescrita na dose 100.000UI, via oral, para lactentes com menos de 6\nmeses de idade, 1x/dia, por 2 dias."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-315180","number":"315180","sourceNumber":"315180","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual das seguintes afirmações sobre trauma pediátrico no Brasil é verdadeira?","options":{"A":"Traumas relacionados aos veículos a motor somam menos de 10% de todas as lesões\npediátricas que resultam em óbito.","B":"Acidentes de trânsito é a principal causa de óbito em crianças e adolescentes de 1 a 14 anos.","C":"Capacetes de proteção para bicicleta não reduzem a gravidade da maioria dos traumatismos\ncrânio-encefálicos relacionados a bicicleta.","D":"A maioria dos óbitos relacionados ao fogo ocorrem nas escolas.","E":"O uso de equipamentos de contenção não reduziram os óbitos na faixa etária menor de 7 anos."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-307069","number":"307069","sourceNumber":"307069","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 8 anos de idade, é trazido pela genitora ao ambulatório com queixa de lesões\nde pele e dor leve em articulações. Relata\nque, há aproximadamente uma semana, apresentou\nfebre, cefaleia, coriza e adinamia. As lesões de pele, por vezes clareiam e retornam; e são pouco\npruriginosas. A genitora informa que o menor é falcêmico. Ao exame, está hipoativo, afebril,\nhipocorado ++/IV. Observa-se rubor facial, concentrado nas bochechas, e exantema macular, de\naspecto rendilhado, em membros, poupando regiões plantares e palmares. Com base nas\ninformações apresentadas, indique o diagnóstico para essa criança.","options":{"A":"Sarampo.","B":"Rubéola.","C":"Eritema infeccioso.","D":"Artrite reumatoide juvenil."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-307070","number":"307070","sourceNumber":"307070","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 8 anos de idade, é trazido pela genitora ao ambulatório com queixa de lesões\nde pele e dor leve em articulações. Relata\nque, há aproximadamente uma semana, apresentou\nfebre, cefaleia, coriza e adinamia. As lesões de pele, por vezes clareiam e retornam; e são pouco\npruriginosas. A genitora informa que o menor é falcêmico. Ao exame, está hipoativo, afebril,\nhipocorado ++/IV. Observa-se rubor facial, concentrado nas bochechas, e exantema macular, de\naspecto rendilhado, em membros, poupando regiões plantares e palmares. Indique o agente\netiológico que corrobora o diagnóstico do paciente.","options":{"A":"Parvovírus.","B":"Morbillivírus.","C":"Herpesvírus.","D":"Streptococos."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-279040","number":"279040","sourceNumber":"279040","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre os cuidados domiciliares de crianças dependentes de Ventilação Pulmonar\nMecânica (VPM), assinale a alternativa correta.","options":{"A":"Mesmo com a melhora do paciente, a criança precisará da mesma quantidade de cuidadores\nprofissionais e familiares.","B":"Durante a internação hospitalar, os cuidadores familiares devem passar por um momento em\nque sejam responsáveis pelo cuidado integral da\ncriança, sob vigilância da equipe de saúde.","C":"Cuidadores familiares só podem cuidar de seus filhos quando o serviço adicional estiver\ndisponível.","D":"A baixa escolaridade da família é um impeditivo para cuidadores domiciliares da criança em\nVPM."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-275987","number":"275987","sourceNumber":"275987","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"As síndromes exantemáticas são condições caracterizadas pelo surgimento de uma\nerupção cutânea disseminada. Acerca das\nsíndromes exantemáticas virais, assinale a alternativa\nINCORRETA.","options":{"A":"O período de maior transmissibilidade da rubéola ocorre de cinco dias antes até seis dias após o\ninício do exantema.","B":"No eritema infeccioso, a criança afetada precisa ser afastada do contato com outras crianças ao\nsurgir o exantema.","C":"Uma das características clínicas marcantes da varicela é o polimorfismo regional.","D":"O vírus do sarampo pertence ao gênero Morbillivirus da família Paramyxoviridae.","E":"O vírus responsável pelo exantema súbito é transmitido ao lactente por gotículas de saliva de um\nhospedeiro saudável."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-279046","number":"279046","sourceNumber":"279046","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa incorreta sobre as orientações terapêuticas frente a um caso de\nsarampo.","options":{"A":"A avaliação da possibilidade de complicações é fundamental, pois, mesmo em crianças\npreviamente saudáveis, o sarampo pode ter manifestações clinicas severas.","B":"A transmissão do sarampo ocorre de 4 a 6 dias antes até 4 dias após o aparecimento do\nexantema.","C":"A análise molecular pode ser utilizada para determinar o genótipo do vírus do sarampo\ncirculante.","D":"A vitamina A deve ser prescrita na dose de 100.000UI, via oral, para lactentes com menos de 4\nmeses de idade, 1x/dia, por 2 dias."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-275992","number":"275992","sourceNumber":"275992","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual o agente etiológico mais frequente na Infecção de Trato Urinário em uma menina\nde 10 meses?","options":{"A":"Klebsiella.","B":"Proteus.","C":"Staphylococcus saprophyticus.","D":"Escherichia coli.","E":"Pseudomonas."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-280423","number":"280423","sourceNumber":"280423","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa incorreta em relação à Febre.","options":{"A":"A função da termorregulação é manter a temperatura corporal dentro de certos limites.","B":"A área pré-óptica do hipotálamo é o centro que coordena e integra a termorregulação.","C":"Ocorre diminuição da síntese de proteínas de fase aguda pelo fígado, do zinco e ferro séricos,\nleucocitose e aceleração da proteólise celular.","D":"A temperatura corporal em geral permanece relativamente constante."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-279054","number":"279054","sourceNumber":"279054","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa que apresenta complicações encontradas tanto na correção\ncirúrgica como no fechamento percutâneo das CIVs.","options":{"A":"Mediastinite.","B":"Derrame pleural.","C":"Sepse.","D":"BAVT."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-280424","number":"280424","sourceNumber":"280424","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa incorreta sobre os processos associados às funções\nhipotalâmicas na regulação da temperatura corporal.","options":{"A":"Ativação de termorreguladores.","B":"Liberação de hormônios tireoidianos com indução do aumento das taxas metabólicas.","C":"Ativação dos mecanismos autonômicos que agem produzindo apenas a conservação da\ntemperatura corporal.","D":"Ativação de respostas comportamentais."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-283751","number":"283751","sourceNumber":"283751","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 6 anos de idade, chega à Unidade de Pronto Atendimento, UPA, com manchas\nhiperemiadas espalhadas pelo corpo. A mãe refere que há 4 dias apresentou quadro gripal, com\nfebre (até 38.4°C), coriza e cefaléia; surgindo posteriormente as lesões de pele, que começaram no\nrosto e depois acometeram tronco e membros. Ao exame, estado geral comprometido, hidratada,\neupneica, afebril, pálida. Observam-se lesões máculo-papulares em rosto (face \"em bofetada\"),\ntronco e membros, poupando as regiões palmares e plantares. Sem outros achados ao exame\nsegmentar. Indique o diagnóstico mais provável para o caso.","options":{"A":"Roséola.","B":"Rubéola.","C":"Escarlatina.","D":"Eritema infeccioso."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-283752","number":"283752","sourceNumber":"283752","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 6 anos de idade, chega à Unidade de Pronto Atendimento, UPA, com manchas\nhiperemiadas espalhadas pelo corpo. A mãe refere que há 4 dias apresentou quadro gripal, com\nfebre (até 38.4°C), coriza e cefaléia; surgindo posteriormente as lesões de pele, que começaram no\nrosto e depois acometeram tronco e membros. Ao exame, estado geral comprometido, hidratada,\neupneica, afebril, pálida. Observam-se lesões máculo-papulares em rosto (face \"em bofetada\"),\ntronco e membros, poupando as regiões palmares e plantares. Sem outros achados ao exame\nsegmentar. Com base no caso clínico, identifique o agente etiológico dessa doença.","options":{"A":"Rubivírus.","B":"Parvovírus B19.","C":"Herpesvírus tipo 6.","D":"Streptococcus Beta hemolítico."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-283753","number":"283753","sourceNumber":"283753","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 6 anos de idade, chega à Unidade de Pronto Atendimento, UPA, com manchas\nhiperemiadas espalhadas pelo corpo. A mãe refere que há 4 dias apresentou quadro gripal, com\nfebre (até 38.4°C), coriza e cefaléia; surgindo posteriormente as lesões de pele, que começaram no\nrosto e depois acometeram tronco e membros. Ao exame, estado geral comprometido, hidratada,\neupneica, afebril, pálida. Observam-se lesões máculo-papulares em rosto (face \"em bofetada\"),\ntronco e membros, poupando as regiões palmares e plantares. Sem outros achados ao exame\nsegmentar. Indique das alternativas apresentadas a que representa uma possível complicação\ndessa doença.","options":{"A":"Catarata, surdez.","B":"Glomerulonefrite.","C":"Meningite, encefalite.","D":"Aplasia medular transitória."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-278650","number":"278650","sourceNumber":"278650","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"É o tumor sólido extracraniano mais comum em lactentes e crianças, representando 8%\n\n- 10% de todos os tumores da infância e 15% de todas as mortes por câncer na população\npediátrica.","options":{"A":"Tumor de Wilms","B":"Tumor de células germinativas","C":"Hepatoblastoma","D":"Neuroblastoma"},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-249280","number":"249280","sourceNumber":"249280","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O uso de aciclovir oral para o tratamento de pessoas da varicela sem condições de\nrisco de agravamento não está indicado até o\nmomento, exceto para aquelas com idade inferior a\n12 anos, não podemos concordar que:","options":{"A":"Portadoras de doença dermatológica crônica.","B":"Pessoas com neuropatias crônicas.","C":"Pessoas que recebem medicamentos à base de corticoides por aerossol ou via oral, mas não\npor via endovenosa.","D":"Aquelas que estejam recebendo tratamento com ácido acetilsalicílico por longo tempo."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-231348","number":"231348","sourceNumber":"231348","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Correlacione as colunas: 1. Sinal de Koplik. 2. Linfonoadomegalia occipital e cervical\nposterior; 3. Aplasia eritroide. 4. Febre alta que some em crise; 5. Sinais de Pastia e Filatov. 6.\n\nPolimorfismo regional; ( ) Varicela; ( ) Sarampo; ( ) Escarlatina; ( ) Exantema súbito; ( ) Eritema\ninfeccioso; ( ) Rubéola","options":{"A":"5, 6, 4, 2, 3, 1","B":"6, 1, 5, 4, 3, 2","C":"6, 5, 3, 4, 1, 2","D":"5, 6, 4, 3, 1, 2","E":"6, 5, 2, 3, 4, 1"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-231350","number":"231350","sourceNumber":"231350","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente, 23 meses, sexo feminino, é levada ao hospital pelos pais, com história de\naumento de volume abdominal, dor óssea,\nemagrecimento, palidez, febre, apatia e irritabilidade há\ndois meses. Exame físico: regular estado geral, hipertensão arterial, protusão de globo ocular\nesquerdo, associado à equimose periorbitária e extensa tumoração palpável em loja renal direita de\nlimites imprecisos, atravessando a linha média do abdômen. A hipótese diagnóstica mais provável\né:","options":{"A":"Neuroblastoma.","B":"Tumor de Wilms.","C":"Linfoma não Hodgkin.","D":"Tumor do córtex suprarrenal.","E":"Linfoma Hodgkin"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-231360","number":"231360","sourceNumber":"231360","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre sarampo, é incorreto afirmar:","options":{"A":"A maior concentração de casos, atualmente, é em crianças menores de 1 ano e adultos não\nvacinados","B":"A infecção não induz imunidade permanente","C":"As principais complicações da doença são encefalomielite, cegueira e pneumonia.","D":"São necessárias pelo menos duas doses de vacina para atingir proteção efetiva","E":"NDA"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-249200","number":"249200","sourceNumber":"249200","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Indique a alternativa correta sobre a suspeita de aspiração de corpo estranho.","options":{"A":"A manobra de Heimlich é sempre a primeira intervenção.","B":"O exame de imagem não acrescenta informações na investigação.","C":"O corpo estranho não ocorre em menores de 3 anos de idade.","D":"Se a suspeita for forte, deve ser realizada laringoscopia/broncoscopia o mais precocemente\npossível."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-249207","number":"249207","sourceNumber":"249207","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa que apresenta a cardiopatia congênita mais comum.","options":{"A":"Coarctação da aorta.","B":"Transposição dos grandes vasos da base.","C":"Persistência do canal arterial.","D":"Comunicação interventricular."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-252921","number":"252921","sourceNumber":"252921","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 10 anos, chegou à Emergência queixando-se de mal-estar e cansaço aos\nesforços. Informa que há 4 dias esteve no\nPronto Atendimento por fadiga importante, dificuldade\nrespiratória e tosse seca que ocorriam há, aproximadamente, dois dias. Realizou hemograma,\nsumário de urina e radiografia de tórax, que não mostraram alterações, e foi liberado com\nprescrição de Eritromicina. Negava febre e outros sintomas. Ao exame, Temperatura: 36,6ºC; FC:\n174bpm. Pulsos Radiais simétricos, finos, arrítmicos. Pulso carotídeo arrítmico. Tempo de\nenchimento capilar: 4 segundos. Estava em regular estado geral, hidratado, eupneico, corado.\n\nAusculta cardíaca: bulhas normofonéticas; Pulmões com murmúrios vesiculares bem distribuídos,\nsem ruídos adventícios. Abdome plano,\nsimétrico, com fígado palpável a 2,5cm do Rebordo Costal\nDireito. Ao final do exame clínico referiu náuseas e apresentou síncope. Verificando-se ausência de\npulso, foram iniciadas compressões torácicas de imediato, tendo retornado os batimentos cardíacos\ncujo ritmo o monitor cardíaco mostra no traçado abaixo: Indique o ritmo cardíaco evidenciado pelo\nmonitor.","options":{"A":"Flutter Atrial.","B":"Taquicardia Sinusal.","C":"Taquicardia Supraventricular.","D":"Taquicardia Ventricular."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":["question_bank/media/medcurso/medcurso-pediatria-ped-5/252921.png"],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-252922","number":"252922","sourceNumber":"252922","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 10 anos, chegou à Emergência queixando-se de mal-estar e cansaço aos\nesforços. Informa que há 4 dias esteve no\nPronto Atendimento por fadiga importante, dificuldade\nrespiratória e tosse seca que ocorriam há, aproximadamente, dois dias. Realizou hemograma,\nsumário de urina e radiografia de tórax, que não mostraram alterações, e foi liberado com\nprescrição de Eritromicina. Negava febre e outros sintomas. Ao exame, Temperatura: 36,6ºC; FC:\n174bpm. Pulsos Radiais simétricos, finos, arrítmicos. Pulso carotídeo arrítmico. Tempo de\nenchimento capilar: 4 segundos. Estava em regular estado geral, hidratado, eupneico, corado.\n\nAusculta cardíaca: bulhas normofonéticas; Pulmões com murmúrios vesiculares bem distribuídos,\nsem ruídos adventícios. Abdome plano,\nsimétrico, com fígado palpável a 2,5cm do Rebordo Costal\nDireito. Ao final do exame clínico referiu náuseas e apresentou síncope. Verificando-se ausência de\npulso, foram iniciadas compressões torácicas de imediato, tendo retornado os batimentos cardíacos\ncujo ritmo o monitor cardíaco mostra no traçado abaixo: Indique o passo terapêutico seguinte no\natendimento desse paciente.","options":{"A":"Realizar cardioversão.","B":"Realizar Manobra Vagal.","C":"Administrar Atropina.","D":"Administrar Adenosina."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":["question_bank/media/medcurso/medcurso-pediatria-ped-5/252922.png"],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-252923","number":"252923","sourceNumber":"252923","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 10 anos, chegou à Emergência queixando-se de mal-estar e cansaço aos\nesforços. Informa que há 4 dias esteve no\nPronto Atendimento por fadiga importante, dificuldade\nrespiratória e tosse seca que ocorriam há, aproximadamente, dois dias. Realizou hemograma,\nsumário de urina e radiografia de tórax, que não mostraram alterações, e foi liberado com\nprescrição de Eritromicina. Negava febre e outros sintomas. Ao exame, Temperatura: 36,6ºC; FC:\n174bpm. Pulsos Radiais simétricos, finos, arrítmicos. Pulso carotídeo arrítmico. Tempo de\nenchimento capilar: 4 segundos. Estava em regular estado geral, hidratado, eupneico, corado.\n\nAusculta cardíaca: bulhas normofonéticas; Pulmões com murmúrios vesiculares bem distribuídos,\nsem ruídos adventícios. Abdome plano,\nsimétrico, com fígado palpável a 2,5cm do Rebordo Costal\nDireito. Ao final do exame clínico referiu náuseas e apresentou síncope. Verificando-se ausência de\npulso, foram iniciadas compressões torácicas de imediato, tendo retornado os batimentos cardíacos\ncujo ritmo o monitor cardíaco mostra no traçado abaixo: Indique os dois fármacos preconizados\npelo protocolo de Suporte Avançado em Pediatria, como antiarrítmicos, na fase de estabilização\ndesse paciente, pós-reanimação.","options":{"A":"Amiodarona e Magnésio.","B":"Amiodarona e Lidocaína.","C":"Magnésio e Procainamida.","D":"Procainamida e Lidocaína."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":["question_bank/media/medcurso/medcurso-pediatria-ped-5/252923.png"],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-252932","number":"252932","sourceNumber":"252932","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 30 meses de idade, é levado à UPA com febre há 72 horas. Sua mãe refere\nque a temperatura tem ultrapassado os 39ºC\nque o menor não tem aceito alimentos, vem\napresentando irritabilidade e diminuiu as eliminações (atribuindo à reduzida ingestão). No momento,\na temperatura é 39,6ºC. Não foram observadas alterações ao exame físico segmentar. Indique a\nlista dos exames complementares que devem ser solicitados neste momento.","options":{"A":"Hemograma; VHS e Sumário de Urina.","B":"Sumário de Urina, Urocultura e Radiografia de tórax.","C":"Hemograma; PCR; Hemoculturas e Radiografia de tórax.","D":"Hemograma; VHS; PCR; Hemocultura; Sumário de Urina e Urocultura."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-216331","number":"216331","sourceNumber":"216331","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"São diversos os fatores que colocam as crianças portadoras de cardiopatias congênitas\nem maior risco de trombose. Os pacientes\ncianóticos estão em maior risco de complicações graves.\nTodas as abaixo indicam um complicação possível nesses pacientes, EXCETO","options":{"A":"embolia pulmonar.","B":"acidente vascular cerebral isquêmico.","C":"hipotermia profunda.","D":"comprometimento de membros."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-216339","number":"216339","sourceNumber":"216339","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Existe um substancial interesse no desenvolvimento de biomarcadores para melhorar o\nmanejo da sepse. Um grande número de biomarcadores tem sido descritos, entretanto a\nprocalcitonina (PCT) e a proteína C reativa (PCR) são as mais usadas. Em função de não existir um\nmarcador específico para sepse e choque séptico, o manejo fundamenta-se em todas as abaixo,\nEXCETO","options":{"A":"reconhecimento precoce.","B":"iniciar droga vasoativa assim que a pressão arterial estiver abaixo do percentil 10 para a\nidade.","C":"controle do foco.","D":"administração de antibióticos."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-216222","number":"216222","sourceNumber":"216222","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente em pós-operatório de Tetralogia de Fallot apresenta taquiarritmia com pulsos\npalpáveis e diminuição da diurese. Qual é a arritmia frequente nesses pacientes?","options":{"A":"Fibrilação ventricular.","B":"Taquicardia juncional.","C":"Taquicardia supraventricular.","D":"Fibrilação atrial."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215505","number":"215505","sourceNumber":"215505","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Dos exames citados a seguir, qual é o padrão ouro para diagnóstico da infecção do\ntrato urinário em pediatria?","options":{"A":"Urinocultura.","B":"Ultrassonografia de rins e vias urinárias.","C":"Hemocultura.","D":"Urina tipo 1 colhida por sondagem vesical."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215520","number":"215520","sourceNumber":"215520","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual é o principal diagnóstico para uma criança de 8 anos que apresenta quadro de\nfebre, com presença de sinal de Foshereimer e lesões polimórficas nucleadas, com inclusões\neosinofílicas, que iniciaram-se de forma centrípeta?","options":{"A":"Parvovirose.","B":"Varicela.","C":"Doença de Kawasaki.","D":"Rubéola."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-219907","number":"219907","sourceNumber":"219907","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em uma consulta de rotina, a mãe de um paciente de 1 ano e seis meses de idade,\npeso 10 kg (Z-score 0,23), estatura 84 cm\n(Z-score 0,10), relata que seu filho gosta de mexer em\ntudo. Ela demonstra-se bastante preocupada pois tem receio que seu filho se machuque, agora que\nconsegue andar sozinho pela casa. A respeito da prevenção de acidentes, a mãe deveria receber a\nseguinte orientação:","options":{"A":"Manter materiais pontiagudos ou cortantes e produtos tóxicos em local bem arejado na cozinha\nou área de serviço.","B":"Proteger cantos dos móveis, além de colocar barreiras de proteção nas escadas e janelas.","C":"Segurar a criança fortemente pela mão ao sair de casa, evitando que ele se solte e corra para a\nrua.","D":"Transportar a criança em assento de elevação (boosters) com cinto de três pontos no banco de\ntrás do carro."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215233","number":"215233","sourceNumber":"215233","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa CORRETA em relação aos mecanismos do trauma.","options":{"A":"A hipovolemia é a principal causa de choque em crianças. O estado hipovolêmico resulta do\naumento da pré-carga e, como consequência, há aumento do débito cardíaco.","B":"O débito cardíaco está diminuído no choque obstrutivo por causa de uma obstrução física que\nimpede o fluxo sanguíneo adequado.","C":"O choque distributivo decorre de disfunção miocárdica, manifestando-se fisiologicamente por\nfunção sistólica e débito cardíacos deprimidos.","D":"O choque cardiogênico ocorre pela diminuição da resistência vascular sistêmica, com diminuição\nanormal do fluxo sanguíneo na microcirculação."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215514","number":"215514","sourceNumber":"215514","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Das cardiopatias citadas a seguir, qual está relacionada a risco de hipertensão\npulmonar no pós-operatório?","options":{"A":"Atresia tricúspide.","B":"Defeito do septo atrioventricular.","C":"Coarctação de aorta.","D":"Tetralogia de Fallot."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215237","number":"215237","sourceNumber":"215237","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa CORRETA sobre o diagnóstico de choque.","options":{"A":"Requer alto índice de suspeita e conhecimento das condições predisponentes do paciente.","B":"Deve-se aguardar por sinais de hipotensão para confirmá-lo, embora haja algum risco de óbito.","C":"Os exames de imagem e laboratoriais são pouco úteis no diagnóstico e manejo do choque,\nporque o exame físico se sobressai.","D":"É, sobretudo, clínico, por isso deve-se estar atento às alterações da frequência cardíaca e aos\nsinais de hiperperfusão tecidual."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215522","number":"215522","sourceNumber":"215522","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Marque a alternativa CORRETA.","options":{"A":"As crises de hipertensão pulmonar podem levar a uma acidose respiratória, mas não a uma\nacidose metabólica.","B":"O ciclo de piora da hiperoxemia, hipocapnia e acidose resultam no aumento da impedância\nvascular pulmonar com consequente falência do ventrículo direito e morte em todos os casos.","C":"A prevenção ativa da acidose e da hipóxia é essencial para o manejo de pacientes em risco de\nhipertensão pulmonar.","D":"O uso de óxido nítrico é a primeira linha no tratamento da hipertensão pulmonar."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-216255","number":"216255","sourceNumber":"216255","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considerando-se a febre na infância, assinale a alternativa CORRETA.","options":{"A":"Os lactentes com idade inferior a 3 meses fazem parte do grupo etário mais vulnerável às\ndoenças bacterianas graves.","B":"A vacinação para pneumococo pouco influenciou a epidemiologia da febre sem sinais de\nlocalização em crianças.","C":"A maioria das crianças febris apresenta febre sem sinais de localização, fonte de dúvidas entre\nos pediatras.","D":"A grande parte das crianças com febre sem sinais de localização apresenta doença viral benigna\nautolimitada, por isso não é necessário a investigação do quadro."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215243","number":"215243","sourceNumber":"215243","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A intermação é uma situação que pode ameaçar a vida, geralmente definida como\nhipertermia maior ou igual a 40ºC associada à desidratação, pele seca com rubor e quente e\ndisfunção do sistema nervoso central. Assinale a alternativa INCORRETA.","options":{"A":"A forma sem esforço frequentemente ocorre durante as ondas de calor ambiental e\nprimariamente afeta os mais idosos e doentes.","B":"A intermação ocorre quando a temperatura corporal se eleva e o sistema de termorregulação\nfalha em responder adequadamente.","C":"A mortalidade da intermação varia, em média de 33-80%, nos doentes com intermação clássica.","D":"A forma clássica ou com esforço normalmente ocorre em jovens e saudáveis, e pessoas\nfisicamente ativas, que estão engajadas em exercícios extenuantes em ambientes quentes e\númidos."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-219908","number":"219908","sourceNumber":"219908","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Mãe de 3 filhos cujas idades são 1 ano, 5 anos e 12 anos, sendo que as crianças têm\nestaturas adequadas à idade. Ela fará uma viagem de carro com as crianças e está preocupada\ncom os cuidados de segurança que devem ser adotados. A alternativa CORRETA sobre a\nprevenção de acidentes automobilísticos na infância é:","options":{"A":"A criança de 1 ano deverá ser levada no bebê-conforto ou assento conversível, no banco de\ntrás, com face voltada para frente.","B":"A criança de 5 anos deve ser levada no banco de trás, com cinto de 3 pontos, com a face\nvoltada para frente.","C":"A criança de 12 anos pode ir no banco da frente utilizando o cinto de segurança de 3 pontos.","D":"Os assentos infantis podem ser fixado ao carro com a utilização de cinto de 2 pontos."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215507","number":"215507","sourceNumber":"215507","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A válvula de uretra posterior é a uropatia obstrutiva congênita mais comum da\npopulação pediátrica masculina. Assinale a alternativa INCORRETA.","options":{"A":"Pode representar um risco fatal imediato para o recém-nascido e, tardiamente, instalar\ninsuficiência renal crônica e irreversível.","B":"As consequências clínicas estão relacionadas diretamente ao grau da obstrução uretral e à\nrepercussão na bexiga.","C":"O diagnóstico de certeza e definitivo da válvula de uretra é feito por meio de cistouretrografia\nmiccional ou uretroscopia.","D":"A uropatia obstrutiva durante a vida intrauterina tem como consequência o polidrâmnio e o\naumento do líquido na árvore brônquica e nos pulmões."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-212208","number":"212208","sourceNumber":"212208","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Depois de ser eliminado nos anos 90 no Brasil, o sarampo volta a ser problema de\nsaúde pública. A recomendação atual é","options":{"A":"programar vacinação em massa de adultos e crianças pela gravidade da doença.","B":"aumentar as taxas de vacinação em todo o território nacional para garantir o controle da doença.","C":"reforçar a vigilância e elevar a taxa de vacinação nas regiões de fronteiras com maior fluxo de\nimigração.","D":"atentar, juntamente com o sarampo, para as baixas coberturas vacinais de poliomielite e vacinar\nantes dos 12 meses de vida.","E":"não valorizar a diferença entre um caso autóctone, de um caso importado, ou ainda relacionado\na um vírus vacinal para tomada de conduta."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-212172","number":"212172","sourceNumber":"212172","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O transporte seguro de crianças em automóveis deve ser baseado nas melhores\nevidencias cientificas e o pediatra tem a\nresponsabilidade de orientar sobre os equipamentos\ndisponíveis, seguros e adequados para cada fase de seu desenvolvimento. Nesse contexto, dadas\nas afirmativas, I. Os assentos de segurança específicos para o transporte de crianças em\nautomóveis têm as características adequadas às diversas fases do crescimento, desde a alta da\nmaternidade até o momento em que o adolescente atinge 1,45 m de altura, quando pode utilizar o\ncinto de segurança. II. Desde 2010, vigora no Brasil a Resolução no 277 do Conselho Nacional de\nTrânsito, segundo a qual menores de 10 anos devem ser transportados nos bancos traseiros,\nusando individualmente dispositivo de retenção apropriado para sua idade. III. O critério de peso\ncontinua sendo o mais fiel para a escolha do melhor assento, segundo evidências científicas atuais.\nverifica-se que está(ão) correta(s)","options":{"A":"I, apenas.","B":"III, apenas.","C":"I e II, apenas.","D":"II e III, apenas.","E":"I, II e III."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-212197","number":"212197","sourceNumber":"212197","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Elias, 1 ano e 1 mês, começou a apresentar febre alta e contínua, com a presença de\nlinfonodos cervicais palpados e hiperemia em cavum. Após cerca de 3 a 4 dias, cessou\nbruscamente a febre, surgindo exantema maculopapular súbito, iniciando em tronco, com\ndisseminação para a cabeça e extremidades, e desaparecimento em 3 dias. Quais o mais provável\ndiagnóstico para Elias e seu agente etiológico?","options":{"A":"Varicela, devido ao varicela-zóster vírus.","B":"Eritema infeccioso, devido ao parvovírus.","C":"Roséola infantil, devido ao herpesvírus humano.","D":"Doença mão-pé-boca, devido ao coxsackievirus.","E":"Mononucleose infecciosa, devido ao vírus Epstein-Barr."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-180156","number":"180156","sourceNumber":"180156","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Segundo o disque 100, foram mais de 3milhoes de telefonemas com denúncias de\nmaus-tratos (MT) a crianças e adolescentes. Relacione a alternativa correta:","options":{"A":"A família é sempre um porto seguro sem questionamentos em casos de violência","B":"Fraturas de costelas em lactentes é muito raro e sempre associada a trauma de grande\nintensidade, deve-se sempre pensar em possível MT se a cinética não é compatível","C":"A notificação dos suspeitos de maus tratos no atendimento hospitalar não é obrigatória","D":"Raramente a criança que sofreu violência apresenta alguma mudança de comportamento","E":"A violência sexual contra a criança acontece mais frequentemente por estranhos"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-182762","number":"182762","sourceNumber":"182762","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a Obstrução Intestinal Congênita que está associada à epidermólise bolhosa:","options":{"A":"Atresia de piloro.","B":"Atresia de duodeno.","C":"Atresia jejuno ileal.","D":"Atresia de cólon."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-180113","number":"180113","sourceNumber":"180113","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa falsa:","options":{"A":"Déficit podero-estatural pode ser um dos achados em crianças cardiopatas","B":"A posição de cócoras adotadas por crianças com Tetralogia de Fallot piora a hipóxia","C":"A facies de S de Down sinaliza a necessidade de avaliação cardíaca completa","D":"A língua é o melhor local para observar cianose central","E":"A ausência de pulsos em membros inferiores podem indicar coarctação de aorta"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-183640","number":"183640","sourceNumber":"183640","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Das doenças exantemáticas citadas a seguir, qual é a única que não apresenta\nexantema vesicobolhoso?","options":{"A":"Herpes zoster.","B":"Chikungunya.","C":"Exantema súbito.","D":"Doença mão-pé-boca."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-182804","number":"182804","sourceNumber":"182804","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 3 anos, previamente hígida, chega ao Pronto Socorro com insuficiência\nrespiratória, apresentando inicio súbito de estridor, evoluindo para dispneia. A mãe nega febre e\nsintomas de vias aéreas superiores nos últimos dias. Ao exame encontra-se afebril, pálida, com\ncianose de extremidades e perioral, tosse bitonal, sibilos esparsos e murmúrio vesicular diminuído\nem hemitórax direito. O diagnóstico mais provável e a conduta são:","options":{"A":"Laringite aguda, inalação com adrenalina pura e corticoide via oral.","B":"Aspiração de corpo estranho, radiografia de tórax e solicitar broncoscopia.","C":"Epiglotite, entubação orotraqueal e uso de ceftriaxone.","D":"Asma aguda grave, radiografia de tórax e inalações de resgate com beta 2 agonista."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-182745","number":"182745","sourceNumber":"182745","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação à Febre De Origem Indeterminada (FOI) na criança, assinale a alternativa\nINCORRETA:","options":{"A":"É definida como febre > 38 graus durante mais de 14 dias sem nenhuma causa óbvia apesar de\numa anamnese completa, exame físico e avaliação\nlaboratorial rotineira.","B":"As três categorias mais comuns de FOI em crianças são: doenças infecciosas, doenças do\ntecido conjuntivo ou inflamatórias e neoplasias.","C":"Por definição os achados físicos são exuberantes nas crianças com FOI. Sudorese deve ser\nobservada, sua ausência sugere desidratação por vômitos e diarréia.","D":"Além da documentação cuidadosa de vários episódios de temperatura elevada, deve-se obter\nanamnese minuciosa, incluindo: impacto da febre sobre a saúde da criança, perda ponderal,\npresença de doença associada, envolvimento de órgãos vitais, uso de drogas, medicamentos ou\nterapia imunossupressora, viagem doméstica ou internacional, atividade sexual."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-183036","number":"183036","sourceNumber":"183036","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual é a melhor forma de identificar as causas potencialmente reversíveis de parada\ncardiorrespiratória em uma criança que chega ao Pronto-socorro?","options":{"A":"Obter história com o cuidador ou um familiar.","B":"Obter uma amostra de urina para triagem toxicológica.","C":"Realizar radiografia de tórax e abdome.","D":"Obter uma gasometria venosa."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-182748","number":"182748","sourceNumber":"182748","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre o Tumor de Wilms, é INCORRETO que,","options":{"A":"é uma neoplasia renal embrionária consistindo em blastema metanéfrico em 85% dos casos.","B":"75% dos casos são diagnosticados em crianças com menos de 5 anos de idade.","C":"13% pode apresentar-se com tumor bilateral.","D":"o pricipal tratamento para o Tumor de Wilms é a quimio e radioterapia."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-181421","number":"181421","sourceNumber":"181421","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação à Tetralogia de Fallot, é correto afirmar:","options":{"A":"a cirurgia corretiva se impõe logo após ganho de peso satisfatório.","B":"o grau de estenose pulmonar é fator determinante para o prognóstico.","C":"não é detectada no período neonatal com o teste do coraçãozinho.","D":"o tamanho da CIV é fator determinante para a precocidade das manifestações clínicas.","E":"o uso de captopril aumenta o shunt E-D levando a uma melhor compensação cardíaca."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-181423","number":"181423","sourceNumber":"181423","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A hipertensão arterial, na infância, é fator previsor de hipertensão arterial no adulto e\nsua aferição nas consultas pediátricas deve ser\nrealizada:","options":{"A":"em toda criança a partir do primeiro ano de idade.","B":"com manguito que deixe descoberta a fossa cubital.","C":"em todas as avaliações médicas de rotina, desde o período escolar.","D":"em crianças portadoras de condições especiais que representem risco elevado para\nhipertensão.","E":"em toda criança a partir de três anos de idade e também nas menores de três anos, se forem\nprematuras, com complicações neonatais, genitourinárias e outras doenças associadas com\nhipertensão arterial."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-181427","number":"181427","sourceNumber":"181427","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Patrícia, há cerca de seis meses, leva seu filho de 11 anos para investigação\ndiagnóstica de crise convulsiva focal em\nmembros, sem fatores desencadeantes ou relação com\nsono, os quais surgem e cedem espontaneamente, já tendo sido realizada triagem com\nneuropediatria e eletroencefalograma, sem determinação de alterações em exame físico ou em\nexames complementares. É filho único de casal divorciado, há sete meses, saudável previamente,\ne com bom desenvolvimento neuropsicomotor. Qual a hipótese diagnóstica mais provável?","options":{"A":"Síndrome de Munchhausen por procuração.","B":"Encefalopatia mioclônica precoce.","C":"Síndrome de Panayiotopoulos.","D":"Epilepsia mioclônica juvenil.","E":"Síndrome de West."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-181397","number":"181397","sourceNumber":"181397","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Júlio, 3 anos, há 07 dias vem apresentando febre diária, hiperemia conjuntival bilateral,\nadenomegalia não dolorosa em cadeia cervical esquerda (2cm), língua em framboesa, exantema\nmaculopapular, edema em boca, mãos e pés, sendo realizados exames complementares que\nevidenciaram: leucocitose (22 mil), plaquetas: 550mil/mm³, PCR: 96mg/L, EAS com 40\nleucócitos/campo e bacterioscopia negativa. Qual o diagnóstico mais provável?","options":{"A":"Síndrome do choque tóxico.","B":"Doença de Kawasaki.","C":"Doença mão-pé-boca.","D":"Mononucleose.","E":"Escarlatina."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-152654","number":"152654","sourceNumber":"152654","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Quais das seguintes afirmações melhor descrevem os fatores mais contribuem para o\ndesenvolvimento de parada cardiorespiratória em lactentes e crianças?","options":{"A":"PCR é usualmente o primeiro sintoma de enfermidade\ncardiovascular subjacente.","B":"PCR em crianças é provocada com maior frequência por início súbito de arritmias ventriculares.","C":"PCR em crianças é, com maior frequência, o resultado de bloqueio cardíaco congênito ou outras\nanormalidades do sistema de condução.","D":"PCR em crianças é, com maior frequência, o resultado final da deterioração das funções\nrespiratória e circulatória.","E":"PCR em crianças é muito raro e geralmente não é resultado da piora respiratória"},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-152626","number":"152626","sourceNumber":"152626","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Na síndrome do Bebê Sacudido, poderemos encontrar, exceto:","options":{"A":"A criança pode apresentar sinais de espancamento,\n\ncomo fratura de costelas ou sinais discretos de lesões traumáticas em regiões cobertas por roupas.","B":"A criança apresenta geralmente com quadro de menor atividade progressiva (letargia).","C":"A criança frequentemente é filha de pais adolescentes jovens.","D":"Podem ser filhos de pais drogaditos.","E":"A tomografia craniana frequentemente não\napresenta lesões sugestivas."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-161178","number":"161178","sourceNumber":"161178","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Para o atendimento da criança traumatizada é fundamental o conhecimento das\nparticularidades da anatomia da criança. Sobre isso, é INCORRETO afirmar que:","options":{"A":"A laringe posterior tem propensão a se anteriorizar em decorrência da flexão passiva da cabeça.","B":"Os tecidos moles da orofaringe de um lactente são proporcionalmente maiores quando\ncomprado aos tecidos da cavidade oral, o que\ndificulta a visualização da laringe.","C":"A traqueia do lactente mede em torno de 5 cm de comprimento.","D":"A laringe da criança é semelhante à do adulto."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-161187","number":"161187","sourceNumber":"161187","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O Tumor de Wilms é uma neoplasia renal embrionária consistindo em blastema\nmetanefrético na maioria dos casos. Sobre este assunto, marque a opção INCORRETA.","options":{"A":"Os principais tratamentos para o Tumor de Wilms são radioterapia e quimioterapia.","B":"Pico de incidência ocorre aos 2-3 anos de idade.","C":"13% pode apresentar tumor bilateral, que é sincrônico em 60% dos casos.","D":"É classificada como favorável e desfavorável. Sendo a favorável mais comum, caracterizada\npela presença de três elementos: células blastemais,\nestromais e epiteliais."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-161388","number":"161388","sourceNumber":"161388","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Os tumores neuroblásticos, incluindo o neuroblastoma, o ganglioneuroblastoma e o\nganglioneuroma são tumores originados das células da placa neural primitiva, que produzirá as\ncélulas da medula adrenal e dos gânglios simpáticos por todo corpo. Sobre o Neuroblastoma,\naponte a alternativa INCORRETA.","options":{"A":"Quanto menor a criança, maior a chance de cura.","B":"Doença metastática que está presente em aproximadamente 70% dos casos ao diagnóstico.","C":"O achado clínico mais comum é a presença de massa dura, indolor e com superfície irregular.","D":"Pode estar associado a algumas anomalias, como aniridia, malformações genitourinárias,\nneurofibromatose, hemi-hipertrofia, síndrome de Beckwith-Wiedmann e Denys-Drash."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-158755","number":"158755","sourceNumber":"158755","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A prevenção de recidiva, no caso da infecção do trato urinário em crianças, visa evitar\nepisódios posteriores da doença, desconforto e estresse familiar. Em qual dos seguintes quadros\nclínicos essa profilaxia deve ser indicada?","options":{"A":"Somente após o término da investigação ultrassonográfica do\ntrato urinário ser concluída, no caso da presença de achados\nultrassonográficos no pré-natal sugestivos de uropatias.","B":"Após confirmação do segundo episódio de infecção urinária por urocultura.","C":"Apenas na presença de refluxo vesicoureteral de grau 4.","D":"Na presença de trato urinário gravemente dilatado.","E":"Após correção cirúrgica de uropatia obstrutiva."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-161287","number":"161287","sourceNumber":"161287","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação à pressão arterial, analise as afirmativas a seguir. I. O uso de monitorização\ninvasiva de pressão arterial é indicado\npara os pacientes com instabilidade hemodinâmica mais\nimportante, para os que se apresentem hipotensos e nos casos de hipertensão arterial grave, como\nnas emergências hipertensivas. II. A pressão arterial normal descarta a presença de baixo débito\ncardíaco e baixa oferta tecidual de oxigênio. III. Como regra prática, pode-se utilizar como um dos\nvalores para diagnóstico de hipotensão em crianças e recém-nascidos a pressão arterial sistólica\ninferior a 60 mmHg. Está CORRETO, APENAS, o contido em","options":{"A":"I e II.","B":"I e III.","C":"II e III.","D":"II."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-158827","number":"158827","sourceNumber":"158827","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A infecção do trato urinário é a infecção bacteriana mais comum na infância e até 30%\ndos neonatos e crianças sofrem de infecções\nrecidivas durante os primeiros 6 a 12 meses após sua\nprimeira manifestação. Sua incidência depende da idade e do sexo. Dadas as afirmativas sobre o\nassunto, I. No primeiro ano de vida, é mais comum em meninos do que em meninas; II.\nEspecialmente em neonatos febris nos primeiros dois meses de vida, ocorre mais em meninos; III.\nNa fase pré-púbere, a incidência muda, com maior ocorrência em meninas. Verifica-se que está(ão)\ncorreta(s):","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"I e II, apenas.","E":"I, II e III."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134337","number":"134337","sourceNumber":"134337","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente jovem de 25 anos de idade se queixa de odinofagia e febre. Ao exame,\napresenta placas purulentas nas tonsilas.\nRecebe tratamento com penicilina oral, não ocorrendo\nmelhora em três dias. Podemos, assim, solucionar o quadro infeccioso com a seguinte conduta\nambulatorial, assinale-a:","options":{"A":"Amoxacilina.","B":"Ampicilina.","C":"Cefalexina.","D":"Penicilina benzatina."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-131419","number":"131419","sourceNumber":"131419","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um lactente de 8 meses apresenta-se com diarreia há 2 dias. A dieta para essa criança\ndeve ser:","options":{"A":"Normolipídica.","B":"Hipolipídica.","C":"Hipoproteica.","D":"Hiperproteica.","E":"Hipoglicídica."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-131422","number":"131422","sourceNumber":"131422","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente dá entrada no serviço de emergência com quadro de diarreia há 3 dias. Ao\nexame físico constata-se que ele está\ndesidratado. Após a introdução da TRO observa-se aumento\nda frequência e do volume das fezes. Sua conduta é:","options":{"A":"Concentrar a TRO;","B":"Continuar com a TRO;","C":"Iniciar a hidratação venosa;","D":"Iniciar anti-diarréico;","E":"Iniciar antibiótico oral;"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134864","number":"134864","sourceNumber":"134864","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um menino de 9 anos apresenta, há cerca de 4 meses, prurido e edema nos lábios e\nno palato que se resolvem espontaneamente em\ncerca de 2 horas. O quadro relaciona-se com a\ningestão de maçãs, descascadas ou não. Esse tipo de reação alimentar é chamado de:","options":{"A":"Esofagite eosinofílica.","B":"Anafilaxia.","C":"Síndrome alérgica oral.","D":"Intolerância alimentar."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134342","number":"134342","sourceNumber":"134342","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um pré-escolar de 3 anos apresenta quadro clínico compatível com aspiração de corpo\nestranho. Dos sintomas a seguir, qual sugere esse diagnóstico?","options":{"A":"Prostração.","B":"Súbito aparecimento de chiado.","C":"Tosse noturna.","D":"Assimetria torácica."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134884","number":"134884","sourceNumber":"134884","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 4 anos, portadora de fibrose cística, é trazida pela mãe ao Posto de\nSaúde para consulta de rotina. O que devemos\nprescrever para essa criança?","options":{"A":"Suplementação com vitaminas A, D, E e K.","B":"Dieta com 50% a 60% de carboidratos.","C":"Dieta com valor calórico em torno de 85% do requerimento basal.","D":"Suplementação de vitaminas lipossolúveis A, B, C e K."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134037","number":"134037","sourceNumber":"134037","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Escolar de 6 anos, com asma, é avaliado pelo Pediatra em consulta de revisão pós-alta\nhospitalar há 4 semanas, por crise. A criança tem apresentado, nas últimas 4 semanas, sintomas\nnoturnos, limitação das atividades e sintomas diurnos 3 vezes por semana. Segundo as diretrizes\nda Sociedade Brasileira de Pneumologia e Tisiologia, o caso clínico se trata de asma:","options":{"A":"Controlada.","B":"Não controlada.","C":"Parcialmente controlada.","D":"Controlada, se os sintomas noturnos forem menores ou iguais a 2 por semana."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134039","number":"134039","sourceNumber":"134039","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"No Brasil, durante o período de inverno, o uso de oseltamivir está indicado na seguinte\nsituação. Assinale-a.","options":{"A":"Lactente febril há 3 dias com coriza e tosse úmida.","B":"Lactente afebril com tosse rouca, sem coriza e tiragem.","C":"Escolar com febre alta, tosse seca e taquidispneia há 24 horas.","D":"Pré-escolar com febre há 48 horas, coriza hialina, tosse e cefaleia."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-110592","number":"110592","sourceNumber":"110592","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente dá entrada no serviço de emergência com quadro de diarreia há 3 dias. Ao\nexame físico constata-se que ele está\ndesidratado. Após a introdução da TRO, observa-se aumento\nda frequência e do volume das fezes. Sua conduta é:","options":{"A":"concentrar a TRO;","B":"continuar com a TRO;","C":"iniciar a hidratação venosa;","D":"iniciar antidiarreico;","E":"iniciar antibiótico oral."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-110616","number":"110616","sourceNumber":"110616","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Mãe traz seu filho com uma semana de vida para consulta, em aleitamento materno\nexclusivo. A queixa é a de que ?toda vez que mama, evacua?. Sua conduta é:","options":{"A":"Suspender o aleitamento, dar soro oral e agendar retorno em 24 horas.","B":"Suspender o aleitamento materno e prescrever uma fórmula isenta de lactose;","C":"Trocar o aleitamento materno para o leite de vaca diluído acrescido de creme de arroz;","D":"Manter o aleitamento materno e prescrever soro oral no intervalo das mamadas;","E":"Manter o aleitamento materno e tranquilizar a mãe."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-110582","number":"110582","sourceNumber":"110582","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Pré-escolar de seis anos de idade chega ao pronto-socorro em crise asmática de início\nhá três horas, após aula de natação.\nAvaliação inicial: FR = 36 irpm, FC = 124 bpm, tiragem\nintercostal de grau moderado, sibilos pulmonares generalizados. A conduta terapêutica de alívio a\nser tomada é:","options":{"A":"Corticoide por via inalatória.","B":"Aminofilina IV.","C":"Beta-2-agonista de curta duração via inalatória.","D":"Corticoide IV.","E":"Beta-2-adrenérgico IV."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-109999","number":"109999","sourceNumber":"109999","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Todas as alternativas são causas de dor torácica em crianças, EXCETO:","options":{"A":"asma.","B":"costocondrite.","C":"pericardite.","D":"infecção respiratória superior."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-109811","number":"109811","sourceNumber":"109811","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 1 mês, em aleitamento materno exclusivo, é atendido no posto de saúde\ncom história de tosse, febre baixa e recusa\nalimentar que piorou nas últimas 24 horas. Ao exame,\napresenta FR = 40 irpm; sem tiragem; temperatura axilar de 37,9ºC. Qual é a MELHOR conduta\npara esse paciente, segundo as normas do Ministério da Saúde?","options":{"A":"Encaminhar lactente imediatamente para o hospital.","B":"Prescrever sintomáticos e rever em 48 horas.","C":"Complementar o aleitamento materno com fórmula láctea e rever em 24 horas.","D":"Prescrever sulfametoxazol + trimetoprima e rever em 48 horas."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-110004","number":"110004","sourceNumber":"110004","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual dos alimentos abaixo NÃO é um alérgeno alimentar comum?","options":{"A":"Ovo.","B":"Leite.","C":"Amendoim.","D":"Chocolate."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-109815","number":"109815","sourceNumber":"109815","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual é a sequência ADEQUADA para tratamento do Estado de Mal Asmático (Asma\nAguda Grave) em Pediatria?","options":{"A":"Inalação contínua, corticoide endovenoso, terbutalina endovenosa, sulfato de magnésio e heliox.","B":"Aminofilina, corticoide endovenoso, inalação contínua, terbutalina endovenosa e heliox.","C":"Inalação contínua, corticoide inalatório, aminofilina, terbutalina subcutânea e sulfato de\nmagnésio.","D":"Inalação contínua, terbutalina subcutânea, sulfato de magnésio e aminofilina."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-110008","number":"110008","sourceNumber":"110008","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A única medida preventiva para alergia a ácaros da poeira é:","options":{"A":"cobertura plástica do colchão.","B":"aspiração frequente do pó dos carpetes.","C":"borrifar inseticida no carpete.","D":"uso de filtro eletrônico de ar."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-110011","number":"110011","sourceNumber":"110011","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente de 12 anos de idade, com asma grave, foi admitido na sala de emergência por\nexacerbação aguda de asma e foi tratado com várias medicações, inclusive albuterol nas últimas\n24h. Você está preocupado que ele possa ter sintomas relacionados com a toxicidade do albuterol.\nQual dos seguintes NÃO é um efeito colateral do albuterol inalado?","options":{"A":"Tremor muscular.","B":"Hipotensão.","C":"Hipocalemia.","D":"Taquicardia."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-109735","number":"109735","sourceNumber":"109735","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de três anos de idade apresenta sibilos expiratórios em ambos os pulmões, Tax\n39°C, FR 48 irpm. Após tratamento com broncodilatador administrado por via inalatória, em três\nsessões com intervalos de 20 minutos, e antitérmico, o menor mostrou melhora da sibilância, mas\nmanteve FR 48irpm e apresentou tiragem intercostal, Tax 39°C, alteração do nível de consciência e\nFC 130bpm. Das observações clínicas apresentadas no texto acima, aquela que determina a\nnecessidade de internação imediata do paciente é:","options":{"A":"a tiragem intercostal.","B":"a frequência cardíaca.","C":"o nível de consciência.","D":"a frequência respiratória."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-109745","number":"109745","sourceNumber":"109745","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Avalie as afirmativas e marque (V) para as afirmaçõesVerdadeiras ou (F) para as\nFalsas. ( ) A aminofilina é a droga de\nprimeira escolha na abordagem da crise asmática aguda; ( )\nA hipocalemia é um efeito colateral esperado pela utilização de beta 2 agonistas em altas doses; ( )\nO brometo de ipatrópio tem ação broncodilatadora semelhante aos beta 2 agonistas, podendo ser\nutilizado sozinho no manejo da asma aguda; ( ) Frequência Respiratória de sessenta incursões\nou mais em criança de qualquer faixa etária é indicação inquestionável de internação; ( )\nInternação por bronquiolite, pelo menos três episódios de sibilância nos primeiros seis meses de\nvida, dermatite atópica e história familiar de asma constituem critérios preditivos de\ndesenvolvimento de asma. Assinale a sequência CORRETA.","options":{"A":"F / V / V / V / V.","B":"F / V / F / V / V.","C":"V / V / F / F / V.","D":"F / F / V / V / F."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-110027","number":"110027","sourceNumber":"110027","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma menina de 3 anos de idade apresenta histórico de dores abdominais associadas à\ncólicas e diarreia aquosa há 2 dias. Apresentou convulsão breve generalizada e foi hospitalizada.\n\nApós 24h de internação, a diarreia torna-se profusa e com sangue. O agente causador mais\nprovável da gastroenterite da menina é:","options":{"A":"E. coli O157:H7.","B":"C. jejuni.","C":"Shigella sonnei.","D":"Salmonella."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-109751","number":"109751","sourceNumber":"109751","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Marque (V) para as proposições Verdadeiras ou (F) para as Falsas e, em seguida,\nassinale a sequência CORRETA: ( ) A\nbronquiolite viral aguda tem sempre boa resposta ao\ntratamento com broncodilatador inalatório e corticoterapia sistêmica, sendo esse o tratamento\nde escolha; ( ) Nas bronquiolites virais agudas o único tratamento que realmente tem comprovação\nde eficácia na literatura é o uso de oxigênio umidificado de acordo com a tolerância da criança; ( )\nOs derrames pleurais parapneumônicos são complicações frequentes da bronquiolite viral aguda\ne requerem conduta expectante; ( ) O corticoide de escolha na crise asmática aguda é a\nmetilprednisolona; ( ) O RX contrastado de Estômago, Esôfago e Duodeno com pesquisa de\nRefluxo Gastroesofágico (EED) é método diagnóstico de baixa sensibilidade e especificidade não\nsendo necessário na suspeita de DRGE em criança sibilante, caso disponhamos de método\nlaboratorial melhor.","options":{"A":"F / V / F / V / F.","B":"F / F / F / F / F .","C":"F / V / V / V / F.","D":"V / V / F / V / F."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-158440","number":"158440","sourceNumber":"158440","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A síndrome do bebê sacudido compreende:","options":{"A":"Situação em que foi utilizada a força física de forma acidental praticada por outra criança\ndurante\numa brincadeira.","B":"Situação em que foi utilizada a força física de forma intencional, não acidental, praticada\nprovavelmente por um responsável pela criança.","C":"Negligência, um ato extremo de omissão, e deve-se ter cuidado ao imputar intenção ao evento.","D":"Maus tratos psicológicos, que podem causar danos ao desenvolvimento físico e psíquico da\ncriança.","E":"Criança espancada, pois são observados ferimentos inusitados que devem ser comprovados por\nradiografias."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-158394","number":"158394","sourceNumber":"158394","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa CORRETA. O acidente responsável pelo maior número de casos\nde mortalidade em crianças menores de cinco anos\né:","options":{"A":"A intoxicação aguda.","B":"O afogamento.","C":"A queimadura.","D":"O automobilístico.","E":"A queda."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108607","number":"108607","sourceNumber":"108607","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Na diferenciação entre regurgitação infantil e doença do refluxo gastroesofágico em\nlactentes menores de 6 meses de idade, o aspecto mais importante é:","options":{"A":"A eliminação de refluxo pelo nariz.","B":"A repercussão no crescimento e desenvolvimento.","C":"A aparência do material regurgitado.","D":"A relação dos episódios com a alimentação.","E":"A frequência dos episódios."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108615","number":"108615","sourceNumber":"108615","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Com relação ao tratamento da giardíase, qual destas medicações não indicada:","options":{"A":"Albendazol.","B":"Tinidazol.","C":"Secnidazol.","D":"Metronidazol.","E":"Prazinquantel."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108617","number":"108617","sourceNumber":"108617","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente de 6 anos chega ao consultório, com a mãe dizendo as seguintes queixas.\n\n?Dr, meu filho geralmente fica cansado 2 vezes por semana, falta escola de vez enquanto por\ncausa disso, quando corre muito também fica\ncansado, só melhora com o aerossol passado na\nemergência, e é a noite que geralmente piora?. Com base nisso você classificaria ele como:","options":{"A":"Crise de asma intermitente.","B":"Crise de asma persistente leve.","C":"Crise de asma persistente moderada.","D":"Crise de asma persistente grave.","E":"Portador de fibrose cística."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-327255","number":"327255","sourceNumber":"327255","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente do sexo masculino, 4 anos, é trazido pela mãe ao pronto atendimento após\nesta observar \"sangue na urina\". O paciente não\napresenta história de dor, febre ou trauma\nabdominal recente. Ao exame físico, o paciente se encontra em BEG, normocorado, eupneico e\nafebril, mas chama a atenção uma P.A.: 140x100mmHg. Seu exame cardiorrespiratório é normal. À\npalpação abdominal, observa-se massa palpável, de consistência firme, não móvel, de cerca de\n15cm, em flanco esquerdo. Hemograma e ionograma sem alteração. O EAS evidencia de 15\nhemácias por campo de microscopia. Sobre o caso descrito, assinale a alternativa INCORRETA:","options":{"A":"Já que não há sinais de choque, comprometimento agudo e significativo do estado geral e\nausência de história de trauma, a investigação deste paciente pode ser ambulatorial.","B":"Imagem de massa sólida ou mista, em loja renal, com distorção pielocalicial à TC de abdome é\ncompatível com o caso clínico descrito.","C":"Após estadiamento tumoral, na ausência de metástases a distância e envolvimento vascular, a\nressecção da massa tumoral seguida de quimioterapia adjuvante pode corresponder proposta\nterapêutica adequada.","D":"Caso sejam observadas elevadas titulações de alfa-feto proteína, haverá indicação de\nquimioterapia neoadjuvante."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-327285","number":"327285","sourceNumber":"327285","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em qual das cardiopatias a seguir, pode ser observado hipoxemia grave:","options":{"A":"Coarctação da Aorta - CoA","B":"Transposição de Grandes Artérias - TGA","C":"Comunicação Intraventricular - CIV","D":"Persistência de Canal Arterial - PCA"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-327298","number":"327298","sourceNumber":"327298","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Pré-escolar 2 anos, sexo feminino com história de febre, irritabilidade, atraso no\ncrescimento, dor ósseo, proptose orbital, equimose periorbitarias. Exame físico: Hipocorado,\nhematócrito: 29%, Velocidade Hemossedimentação: 85mm, Rx de tórax, massa volumosa no\nmediastino posterior de contornos irregulares com calcificações. Esse quadro é sugestivo de:","options":{"A":"Tuberculose ganglionar","B":"Pneumonia","C":"Neuroblastoma","D":"Cisto broncogênico"},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-298261","number":"298261","sourceNumber":"298261","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um pai traz sua filha de 3 anos à consulta por adinamia, perda de apetite e aumento\nprogressivo de abdômen há algumas semanas.\nApresenta vômitos há 1 dia. Exame físico com\npalidez, proptose, descoloração periorbital e massa abdominal grande e irregular ao longo do flanco\nesquerdo, cruzando a linha média. Sinais vitais e restante do exame físico normal. Qual o\ndiagnóstico mais provável?","options":{"A":"Osteossarcoma","B":"Neuroblastoma","C":"Rabdomiossarcoma","D":"Linfoma"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-298266","number":"298266","sourceNumber":"298266","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menina de 13 anos apresenta hipertensão arterial (aferida no membro superior direito),\ndiminuição da amplitude dos pulsos femorais e dificuldade de palpar os pulsos tibiais anteriores e\nposteriores. Mantém saturação arterial acima de 95% nos membros superiores e inferiores, sem\ndiferença significativa entre eles. Raio x de tórax: presença do sinal de Röesler (desgaste das\nbordas inferiores das costelas). O adolescente é portador de:","options":{"A":"Interrupção da aorta","B":"Coarctação da aorta","C":"Estenose aórtica valvar","D":"Estenose aórtica supravalvar"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-298267","number":"298267","sourceNumber":"298267","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 10 meses com história de febre alta nos últimos três dias (3 episódios ao\ndia), com irritabilidade e discreta\ndiminuição do apetite. Logo após o desaparecimento do último\npico febril, passou a apresentar rash maculopapular, que começou no tronco e evoluiu para cabeça\ne membros. A principal hipótese diagnóstica é:","options":{"A":"Exantema súbito por Parvovírus B-19.","B":"Roseola infantum por Varicela Zoster.","C":"Escarlatina por Streptococcus beta hemolítico do grupo A.","D":"Exantema súbito por Herpes 6 e 7"},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-286730","number":"286730","sourceNumber":"286730","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente do sexo masculino, 5 anos de idade, apresenta quadro de dor em abdome\nsuperior de leve intensidade há 6 meses,\nquando a mãe palpou um ?caroço na barriga? em\nHipocôndrio Direito(HD) . Nega vômitos, febre e demais queixas. Ao exame físico o paciente se\nencontrava em Bom Estado Geral, discretamente emagrecido, hipocorado +/4, anictérico, afebril,\nhemodinamicamente estável. Seu abdome é atípico, plano, flácido, discretamente doloroso em HD,\ncom hepatomegalia palpável a 5cm do rebordo costal. Baço não palpável. À USG, observamos\nfígado com ecogenicidade usual apresentando volumosa massa sólida em lobo direito. Sobre a\ncondução do caso, assinale a alternativa INCORRETA:","options":{"A":"O próximo passo na investigação desse paciente é a tomografia computadorizada de abdome e\ntórax.","B":"A ressecção da neoplasia se torna mais factível por tratar-se de fígado não-cirrótico.","C":"Frequentemente indica-se quimioterapia neoadjuvante para o caso acima.","D":"Esperamos observar baixos níveis de alfa-fetoproteína no perfil laboratorial deste paciente."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-286738","number":"286738","sourceNumber":"286738","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Você é chamado para avaliar uma criança de 2 anos, oriunda do Interior do Estado do\nAmazonas, que foi diagnosticada com um sopro cardíaco pelo médico do posto de saúde local. A\ncriança é eutrófica, está normocorada, acianótica, afebril, ativa, hemodinamicamente estável. A\nmãe refere que a paciente nunca foi internada por quaisquer doenças até o momento. À ausculta\ncardíaca, apresenta sopro pan-sistólico de elevado volume, mais audível na borda esternal inferior\nesquerda. Nesta internação, realizou ecocardiograma transtorácico com doppler que evidenciou\ncomunicação interventricular do tipo membranosa, de pequeno diâmetro, com shunt do ventrículo\nesquerdo para o direito de discreta monta, sem sinais de hipertensão pulmonar detectáveis pelo\nmétodo. Não foram observadas outras máformações cardíacas. Sobre o caso, assinale a alternativa\nINCORRETA:","options":{"A":"Há indicação de correção cirúrgica precoce, devido ao elevado risco de hipertensão pulmonar\nprogressiva e endocardite infecciosa.","B":"Em conjunto com a comunicação interatrial, compõem as má-formações cardíacas mais comuns\ne geralmente apresentam bom prognóstico quando\ndetectadas e tratadas adequadamente.","C":"A radiografia de tórax e o eletrocardiograma provavelmente não trariam informações adicionais\nrelevantes para o caso.","D":"Comunicações interventriculares de maior diâmetro podem evoluir com progressiva disfunção\nventricular e cianose."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-286766","number":"286766","sourceNumber":"286766","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A hipertensão arterial secundária em uma criança de 3 anos tem como principal causa:","options":{"A":"Alterações vasculares","B":"Doenças cardiológicas","C":"Endocrinopatias","D":"Anormalidades renais"},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-252270","number":"252270","sourceNumber":"252270","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menina de 2 anos de idade está internada em enfermaria de pediatria por quadro de\nfebre a esclarecer há 2 dias. O exame de Hemocultura apresenta diplococos gram negativos em\nidentificação. A infecção por qual agente é a hipótese etiológica principal?","options":{"A":"Neisseria meningitidis.","B":"Streptococcus pneumoniae.","C":"Escherichia coli.","D":"Staphylococcus aureus."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-252271","number":"252271","sourceNumber":"252271","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menina, 4a, previamente hígida, chega ao seu consultório com história de três dias com\nmal-estar e febre, sendo que há um dia iniciou com lesão avermelhada na pele. Exame: FC=\n90bpm, FR= 20irpm, lesões eritematosas nas regiões zigomáticas, preservando região central da\nface e exantema reticulado em tronco e extremidades. Qual agente etiológico corresponde ao\nquadro clínico descrito?","options":{"A":"Herpes vírus 6 e 7","B":"Coxsackievirus A16 e A10","C":"Vírus do sarampo","D":"Parvovírus B19"},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-208428","number":"208428","sourceNumber":"208428","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente do sexo masculino, 4 anos sua mãe refere que sua urina estava avermelhada\ne suspeita de sangue na urina, levando-a à\nconsulta médica. Nega história recente de trauma\nabdominal. O paciente está em bom estado geral, eupneico, afebril, normocorado e normotenso. Ao\nexame físico, observou-se massa sólida, imóvel e indolor, de cerca de 15 cm, localizada em flanco\ndireito. Nega alterações do hábito intestinal, demais sintomas urinários e icterícia. Seu hemograma\ne ionograma são normais. O EAS revelou 50 hemácias por campo. Assinale a alternativa\nCORRETA:","options":{"A":"A presença de calcificações à radiografia simples de abdome já indica tratamento cirúrgico sem\na necessidade de outros exames de imagem.","B":"Apesar da ultrassonografia ser o primeiro exame de imagem indicado, a tomografia de abdome e\ntórax poderá fechar o diagnóstico e estadiar o caso.","C":"A ureterolitotomia endoscópica deve ser realizada em caráter urgente para esse paciente,\nindicada pela iminente perda da função do rim direito.","D":"A nefrectomia é o tratamento curativo (caso aplicável) de escolha para este paciente já que nem\na quimioterapia nem a radioterapia são\ntratamentos coadjuvantes com resposta satisfatória."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-208388","number":"208388","sourceNumber":"208388","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O Sarampo é uma doença infecciosa exantemática aguda, transmissível e\nextremamente contagiosa. As manchas de Koplik são o sinal patognomônico do sarampo,\naparecendo no período de:","options":{"A":"3 - 7 dias antes do início da erupção.","B":"1 - 4 dias antes do início da erupção.","C":"2 - 4 dias antes do início da erupção.","D":"1 - 10 dias antes do início da erupção."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-208399","number":"208399","sourceNumber":"208399","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente com nove meses vem ao pronto-socorro acompanhado de sua mãe. Ela está\nmuito angustiada, pois é a segunda vez em menos de 5 dias que eles comparecem ao serviço. Mãe\nrelata que seu filho apresentou febre de 39°C, discreto edema periorbitário e irritabilidade por 3\ndias. Na ocasião, foi avaliado pelo plantonista do dia e liberado com sintomáticos e orientações\npara sinais de alarme. Hoje, no quinto dia de evolução da doença, surgiu exantema maculopapular\nna face e tronco, porém, já não há mais febre no período do exantema. A etiologia mais provável\npara o caso é:","options":{"A":"Coxsackievírus.","B":"Parvovírus B19.","C":"Herpesvírus humano tipo 6.","D":"Estreptococos do grupo A."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-176039","number":"176039","sourceNumber":"176039","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Júlia tem um ano e meio de idade e pesa 14 kg. Você fará recomendações para\nprevenção de injúrias não intencionais em\nacidentes de transporte, sendo a criança ocupante de\num automóvel. Assinale a assertiva CORRETA, baseado em orientações da Sociedade Brasileira\nde Pediatria (SBP):","options":{"A":"Utilizar assento infantil, tipo bebê-conforto,\ninstalado de frente para o painel do veículo.","B":"Utilizar assento infantil, tipo cadeirinha,\ninstalado de costas para o painel do veículo.","C":"Utilizar assento infantil, tipo bebê-conforto, instalado de costas para o painel do veículo.","D":"Utilizar assento infantil tipo cadeirinha, instalado de frente para o painel do veículo."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-176076","number":"176076","sourceNumber":"176076","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Genitora chega ao pronto-socorro e refere que sua filha de 6 anos iniciou o quadro de\nerupção cutânea com 24 a 48 horas. Começou em\ntorno do pescoço, espalhando para tronco e\nmembros que clareia à compressão. Geralmente é mais intensa ao longo das pregas dos cotovelos,\naxilas e virilha, com palidez ao redor da boca. Após 3-4 dias desapareceu e em seguida iniciou fase\nde descamação. Considerando esse quadro, o diagnóstico é:","options":{"A":"Rubéola.","B":"Mononucleose.","C":"Eritema infeccioso.","D":"Escarlatina."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-176042","number":"176042","sourceNumber":"176042","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"João tem dois anos de idade, foi levado ao pronto-socorro pediátrico. A mãe relata\nfebre de 10 dias, congestão conjuntival\nbulbar bilateral geral, sem exsudato, eritema de mucosa\noral e faríngea com língua ?em morango? e lábios secos e fissurados, eritema e edema de mãos e\ndos pés, linfoadenopatia cervical unilateral não supurativa. O diagnóstico provável é:","options":{"A":"Ehlers-Danlos.","B":"Cardiopatia reumática.","C":"Doença de Kawasaki.","D":"Poliangeíte com granulomatose."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-151929","number":"151929","sourceNumber":"151929","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de 7 anos apresenta febre alta, calafrio, odinofagia. Após 48 horas evoluiu com\nexantema formado por pápulas eritematosas, puntiformes mais intenso em dobras e pregas\ncutâneas, rubor facil discreto com palidez peribucal e língua com aspecto de framboesa. O\ndiagnóstico mais provável é:","options":{"A":"Eritema infeccioso.","B":"Mononucleose.","C":"Escarlatina.","D":"Rubéola."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-139120","number":"139120","sourceNumber":"139120","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 12 meses é levada ao serviço de emergência com história de 3 dias de\ntosse produtiva e febre. Foi avaliada pelo plantonista, que fez o diagnóstico de pneumonia. Qual\nachado no exame físico que corrobora essa hipótese?","options":{"A":"Sibilos inspiratórios e expiratórios.","B":"Taquipneia.","C":"Rinorreia.","D":"Meningismo."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-129757","number":"129757","sourceNumber":"129757","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 6 semanas de vida com vômitos em jato após alimentação. No exame\nabdominal, verifica-se uma massa abdominal em\nforma de azeitona. Qual das afirmativas a seguir é\nverdadeira?","options":{"A":"É provável que ele apresente acidose metabólica.","B":"Essa condição é mais comum em bebês do sexo feminino.","C":"Ele deverá reiniciar alimentação após cessação de vômitos.","D":"É provável que ele apresente alcalose metabólica hipoclorêmica."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-129779","number":"129779","sourceNumber":"129779","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um menino de 2 anos é atendido no serviço de saúde após seus pais relatarem uma\n\"noite difícil\". Em continuação a alguns\ndias de sintomas respiratórios superiores leves, mas sem\nfebre, na noite passada ele manifestou um episódio de estridor e aumento de esforço respiratório. A\ncriança já apresentou esses sintomas duas vezes nos dois últimos meses, ficando bem após cada\nepisódio. No intervalo entre crises, ele encontra-se normal. Hoje, exceto pela rinorreia discreta,\nseu\nexame físico está normal. Qual das opções a seguir é a etiologia mais provável?","options":{"A":"Compressão extraluminal da traqueia por tumor.","B":"Aspiração de corpo estranho.","C":"Traqueomalácia.","D":"Crupe espasmódico."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-129805","number":"129805","sourceNumber":"129805","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 15 meses passou em consulta no pronto-socorro e foi feito diagnóstico de\notite média aguda à direita. Iniciou tratamento com amoxicilina na dose de 50 mg/kg/dia. Fez uso\ncorreto por 3 dias, quando apresentou novo quadro febril, abaulamento de região retroauricular\ndireita, com dor local e eritema. A conduta mais indicada nesse momento:","options":{"A":"Dobrar a dose da amoxicilina e pedir retorno em 48h.","B":"Substituir amoxicilina por macrolídeos e solicitar TC de crânio.","C":"Substituir amoxicilina por cloranfenicol.","D":"Internar e iniciar antibioticoterapia endovenosa."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-107574","number":"107574","sourceNumber":"107574","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma gestante chega para uma consulta pré-natal. Qual das opções a seguir representa\na instrução que deverá constar do seu\naconselhamento como Pediatra da família para reduzir os\nriscos de Síndrome da Morte Súbita do Lactente (SMSL)?","options":{"A":"Reduzir a exposição do lactente a fumaça de cigarro e sempre colocar a criança em decúbito\ndorsal para dormir.","B":"Manter sempre o bebê em posição Prona.","C":"Evitar o contato com pessoas doentes com diarreia.","D":"Administrar vitaminas e minerais."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-107583","number":"107583","sourceNumber":"107583","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A mãe informa que o filho de 4 anos de idade está com \"coceira nas nádegas\". Ela traz\namostra de fezes para inspeção. Nas fezes estão presentes alguns vermes de 15 a 20 cm de\ncomprimento, arredondados e esbranquiçados. Você iniciaria o tratamento com:","options":{"A":"Amoxicilina.","B":"Mebendazol.","C":"Praziquantel.","D":"Niclosamida."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-107628","number":"107628","sourceNumber":"107628","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma menina de dois anos de idade, antes saudável, apresentou-se com queixa de\nsibilância aguda. Sua mãe nega episódios\nanteriores de sibilância. Não tem história familiar. A mãe\ninformou que deixara a criança brincando no quarto do irmão mais velho e que cerca de 20 minutos\ndepois ela ouviu a filha tossindo e chiando. Qual das opções a seguir será o melhor próximo passo\nna condução clínica?","options":{"A":"Determinar com o quê a criança estava brincando e solicitar uma radiografia de tórax.","B":"Realizar raio X de abdome, hemocultura, urinocultura e determinar internação hospitalar.","C":"Prescrever Predinisona IM e reavaliar com 1 semana no ambulatório.","D":"Prescrever amoxicilina oral e reavaliar com 1 mês no ambulatório."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-107650","number":"107650","sourceNumber":"107650","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A mãe da menor L.M.C. de 2 anos chega no Pronto-Socorro com a criança no colo,\nrelata história de diarreia há mais ou menos 24hs com inúmeras evacuações por dia, fezes de\ncaracterística líquida. Ao examinar a criança, o médico diz para o residente que ela está com\nchoque hipovolêmico, pois apresenta os seguintes sinais clínicos:","options":{"A":"Mucosa úmida, boa perfusão, choro forte.","B":"Alteração no estado mental (torporosa), taquipneia, extremidades frias, oligúria, hipotensão.","C":"Neurológico adequado, criança lúcida e orientada, extremidades quentes.","D":"Alteração no estado mental (chorando pedindo a mãe), eupneica, leve taquicardia, pulsos\ncheios."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-107695","number":"107695","sourceNumber":"107695","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente eutrófico, alimentado somente com leite materno, iniciou quadro de diarreia\nlíquida, há 03 dias, acompanhada de febre e\nvômitos. Evoluindo com taquipneia, diminuição da\ndiurese (oligúria), sonolência. Com sinais de desidratação grave. Após etapa de expansão (3x),\napresentou diurese em pequena quantidade. Colhido os exames observou-se: Na = 115, K = 1,5,\nCa = 0,9, Mg+ = 2, Fósforo = 4 mg/dl. Com relação aos distúrbios hidroeletrolítico devemos\ncorrigir:","options":{"A":"O quadro de Hipofosfatemia e Hipomagnesemia e ambos devem ser corrigidos, pois são\nconsiderados graves e com risco de vida.","B":"Não há distúrbios eletrolíticos para corrigir.","C":"O quadro de Hiponatremia e Hipopotassemia e ambos devem ser corrigidos, pois são\nconsiderados graves e com risco de vida.","D":"Não há necessidade de correção da Hiponatremia."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-107839","number":"107839","sourceNumber":"107839","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"No mundo o número de óbitos por diarreia, na população infantil, é alarmante. Em\nrelação às doenças diarreicas na infância, qual das alternativas está CORRETA?","options":{"A":"O uso de medicações incluindo zinco não reduz a duração e a gravidade do evento diarreico.","B":"A diarreia aguda não apresenta maior gravidade em lactentes jovens e imunodeprimidos.","C":"A diarreia aguda é autolimitada, presumivelmente infecciosa, com duração menor de 14 dias.","D":"O mecanismo osmótico é a principal fisiopatogenia das diarreias agudas causadas por\nEscherichia coli enterotoxogênicas."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-107878","number":"107878","sourceNumber":"107878","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A diarréia crônica (DC) na infância pode ser causada por várias etiologias, Assinale\nabaixo a assertiva onde há correspondência entre a etiologia da DC e métodos de diagnóstico.","options":{"A":"Doença celíaca - diagnóstico clínico.","B":"Fibrose cística - teste de cloro no suor.","C":"Doença intestinal inflamatória - anticorpo anti endomisio.","D":"Síndrome do intestino irritável - enema opaco."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-103854","number":"103854","sourceNumber":"103854","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Pré-escolar 3 anos, chega ao Pronto atendimento com sua genitora que refere coriza,\ndor de garganta e febre. O plantonista diz\nque ela está com faringite. O agente etiológico mais\nprovável é:","options":{"A":"Bartonella henselae.","B":"Vírus herpes simples tipo I.","C":"Estafilococcus.","D":"Adenovírus."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-103870","number":"103870","sourceNumber":"103870","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Escolar de 8 anos deu entrada no pronto atendimento em crise de asma que teve início\nhá 24 horas. A mãe refere que ele tosse,\nestá cansado, com chiado no peito e vomitando. Ao\nexame físico: está lúcido, orientado, acianótico, temperatura axilar 36,7°C; FR: 38 irpm; FC: 119\nbpm; saturimetria 95%; dispneia moderada; com retrações intercostais e sibilos expiratórios. O\ntratamento indicado neste momento é:","options":{"A":"Uso de leucotrienos via oral.","B":"Beta-2-agonista de ação curta por via inalatória.","C":"Aminofilina intravenosa.","D":"Corticoide via oral."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-103783","number":"103783","sourceNumber":"103783","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual o procedimento de escolha para o diagnóstico de megacólon agangliônico\ncongênito (doença de Hirschsprung)?","options":{"A":"RX simples com bário.","B":"Cintilografia.","C":"Ultrassonografia.","D":"Biópsia retal."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-103784","number":"103784","sourceNumber":"103784","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Os vermes adultos de Ascaris lumbricoides habitam no:","options":{"A":"Intestino grosso.","B":"Intestino delgado.","C":"Ceco e cólon ascendente.","D":"Ceco e cólon descendente."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-103822","number":"103822","sourceNumber":"103822","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Pré-escolar apresenta obstrução nasal e tosse produtiva principalmente noturna. Há 10\ndias apresentou infecção de vias aéreas superiores, segundo relato da mãe. Neste caso, qual\ndiagnóstico provável?","options":{"A":"Laringite.","B":"Sinusite.","C":"Traqueíte.","D":"Asma."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-87447","number":"87447","sourceNumber":"87447","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Quanto ao refluxo gastroesofágico na criança é necessário diferenciar a presença ou\nnão de refluxo gastroesofágico patológico.\nAssinale abaixo a assertiva onde NÃO há sinais de\nalerta para refluxo gastroesofágico patológico:","options":{"A":"Retardo no ganho de peso e na estatura.","B":"Episódios de apneia.","C":"Presença de 3 ou mais episódios de regurgitação por dia, por mais de 3 semanas.","D":"Vômitos com conteúdo bilioso.","E":"Anormalidades congênitas de orofaringe."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-81002","number":"81002","sourceNumber":"81002","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Ana de 3 anos chega ao Pronto-Socorro com história prévia de diarreia, inúmeras\nevacuações por dia, fezes de característica\nlíquida. O preceptor diz para o residente que ela está\ncom choque hipovolêmico, pois apresenta os seguintes sinais clínicos:","options":{"A":"Mucosa úmida, boa percussão e choro forte.","B":"Neurológico adequado, criança lúcida, orientada e extremidades quentes.","C":"Diurese clara e abundante, choro fraco, pele fria e eupneica.","D":"Alteração no estado mental (chorando pedindo mãe), eupneica, leve taquicardia e pulsos cheios.","E":"Alteração no estado mental (torporosa), taquipneia, extremidades frias, oligúria e hipotensão."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-81013","number":"81013","sourceNumber":"81013","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Maria de 35 dias é atendida no pronto-socorro com quadro de bronquiolite viral aguda.\nMãe relata prematuridade de 35 semanas, AIG,\nnão necessitando de cuidados ventilatórios. Exame\nfísico: regular estado geral, dispneica, FR: 82 irpm, sem tiragem ou batimento de aletas nasais, MV\npresente e diminuído universalmente, com sibilos esparsos. Exames complementares: saturação de\nO2 de 95% em repouso; radiografia de tórax: pulmões hiperinsuflados com reforço da trama\nbroncovascular. O pediatra assistente decide pela internação hospitalar. As alterações clínicas ou\nlaboratoriais que determinaram essa decisão foram:","options":{"A":"Radiografia do tórax e idade.","B":"Estado geral e prematuridade.","C":"Saturação de O2 e prematuridade.","D":"Idade e FR elevada.","E":"Radiografia de tórax e saturação de O2."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-80988","number":"80988","sourceNumber":"80988","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Escolar de dez anos é levado ao pronto-socorro em crise de asma iniciada na noite\nanterior. A mãe relata tosse, chiado,\ndispneia e vômitos. Exame físico: lúcido, orientado, acianótico,\ntax 36,4º C, FR 40 irpm, FC: 112 bpm, SaO2: 94%, dispneia leve sem retrações intercostais e\npresença de sibilos expiratórios. O tratamento indicado neste momento é:","options":{"A":"Aminofilina intravenosa.","B":"Adrenalina subcutânea.","C":"corticosteroide via inalatória.","D":"Sulfato de magnésio intravenosa.","E":"ß2- agonistas de ação curta por via inalatória."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-80991","number":"80991","sourceNumber":"80991","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Quais os parasitas mais comumente envolvidos na espoliação do ferro na criança?","options":{"A":"Giardia lamblia e Necator americanus.","B":"Ancylostoma duodenale e Ascaris lumbricoides.","C":"Necator americanus e Ancylostoma duodenale.","D":"Giardia lamblia e Ascaris lumbricoides.","E":"Entamoeba coli e Ancylostoma duodenale."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-80952","number":"80952","sourceNumber":"80952","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A doença diarreica constitui um dos problemas mais graves que afetam a população\ninfantil. Em relação às doenças diarreicas na\ninfância, qual das alternativas está INCORRETA?","options":{"A":"A diarreia aguda é autolimitada com duração menor que 14 dias .","B":"As cepas de Escherichia coli enterotoxigênicas costumam causar diarreia por mecanismo\nsecretor.","C":"A suplementação de zinco durante o episódio de diarreia aguda reduz a duração e a gravidade\ndo evento diarreico.","D":"Pacientes desnutridos, lactentes jovens e imunodeprimidos são pacientes mais suscetíveis a\ndesenvolver quadros graves de diarreia aguda.","E":"O Vibrio cholerae e a Shigella estão comumente associados à síndrome hemolítica urêmica."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-80924","number":"80924","sourceNumber":"80924","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A vacina contra sarampo pode ser aplicada, sem qualquer tipo de contraindicação, no\ncaso de:","options":{"A":"Gravidez no primeiro trimestre.","B":"Estado de imunossupressão grave.","C":"Vacinação recente contra a poliomielite.","D":"Uso de imunoglobulina humana nos últimos 30 dias.","E":"Antecedente de reação anafilática após ingestão de ovo de galinha."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-314287","number":"314287","sourceNumber":"314287","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"é uma vasculite sistêmica de etiologia desconhecida, e uma das\ncausas principais de cardiopatia adquirida na\ninfância, podendo se manifestar na forma de\nmiocardite aguda com insuficiência cardíaca, arritmias, endocardites e pericardites. A alternativa\nque preenche, corretamente, a lacuna do trecho acima é","options":{"A":"Doença de Devic","B":"Síndrome de Weil","C":"Doença de Krabbe","D":"Doença de Kawasaki","E":"Síndrome de Raynaud"},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-281867","number":"281867","sourceNumber":"281867","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre os fatores responsáveis pelo equilíbrio entre o benefício e a lesão gerada pela\nfebre em pacientes internados na UTI pediátrica, assinale a alternativa incorreta.","options":{"A":"Tratamento profilático para resposta inflamatória.","B":"Intensidade da resposta imune.","C":"Reserva fisiológica do paciente.","D":"Estágio e gravidade da infecção."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-281868","number":"281868","sourceNumber":"281868","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considera-se que uma criança de 8 anos está hipotensa quando sua PAS está abaixo\nde:","options":{"A":"70.","B":"82.","C":"86.","D":"90."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215575","number":"215575","sourceNumber":"215575","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"São contraindicações ao uso de ventilação pulmonar não invasiva, em domicílio, todas\nas abaixo, EXCETO:","options":{"A":"Distúrbios de deglutição.","B":"Necessidade de suporte ventilatório contínuo.","C":"Idade abaixo de 1 ano.","D":"Episódios prévios de broncoaspiração."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-181157","number":"181157","sourceNumber":"181157","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação a suspeita de corpo estranho em via aérea, assinale a alternativa correta:","options":{"A":"A manobra de Heimlich é sempre a primeira intervenção.","B":"O exame de imagem não acrescenta informações na investigação.","C":"Se a suspeita for forte, deve ser realizada laringoscopia/ broncoscopia o mais precocemente\npossível.","D":"A aspiração de corpo estranho não ocorre em menores de 3 anos de idade."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-162476","number":"162476","sourceNumber":"162476","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação ao refluxo gastroesofágico na criança, é correto afirmar que:","options":{"A":"A elevação de cabeceira deve ser orientada nos lactentes.","B":"Os exames radiológicos contrastados são padrão-ouro para o diagnóstico do refluxo\ngastroesofágico.","C":"As medidas não farmacológicas, na presença de bom crescimento e ausência de sinais de alerta\ngeralmente, são suficientes para o tratamento do refluxo gastroesofágico.","D":"Os sintomas de vias aéreas superiores, como rouquidão crônica, tosse crônica, sinusites, otites\nmédias de repetição ou crônicas e hiperemia de laringe têm forte associação com o refluxo\ngastroesofágico.","E":"O tratamento com procinéticos deve ser iniciado de forma empírica para crianças com vômitos e\nregurgitação recorrentes, não sendo necessária investigação prévia para determinar se há doença\ndo refluxo gastroesofágico."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-157719","number":"157719","sourceNumber":"157719","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Analise estas patologias; I. Infecções virais; II. Gastroenterites; III. Cálculo biliar.\nAs\nprincipais causas de dor abdominal, na emergência pediátrica, estão relacionadas às patologias\ncontidas em:","options":{"A":"I, II e III.","B":"II e III, apenas.","C":"I e III, apenas.","D":"I e II, apenas."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-157727","number":"157727","sourceNumber":"157727","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Quais alterações a criança com estenose hipertrófica do piloro apresenta?","options":{"A":"Alcalose metabólica e hipocloremia.","B":"Vômitos biliosos e letargia.","C":"Vômitos biliosos e acidose metabólica.","D":"Letargia e hipercloremia."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-157756","number":"157756","sourceNumber":"157756","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual das seguintes medicações está associada à pancreatite aguda, em crianças?","options":{"A":"Clindamicina.","B":"Furosemida.","C":"Insulina simples.","D":"Ácido valproico."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134692","number":"134692","sourceNumber":"134692","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa CORRETA:","options":{"A":"A bronquiolite viral aguda ocorre, exclusivamente, em pacientes menores de 2 anos de idade.","B":"Cerca de 50% das crianças com menos de 2 anos de idade são infectadas pelo Vírus Sincicial\nRespiratório (VSR).","C":"A mortalidade da bronquiolite está em torno de 15% dos casos.","D":"O VSR pode sobreviver por várias horas nas mãos e na superfície."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-139763","number":"139763","sourceNumber":"139763","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Ao atender uma criança de 4 anos de idade, previamente hígida, que no meio da noite\niniciou quadro de tosse rouca e dispneia inspiratória, ao exame físico, apresenta-se afebril,\nsudorese fria, taquicárdica e discreta cianose perioral. A ausculta pulmonar apresenta murmúrio\nvesicular universalmente presente em ambos os hemitórax. Referente a esse caso, marque a\nalternativa que apresenta a MELHOR conduta imediata?","options":{"A":"Nebulização com oxigênio.","B":"Nebulização com beta-2-adrenérgico.","C":"Hidratação venosa e antibioticoterapia.","D":"Ventilação por tubo orotraqueal."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134715","number":"134715","sourceNumber":"134715","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Doença mão-pé-boca e Herpangina são diagnósticos de doenças relacionadas a:","options":{"A":"Herpes-vírus 6.","B":"Parvovírus.","C":"Enterovírus.","D":"Togavírus."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134759","number":"134759","sourceNumber":"134759","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Com relação às cólicas do lactente, aponte a alternativa INCORRETA:","options":{"A":"A prevalência varia de 10 a 30% em todo o mundo.","B":"Alguns estudos mostram uma incidência maior quando a criança é o primeiro filho.","C":"Quanto ao sexo, mostra uma prevalência maior em meninos.","D":"Prematuros têm um atraso no tempo de aparecimento das cólicas."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134768","number":"134768","sourceNumber":"134768","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual alternativa NÃO faz parte dos critérios de Wessel para cólicas do lactente ou\n\n?regra dos 3??","options":{"A":"Paroxismos de irritabilidade, agitação e choro.","B":"Surgem a qualquer hora do dia.","C":"Duração de pelo menos 3 horas/dia por mais de 3 dias na semana por, pelo menos, 3 semanas.","D":"Desaparecimento aos 3 meses de idade."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134781","number":"134781","sourceNumber":"134781","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere os itens que contêm os preditores de Bronquiolite Grave. I. Baixo peso ao\nnascer. II. Presença de fumo passivo. III. Atelectasias aos Raios X de tórax. É CORRETO, o\ncontido em:","options":{"A":"I, apenas.","B":"II, apenas.","C":"III, apenas.","D":"I, II e III."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134782","number":"134782","sourceNumber":"134782","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Acompanhando as cólicas do lactente podem ocorrer, concomitantemente,\ndistúrbios gastrointestinais leves. Dentre eles, o MAIS\nfrequente, segundo estudos\nobservacionais, é:","options":{"A":"A regurgitação.","B":"A constipação intestinal.","C":"O vômito.","D":"A diarreia."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-139788","number":"139788","sourceNumber":"139788","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente, 8 meses de idade, com quadro de diarreia líquida há 2 dias (média de 8\nepisódios por dia), apresentando vômitos nas últimas horas. A mãe relata ter observado muco e\nraias de sangue nas fezes. Ao exame físico, está em regular estado geral, irritado, olho fundo e\nsem lágrimas, boca seca e preenchimento capilar lentificado (5 segundos). Sobre a terapêutica de\nreidratação, segundo as orientações da OMS/MS, aponte a alternativa em quea afirmação esteja\nINCORRETA.","options":{"A":"Crianças com sinais de choque devem ter seu volume restaurado com a infusão inicial de soro\nfisiológico ou ringer lactato na dose de 10 ml/kg/hora.","B":"Plano A ? está indicado para pacientes que não apresentam sinais de desidratação,\nfornecendo SRO após cada evacuação líquida.","C":"Plano B ? indicado para pacientes com alguns sinais de desidratação, oferecendo SRO\nfrequentemente eem doses pequenas,\n\ncorrespondendo a um volume ingerido de 50 a 100 ml/kg ao final de 4 a 6 horas.","D":"Plano C ? indicado para crianças que exibem sinais francos de desidratação e persistência dos\nvômitos e diarreia, além daquelas comatosas, com alteração do nível de consciência."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134784","number":"134784","sourceNumber":"134784","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Das alternativas abaixo, qual NÃO é indicador de internação hospitalar?","options":{"A":"FR maior do que 60 irpm.","B":"SpO2 menor do que 95% em ar ambiente.","C":"Letargia.","D":"Pais inábeis em cuidar da criança em casa."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134672","number":"134672","sourceNumber":"134672","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Quantas infecções respiratórias, a criança pode apresentar, em média, por ano?","options":{"A":"2 a 4.","B":"4 a 8.","C":"1 a 3.","D":"3 a 5."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-134699","number":"134699","sourceNumber":"134699","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A Herpangina, infecção comum na infância, tem como agente etiológico, nas formas\nepidêmicas, o vírus:","options":{"A":"Herpes hominis tipo 1.","B":"Herpes hominis tipo 2.","C":"Parainfluenza 3.","D":"Coxsakie A."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-111869","number":"111869","sourceNumber":"111869","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual é a sequência ADEQUADA para tratamento do Estado de Mal Asmático (Asma\nAguda Grave), em Pediatria?","options":{"A":"Inalação contínua, corticoide endovenoso, terbutalina endovenosa, sulfato de magnésio e heliox.","B":"Aminofilina, corticoide endovenoso, inalação contínua, terbutalina endovenosa e heliox.","C":"Inalação contínua, corticoide inalatório, aminofilina, terbutalina subcutânea e sulfato de\nmagnésio.","D":"Inalação contínua, terbutalina subcutânea, sulfato de magnésio e aminofilina."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-111886","number":"111886","sourceNumber":"111886","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de 10 anos é internada com hipótese diagnóstica de pneumonia lobar à direita.\nSegundo história, paciente é previamente hígido, sem internações anteriores, com vacinações em\ndia. Ao exame físico, apresenta-se em regular estado geral, descorado (+/4+), hidratado,\nacianótico, anictérico, taquidispneico leve, consciente e orientado, febril. ACV ? RCR 2T, sem\nsopros. AR ? MVF com estertores crepitantes à direita, estertores subcrepitantes disseminados em\nambos hemitórax. ABDOME ? inocente, ORO ? normal, OTO ? normal. Qual é o antibiótico de\nescolha para esse paciente?","options":{"A":"Vancomicina.","B":"Cefepime.","C":"Eritromicina.","D":"Penicilina cristalina."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-111915","number":"111915","sourceNumber":"111915","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"São situações que contraindicam a terapia de reidratação oral em uma criança com\ndoença diarreica aguda, EXCETO uma. Aponte-a:","options":{"A":"Vômitos frequentes.","B":"Íleo paralítico.","C":"Coma.","D":"Choque hipovolêmico."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-111817","number":"111817","sourceNumber":"111817","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"NÃO é sinal de gravidade na avaliação de pneumonias em crianças:","options":{"A":"febre.","B":"tiragem subcostal.","C":"gemência.","D":"batimentos de asas do nariz."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-350884","number":"350884","sourceNumber":"350884","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Nas consultas de Puericultura, o médico deve estar atento aos sinais precoces de\nalerta para neoplasias na infância. Qual das assertivas abaixo são sinais que devem ser\ninvestigados para o câncer infantil?","options":{"A":"Leucocoria.","B":"Estrabismo verificado ao nascimento.","C":"Sangramento vaginal na adolescência.","D":"Aumento do volume testicular associado a um trauma."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-292848","number":"292848","sourceNumber":"292848","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 3 anos de idade chega ao ambulatório com relatos dos pais de que há\ncerca de três dias vem apresentado sintomas como como enurese, urgência urinária, polaciúria,\ndisúria, incontinência urinária com urina fétida e turva. Qual o diagnóstico ao qual esses sintomas\npodem estar relacionados?","options":{"A":"Cistite aguda.","B":"Pielonefrite aguda.","C":"Presença de ureter ectópico.","D":"Balanopostites e vulvovaginites."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-259740","number":"259740","sourceNumber":"259740","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de seis meses, em acompanhamento com diagnóstico de tetralogia de Fallot,\napresenta quadro súbito de agitação, taquipneia e piora da cianose, seguido de síncope no\ndomicílio. Genitora leva a criança à emergência, sendo atendida por médico que prontamente inicia\noxigenoterapia e posiciona o paciente com os joelhos fletidos sobre o abdome (posição\ngenupeitoral). A conduta utilizada tem como principal objetivo:","options":{"A":"reduzir a resistência vascular pulmonar e sistêmica.","B":"aumentar a resistência vascular pulmonar e sistêmica.","C":"reduzir a resistência vascular pulmonar e aumentar a resistência vascular sistêmica.","D":"aumentar a resistência vascular pulmonar e reduzir a resistência vascular sistêmica."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-259741","number":"259741","sourceNumber":"259741","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 8 anos, previamente hígido, evolui com lesões vesiculares com base\neritematosa em dorso, em área delimitada,\nseguindo trajeto do nervo. Lesões foram precedidas por\ndor moderada. Sem sinais de infecção secundária ou necrose. Nega episódios prévios\nsemelhantes. Diante do quadro apresentado, assinale a terapêutica mais adequada.","options":{"A":"Anestésico tópico / curetagem.","B":"Analgesia/compressas calmantes.","C":"Solução a base de ácido salicílico.","D":"Aciclovir 30 mg/kg /dia dividido em 5 doses."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-259754","number":"259754","sourceNumber":"259754","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 9 meses de idade, desnutrido, é levado para consulta na UBS devido a\nquadro de febre (39°C), tosse, conjuntivite\ne coriza nasal iniciados há 2 dias. No 3° dia houve piora\nda febre e aparecimento de rash cutâneo eritematoso morbiliforme com acometimento inicial da\nface, e posteriormente, pescoço e tronco. Qual o diagnóstico e qual conduta a ser adotada?","options":{"A":"Varicela e aciclovir.","B":"Rubéola e sintomáticos.","C":"Sarampo e vitamina A.","D":"Exantema súbito e sintomáticos."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-234011","number":"234011","sourceNumber":"234011","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Crianc?a, sexo masculino, 2 anos de idade, estava brincando com um irma?o e levou\numa queda da pro?pria altura. Sua ma?e, ao levanta?-la do cha?o, achou que havia uma \"massa\"\nabdominal e resolveu leva?-la a? uma emerge?ncia. Na admissa?o, na?o havia alterac?o?es\nhemodina?micas ou outros sinais cli?nicos de perda vole?mica. Os pais informam que crianc?a\nnascera a termo, de parto normal, com gestac?a?o sem intercorre?ncias, incluindo ultrassom\nmorfolo?gico em terceiro trimestre normal e negaram quaisquer relatos de febre, alterac?a?o do\nha?bito intestinal ou urina?rio, dor ou perda de peso, nos u?ltimos tre?s meses. Ao exame, a\ncrianc?a apresentava-se com bom estado geral, estava ativa e normocorada, pore?m com\npresenc?a de lesa?o endurecida e indolor em hipoco?ndrio direito. Ausculta pulmonar e cardi?aca\nnormais. Sinais vitais sem alterac?o?es. Foi realizada ultrassonografia na urge?ncia que detectou\nlesa?o expansiva retroperitoneal a? direita, na?o sendo possi?vel caracterizar adequadamente rim\nipsilateral e adrenais. O Rx de to?rax revelou no?dulo de 2cm em lobo superior do pulma?o\nesquerdo compati?vel com prova?vel etiologia neopla?sica. Com base na situac?a?o cli?nica\ndescrita, o diagno?stico mais prova?vel e?:","options":{"A":"Tumor de Wilms.","B":"Feocromocitoma.","C":"Neuroblastoma metasta?tico.","D":"Carcinoma de ce?lulas renais."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-234044","number":"234044","sourceNumber":"234044","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente, 10 meses, sexo masculino, é levado à emergência por sua mãe com quadro\nde tosse seca, febre alta e coriza há 5 dias.\nRelata que há 48 horas apareceram \"manchas\nvermelhas em todo o corpo\" e conjuntivite bilateral. Cartão vacinal atualizado até 6 meses de idade.\nIrmã de 7 anos apresentou quadro clínico semelhante há 2 semanas. Ao exame físico: estado geral\nregular, irritado, febril, eupneico, hidratado. Ausência de sinais meníngeos. Ausculta pulmonar e\ncardiovascular normais. Abdome sem alterações. Rash maculopapular generalizado, confluente em\nface e tronco, com enantema difuso de mucosa oral. Diante do quadro clínico apresentado, qual o\ndiagnóstico mais provável?","options":{"A":"Rubéola.","B":"Sarampo.","C":"Exantema súbito.","D":"Doença de Kawasaki."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-234048","number":"234048","sourceNumber":"234048","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"André, 15 meses de idade, é atendido no ambulatório de pediatria com sinusites e\notites frequentes há 8 meses. Infecções de repetição não muito graves que melhoram com\nantibioticoterapia oral. Lactente apresenta crescimento e desenvolvimento normais. Vacinação\natualizada. Nega reações vacinais. Ao exame físico, apresenta tecido linfoide amigdaliano e\ngânglios palpáveis menores que 1,0 cm. Pensando na possibilidade de imunodeficiência, o\ndiagnóstico mais provável é:","options":{"A":"agamaglobulinemia ligada ao x.","B":"hipogamaglobulinemia transitória.","C":"imunodeficiência combinada grave.","D":"síndrome de imunodeficiência adquirida."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-234061","number":"234061","sourceNumber":"234061","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente, 3 meses, é levado a emergência com história de cianose. Mãe refere que\npercebe o bebê \"roxo\" desde o nascimento,\nporém com piora nas últimas semanas, apresentando\ntambém cansaço e palidez durante o choro. Ao exame: cianose central, SatO?: 80%, FC: 140bpm,\nFR: 45irpm. Sopro sistólico discreto. Pulsos palpáveis e simétricos. ECG: sobrecarga ventricular\nesquerda. Radiografia torácica: hipofluxo pulmonar. Diante do quadro clínico e exames\ncomplementes apresentados, qual a cardiopatia congênita mais provável?","options":{"A":"Tetralogia de Fallot.","B":"Hipoplasia do coração esquerdo.","C":"Transposição das grandes artérias.","D":"Atresia pulmonar com septo interventricular íntegro."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-199654","number":"199654","sourceNumber":"199654","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O choque séptico é causa frequente de choque em crianças, e a morbimortalidade\ndessa grave situação pode ser reduzida\nsignificativamente com diagnóstico precoce e tratamento\nadequado. Que tipo de choque, o choque séptico representa?","options":{"A":"Choque hipovolêmico.","B":"Choque cardiogênico.","C":"Choque distributivo.","D":"Choque obstrutivo."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-199644","number":"199644","sourceNumber":"199644","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um recém-nascido foi trazido à emergência duas semanas após a alta da maternidade,\nem choque. O exame físico mostrou ausência de\nsopro cardíaco e ausência de pulsos em membros\ninferiores. O eletrocardiograma exibiu sobrecarga ventricular direita. Qual o diagnóstico mais\nprovável desse bebê?","options":{"A":"Coarctação da aorta.","B":"Tetralogia de Fallot.","C":"Anomalia de Ebstein.","D":"Comunicação interventricular."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-199661","number":"199661","sourceNumber":"199661","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Mãe leva seu filho de 18 meses de idade para atendimento em urgência pediátrica com\nquadro de choro persistente após queda quando brincava no parquinho. Mãe relata que criança\ntem dificuldade de andar e sempre está caindo. Ao exame, a criança era eutrófica, apresentava-se\nassustada, bastante chorosa, com ausculta cardíaca e pulmonar normais, com dor à manipulação\nde membro inferior direito e presença de duas equimoses face medial e posterior da coxa direita. A\nradiografia de membros inferiores evidenciou fratura em metafisária em \"alça de balde\" em região\nde fêmur direito e presença de fratura em tíbia esquerda em consolidação. Diante do quadro acima\ndescrito, qual a melhor conduta?","options":{"A":"Providenciar a imobilização imediata do membro fraturado e encaminhamento para geneticista\npara avaliação e acompanhamento.","B":"Solicitar avaliação do ortopedista para imobilização do membro e posteriormente alta do\npaciente com orientações para cuidados no domicílio.","C":"Acionar o instituto médico legal para avaliação das lesões e providenciar encaminhamento para\ncentro de referência em traumatologia ortopédica infantil.","D":"Solicitar investigação radiológica completa e notificar a suspeita de maus tratos ao Conselho\nTutelar e no Sistema de Informação de Agravos de Notificação."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-173040","number":"173040","sourceNumber":"173040","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um lactente de 3 meses trazido à Unidade Básica de Saúde, apresentando quadro\nclínico compatível com bronquiolite, foi\nradiografado e realizou exames laboratoriais. Ao analisar os\nexames, o médico suspeitou de imunodeficiência primária. Que achado nesses exames fez o\nprofissional levantar essa possibilidade?","options":{"A":"Ausência de imagem tímica na radiografia de tórax.","B":"Leucograma com leucopenia e linfocitose no hemograma.","C":"Proteína C reativa e Velocidade de hemossedimentação elevadas","D":"Hiperinsuflação, opacidade ao redor do hilo pulmonar na radiografia de tórax."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-150818","number":"150818","sourceNumber":"150818","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"No ambulatório, chega uma criança de oito meses de idade com relato de cicatrização\ndeficiente e abscessos profundos na pele,\nrecorrentes. Já tivera, também, ulcerações orais. Qual a\nprincipal suspeita diagnóstica?","options":{"A":"Imunodeficiência predominante dos linfócitos B.","B":"Imunodeficiência predominante dos linfócitos T.","C":"Imunodeficiência predominante do sistema fagocitário.","D":"Imunodeficiência predominante do sistema complemento."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-126954","number":"126954","sourceNumber":"126954","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menina, 10 meses de idade, bem nutrida, é atendida no setor de emergência por choro\nintenso há 6 horas. Face a episódios de movimento das pernas de encontro ao abdome,\n\npercebe-se padrão de cólicas abdominais, com intensidade progressiva e a intervalos cada vez\nmenores. Mãe relata ainda vômitos há 2\nhoras. Ao exame, criança encontra-se alerta,\npermanecendo calma nos intervalos de dor e não apresenta alterações hemodinâmicas ou indícios\nclínicos de choque séptico. Abdome se encontra distendido, sem sinais de peritonite. No toque\nretal: ampola vazia, com muco e sangue. Ultrassonografia de abdome revela alça intestinal com\nmulticamadas visíveis (aparência de um ?alvo?). Hemograma normal. Considerando a hipótese\ndiagnóstica mais provável para essa criança, a melhor conduta terapêutica, entre as opções abaixo,\né:","options":{"A":"Distorção da lesão isquêmica por acesso videolaparoscópico.","B":"Enema usando contraste baritado ou ar guiado por fluoroscopia.","C":"Ressecção da lesão intestinal e confecção de ostomias por laparotomia exploradora.","D":"Ressecção da lesão intestinal seguida de anastomose primária por acesso videoassistido."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-126956","number":"126956","sourceNumber":"126956","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino de 3 anos é trazido à Unidade de Pronto Atendimento (UPA) apresentando voz\nabafada, tosse de cachorro e \"cansaço\". A família informa que o quadro iniciou após a sesta da\ntarde, e que o filho estava previamente saudável, com as vacinas feitas. Ao atendê-lo, o\nmédico constata estridor em repouso, retração de fúrcula e postura em tripé da criança. Qual a\nconduta imediata adequada para esse caso?","options":{"A":"Nebulização com fenoterol, hidratação venosa e corticoide endovenoso. Realização de\nradiografia de tórax;","B":"Nebulização com fenoterol ? 1 inalação a cada 20 minutos em 1 hora e prometazina\nendovenosa\n\nReavaliação após nebulizações;","C":"Internação, hidratação venosa vigorosa, prometazina endovenosa e antibioticoterapia.\n\nRealização de radiografia lateral do pescoço;","D":"Internação, estabelecer via aérea e oxigênio em alto fluxo, adrenalina intramuscular,\nacesso venoso para infusão de volume, monitorização e\nreavaliação em 5 minutos."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-126959","number":"126959","sourceNumber":"126959","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menina de 6 anos comparece à Unidade Básica de Saúde por apresentar\nquadros de diarreia alternados com períodos\nde eliminação de fezes normais ou ressecadas. Os\npais referem também episódios de dor e leve distensão abdominal, perda de peso e eventualmente\nfezes gordurosas e com restos alimentares. Esse quadro clínico é fortemente sugestivo de qual\nparasita intestinal?","options":{"A":"Giardia lamblia.","B":"Ascaris lumbricoides.","C":"Entamoeba histolytica.","D":"Strongyloides stercoralis."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-126969","number":"126969","sourceNumber":"126969","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menina de 2 anos vem à Unidade Básica de Saúde (UBS) apresentando febre\nbaixa há 3 dias, irritabilidade, falta de\napetite e discretos sintomas catarrais. No dia do\natendimento surgiu exantema com lesões papulovesiculares nas extremidades, principalmente\nnos dedos, dorso das mãos e planta dos pés. Ao exame, o médico constatou lesões vesiculares\nna boca, com algumas úlceras dolorosas. O quadro clínico descrito corresponde a qual doença\nexantemática da infância?","options":{"A":"Sarampo.","B":"Exantema súbito.","C":"Eritema infeccioso.","D":"Síndrome mão-pé-boca."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-126944","number":"126944","sourceNumber":"126944","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de 1 mês e 15 dias de idade é levada à Unidade Básica Saúde (UBS) pela avó\npor não estar conseguindo mamar e por\napresentar ?cansaço? há 3 horas. No exame físico, a sua\nmédica de família e comunidade observa tiragem subcostal e FR de 65 irpm. Qual das alternativas\nrepresenta a conduta CORRETA?","options":{"A":"Administrar oxigenoterapia e observar a criança na UBS até melhora dos sintomas.","B":"Solicitar radiografia de tórax urgentemente e agendar retorno na UBS em 24 horas.","C":"Prescrever antibiótico oral por 10 dias e agendar retorno na UBS em 48 horas.","D":"Administrar a primeira dose do antibiótico na UBS e remover para o hospital."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-102128","number":"102128","sourceNumber":"102128","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de três meses, assintomática, comparece ao ambulatório para checar o teste\ndo pezinho que evidencia triagem positiva para\nfibrose cística. Nessa situação, dentre as abaixo\ncitadas, qual a melhor conduta a seguir?","options":{"A":"Encaminhar a família para aconselhamento genético.","B":"Solicitar teste de eletrólitos (sódio e cloro) no suor.","C":"Solicitar nova coleta de tripsina imunorreativa (IRT).","D":"Aguardar presença de sinais e sintomas para repetir o exame."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-102139","number":"102139","sourceNumber":"102139","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de nove meses de idade, anteriormente sadia, apresenta subitamente\nchoro intenso, alguns vômitos e distensão\nabdominal. O toque retal revela a presença de sangue.\nQual a hipótese diagnóstica mais provável?","options":{"A":"Íleo infeccioso.","B":"Apendicite aguda.","C":"Invaginação intestinal.","D":"Hérnia inguinal estrangulada."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-102151","number":"102151","sourceNumber":"102151","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de três meses e 15 dias, em aleitamento misto, foi levado à Unidade Básica\nde Saúde porque sua mãe notou fezes muito\nlíquidas várias vezes ao dia. O médico indagou: Há\nquanto tempo o bebê está com diarreia? A mãe respondeu: dois dias. Há sangue nas fezes? A mãe\ndisse que não. Ao examinar o bebê, observou-se que estava intranquilo e irritado, não tinha os\nolhos fundos e ao sinal da prega, a pele voltava lentamente ao seu estado anterior. Qual a conduta\nadequada para o caso desse lactente?","options":{"A":"Hidratação venosa e ácido nalidíxico 5 dias.","B":"Referir urgente para internação após etapa rápida de hidratação venosa.","C":"Estimular o aleitamento materno e solução de reidratação oral 50-100 ml/kg em 4-6 horas.","D":"Solução de reidratação oral 50-100 ml após cada evacuação líquida e\nsulfametoxazol/trimetropim 5 dias."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-102160","number":"102160","sourceNumber":"102160","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de seis anos de idade, com retardo mental, apresenta diarreia, dor\nabdominal epigástrica de forte intensidade e flatulência. Há uma semana apresenta rash\neritematopapular pruriginoso e sintomas asmatiformes. Qual a parasitose mais provável e o\ntratamento correspondente associado a esse quadro?","options":{"A":"Amebíase; etofamida.","B":"Ancilostomíase; albendazol.","C":"Esquistossomose; praziquantel.","D":"Estrongiloidíase; ivermectina."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-102171","number":"102171","sourceNumber":"102171","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Ao atender uma criança de três dias de vida, com conjuntivite por provável Clamídia, o\nmédico prescreve eritromicina oral. Após duas semanas, a criança necessita fazer uma cirurgia por\num possível efeito adverso desse antibiótico nessa faixa de idade. Assinale a alternativa que\ncontém a condição sugerida nesse caso?","options":{"A":"Estenose hipertrófica do piloro.","B":"Intussuscepção intestinal.","C":"Divertículo de Meckel.","D":"Má rotação intestinal."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-102101","number":"102101","sourceNumber":"102101","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 18 meses é atendida no ambulatório com relato de três episódios de\n\"chiado no peito\" logo após ter completado o 1º semestre de vida. Que outros dados da história\nclínica aumentam a probabilidade de asma de apresentação precoce?","options":{"A":"Sinais de dermatite atópica + tosse noturna.","B":"Sibilância induzida por vírus + um dos pais com asma.","C":"Sintomas nasais (prurido e rinorreia) + sinais de dermatite atópica.","D":"Dados clínicos sugestivos de refluxo gastroesofágico + rinorreia."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-141594","number":"141594","sourceNumber":"141594","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 11 meses, sexo feminino, é atendido na Unidade de Saúde com relato de\nfebre e rinorreia há 24h. A mãe levou para a consulta hoje, por achar que estava mais prostrado\nnaquele momento, embora com boa aceitação de dieta oral. Ao exame físico, foi observado:\nhiperemia de orofaringe, secreção nasal espessa e amarelada, abaulamento de membranas\ntimpânicas e presença de efusão purulenta da orelha média a direita. A ausculta cardíaca e\npulmonar estava normal e não apresentava outras alterações ao exame físico além das descritas\nacima. A conduta indicada seria a prescrição de:","options":{"A":"Cefaclor durante sete dias.","B":"Ceftriaxona durante três dias.","C":"Clindamicina durante dez dias.","D":"Amoxacilina durante sete dias."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-365611","number":"365611","sourceNumber":"365611","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 10 meses de vida foi levada ao pronto-socorro com história de febre\nalta há dois dias, sem outros sintomas. O\ndiagnóstico inicial foi febre sem sinais de localização,\nprovavelmente por um quadro viral inespecífico. Recebeu alta sintomático, e os pais foram\norientados a aguardar a resolução espontânea do quadro. No quinto dia de febre, retornou ao\npronto atendimento para reavaliação. Além da febre, observaram-se hiperemia de conjuntivas sem\nsecreção, exantema em tronco e região perineal, além de ressecamento e fissuras nos lábios. Ao\nexame físico, foram verificados linfonodo cervical direito palpável, medindo cerca de 1,5 cm,\ndiscreto edema em dorso das mãos e dos pés, sem descamação e orofaringe difusamente\nhiperemiada, sem placas de pus ou lesões aftosas. Realizou testes rápidos para Sars-CoV-2 e\ninfluenza, com resultados negativos. Nesse caso, a conduta mais adequada é","options":{"A":"manter sintomáticos e informar que se trata de um quadro viral autolimitado.","B":"iniciar antibioticoterapia de amplo espectro (amoxicilina+clavulanato ou cefalosporina de\nsegunda geração) por 10 dias.","C":"iniciar amoxicilina por 10 dias.","D":"solicitar hemograma, proteína-C-reativa, transaminases, EAS e ecocardiograma."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-349725","number":"349725","sourceNumber":"349725","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um menino de um ano e meio de idade apresenta febre há três dias, com poucos\npródromos de infecção respiratória aguda,\ne apresenta erupção maculo-papular que cursa por dois\ndias. O que chamou a atenção da mãe foi que, \"no dia em que apareceram as manchas na pele, a\nfebre desapareceu\". Clinicamente a criança encontra-se bem. Qual é o diagnóstico provável nesse\ncaso?","options":{"A":"Eritema infeccioso.","B":"Mononucleose infecciosa.","C":"Varicela.","D":"Exantema súbito.","E":"Escarlatina."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-349697","number":"349697","sourceNumber":"349697","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Na consulta de rotina, o pediatra está em dúvida sobre um sopro cardíaco em uma\ncriança de dois anos que não apresenta sinais de insuficiência cardíaca. Suspeita-se de\nComunicação Interventricular (CIV). Para auscultar o sopro cardíaco nesse caso,","options":{"A":"o paciente deve estar, preferencialmente, em decúbito dorsal com o tórax elevado.","B":"o paciente deve estar em posição supina, com o braço esquerdo apoiado no peito, subclavicular.","C":"o paciente deve estar em posição sentada com o tronco inclinado para frente, axilar direito.","D":"o melhor local é o quarto espaço intercostal esquerdo.","E":"o paciente deve estar em decúbito ventral, interescapular."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-365575","number":"365575","sourceNumber":"365575","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Nos últimos anos, está aumentando o número de casos de hipertensão arterial\nsistêmica na faixa etária pediátrica. Isso se\ndeve ao aumento da prevalência de obesidade,\nsedentarismo e hábitos alimentares inadequados. Com relação à hipertensão arterial na infância,\nassinale a alternativa correta.","options":{"A":"Betabloqueadores são as drogas de primeira linha na maioria dos casos, com baixo risco de\nefeitos colaterais nessa faixa etária.","B":"A hipertensão relacionada à obesidade é classificada como secundária.","C":"Todas as crianças devem ter a pressão arterial verificada anualmente a partir dos 3 anos de\nidade.","D":"Hipertensão arterial primária acomete principalmente crianças menores de 5 anos de idade."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-349679","number":"349679","sourceNumber":"349679","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação ao sistema cardiovascular fetal, assinale a alternativa correta.","options":{"A":"Aproximadamente 10% do retorno venoso ao coração fetal é originário da veia cava inferior,\nsendo que cerca de um terço desse volume é de responsabilidade do ducto venoso.","B":"O forame oval comunica o ventrículo direito e o ventrículo esquerdo.","C":"A maior saturação de oxigênio da circulação fetal encontra-se na veia cava inferior\ninfra-hepática.","D":"Medicamentos inibidores de prostaglandinas, como os anti-inflamatórios não hormonais, têm\npotencial para provocar o fechamento do canal arterial e causar hipertensão pulmonar antes do\nnascimento.","E":"O sistema nervoso central, o miocárdio e a parte superior do corpo do feto recebem sangue\nejetado pelo ventrículo direito."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-322166","number":"322166","sourceNumber":"322166","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre o fenômeno (ou síndrome) de Eisenmenger, assinale a alternativa correta.","options":{"A":"É muito comum nos casos de infarto agudo do miocárdio.","B":"Uma das principais características clínicas é a cianose de extremidades.","C":"É comum nos casos de comunicação interventricular, sendo caracterizado pelo shunt\nesquerda-direita.","D":"Foi descrito por Frederick Eisenmenger em 1973 em estudo publicado após análise de 52 casos\nde cardiopatias congênitas cianóticas.","E":"O tratamento com inibidores da enzima conversora de angiotensina (IECA) está indicado."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-322170","number":"322170","sourceNumber":"322170","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um menino de 3 anos apresenta quadro febril há 6 dias e é levado para avaliação.\nDurante a consulta, são identificadas outras\nalterações: exantema polimorfo difuso, conjuntivite sem\nexsudato, mucosite oral, edema distal dos membros e adenomegalia cervical unilateral.\n\nSuspeitando-se de Doença de Kawasaki, qual dos sinais ou sintomas apresentados pelo paciente é\nconsiderado o critério mandatório para o diagnóstico?","options":{"A":"Febre.","B":"Exantema.","C":"Conjuntivite.","D":"Mucosite.","E":"Edema distal."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-322182","number":"322182","sourceNumber":"322182","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança em idade escolar é levada para consulta de rotina. Ela fazia\nacompanhamento em outra cidade e vem, hoje, para\na primeira consulta com você. Ao exame\nfísico, você detecta um sopro cardíaco. Qual das seguintes características indica se tratar de um\nsopro patológico?","options":{"A":"Sopro acentuado por quadro febril.","B":"Ausência de irradiação do sopro.","C":"Desaparecimento ou diminuição do sopro com a mudança de decúbito.","D":"Presença de frêmitos.","E":"Sopro localizado em área pequena e bem definida."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-305290","number":"305290","sourceNumber":"305290","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma mulher de 32 anos procura atendimento médico com queixa de cansaço aos\nmínimos esforços. Refere sopro cardíaco desde a\ninfância. Possui histórico de comunicação\ninterventricular e evolução para Síndrome (ou fenômeno) de Eisenmenger nos últimos dois meses.\nQual achado de exame físico é certamente encontrado nessa paciente?","options":{"A":"Sopro holossistólico com hiperfonese de B1.","B":"Pronunciada cianose de extremidades.","C":"Déficit cognitivo moderado.","D":"Pulso em martelo d'água.","E":"Pressão arterial convergente."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-305309","number":"305309","sourceNumber":"305309","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação ao nefroblastoma (tumor de Wilms), é CORRETO afirmar que:","options":{"A":"Tem seu pico de incidência em crianças maiores de 5 anos.","B":"É mais agressivo na presença de anaplasia, mesmo quando focal e em tumores localizados\n(estádios I e II).","C":"Manifesta-se mais comumente como massa abdominal muito dolorosa, acompanhada de\nhematúria macroscópica.","D":"Exige, para seu diagnóstico, a realização de biópsia percutânea nos casos suspeitos de idade\ncompatível.","E":"É o tumor sólido mais comum no recém-nascido."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-305311","number":"305311","sourceNumber":"305311","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A enurese noturna é uma queixa frequente no consultório pediátrico. Qual das\nseguintes alternativas é correta a respeito dessa condição?","options":{"A":"A enurese primária ocorre quando a criança nunca ficou mais de 1 dia sem urinar durante o\nsono.","B":"A enurese é dita secundária quando a criança ficou um período igual ou superior a 4 semanas\nsem enurese e voltou a urinar durante o sono.","C":"Fatores psicológicos são a causa mais comum de enurese primária.","D":"É definida por perda intermitente de urina durante o sono, em maiores de 3 anos, pelo menos 1\nvez por noite, na ausência de alterações de\nsistema nervoso central.","E":"Não há associação significativa entre sobrepeso e enurese."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-298882","number":"298882","sourceNumber":"298882","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma paciente de 1 ano e 6 meses de idade foi encaminhada ao pronto atendimento\npediátrico por apresentar febre, há três\ndias, entre 38ºC e 39,5ºC, sem outras queixas. A criança foi\nlevada pela avó materna, que se mostrou bastante preocupada, pois, além da febre, notou que a\ncriança apresenta manchas arrocheadas nos membros superiores e inferiores. A criança reside\ncom a mãe, um irmão de 5 anos de idade e o padrasto. Ao exame físico, ela mostra-se abatida e\nprostrada, mas está corada e hidratada. Constataram-se FC = 120 bpm, FR = 40 irpm, SatO2 =\n98% em AA, oroscopia sem petéquias, sem placas, sem lesões, otoscopia com membrana\ntimpânica translúcida, sem abaulamento, sem secreção, ausculta cardíaca BNF, RR, 2t, sem sopro\ne ausculta pulmonar MVUD, sem ruídos adventícios. Também foram observados abdome RHA+,\ndepressível, dor à palpação em baixo ventre, Blumberg e Murph negativos, sem sinais de\nmeningismo, membros inferiores com equimoses < 5 cm e membros superiores com equimoses > 5\ncm em braço esquerdo. Inicialmente foram solicitados exame qualitativo de urina com urocultura\n(via sondagem vesical; ainda sem resultado da urocultura) e radiografia de membro superior\nesquerdo. O exame qualitativo de urina pode ser verificado a seguir. Realizou-se, ainda, radiografia\nque evidenciou calo ósseo em rádio e ulna esquerda, conforme a imagem a seguir. Acerca desse\ncaso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. Quando\numa criança tem infecção febril do trato urinário, é importante realizar o tratamento correto, com\nuso\nde antibiótico por 10 dias a 14 dias, mas não é necessário acompanhar com exames de imagem,\nvisto que dificilmente elas apresentam lesão renal.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-298883","number":"298883","sourceNumber":"298883","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma paciente de 1 ano e 6 meses de idade foi encaminhada ao pronto atendimento\npediátrico por apresentar febre, há três\ndias, entre 38ºC e 39,5ºC, sem outras queixas. A criança foi\nlevada pela avó materna, que se mostrou bastante preocupada, pois, além da febre, notou que a\ncriança apresenta manchas arrocheadas nos membros superiores e inferiores. A criança reside\ncom a mãe, um irmão de 5 anos de idade e o padrasto. Ao exame físico, ela mostra-se abatida e\nprostrada, mas está corada e hidratada. Constataram-se FC = 120 bpm, FR = 40 irpm, SatO2 =\n98% em AA, oroscopia sem petéquias, sem placas, sem lesões, otoscopia com membrana\ntimpânica translúcida, sem abaulamento, sem secreção, ausculta cardíaca BNF, RR, 2t, sem sopro\ne ausculta pulmonar MVUD, sem ruídos adventícios. Também foram observados abdome RHA+,\ndepressível, dor à palpação em baixo ventre, Blumberg e Murph negativos, sem sinais de\nmeningismo, membros inferiores com equimoses < 5 cm e membros superiores com equimoses > 5\ncm em braço esquerdo. Inicialmente foram solicitados exame qualitativo de urina com urocultura\n(via sondagem vesical; ainda sem resultado da urocultura) e radiografia de membro superior\nesquerdo. O exame qualitativo de urina pode ser verificado a seguir. Realizou-se, ainda, radiografia\nque evidenciou calo ósseo em rádio e ulna esquerda, conforme a imagem a seguir. Acerca desse\ncaso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. Sempre\nque se observam equimoses em menores de 5 anos de idade, deve-se realizar uma investigação\nde hemofilia, por ser uma patologia bastante frequente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-298884","number":"298884","sourceNumber":"298884","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma paciente de 1 ano e 6 meses de idade foi encaminhada ao pronto atendimento\npediátrico por apresentar febre, há três\ndias, entre 38ºC e 39,5ºC, sem outras queixas. A criança foi\nlevada pela avó materna, que se mostrou bastante preocupada, pois, além da febre, notou que a\ncriança apresenta manchas arrocheadas nos membros superiores e inferiores. A criança reside\ncom a mãe, um irmão de 5 anos de idade e o padrasto. Ao exame físico, ela mostra-se abatida e\nprostrada, mas está corada e hidratada. Constataram-se FC = 120 bpm, FR = 40 irpm, SatO2 =\n98% em AA, oroscopia sem petéquias, sem placas, sem lesões, otoscopia com membrana\ntimpânica translúcida, sem abaulamento, sem secreção, ausculta cardíaca BNF, RR, 2t, sem sopro\ne ausculta pulmonar MVUD, sem ruídos adventícios. Também foram observados abdome RHA+,\ndepressível, dor à palpação em baixo ventre, Blumberg e Murph negativos, sem sinais de\nmeningismo, membros inferiores com equimoses < 5 cm e membros superiores com equimoses > 5\ncm em braço esquerdo. Inicialmente foram solicitados exame qualitativo de urina com urocultura\n(via sondagem vesical; ainda sem resultado da urocultura) e radiografia de membro superior\nesquerdo. O exame qualitativo de urina pode ser verificado a seguir. Realizou-se, ainda, radiografia\nque evidenciou calo ósseo em rádio e ulna esquerda, conforme a imagem a seguir. Acerca desse\ncaso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. Em\ncasos de febre sem sinais localizatórios, deve-se pensar sempre em infecção do trato urinário,\nsendo que, entre as bactérias causadoras, encontra-se a Bordetella pertussis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-298886","number":"298886","sourceNumber":"298886","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma paciente de 1 ano e 6 meses de idade foi encaminhada ao pronto atendimento\npediátrico por apresentar febre, há três\ndias, entre 38ºC e 39,5ºC, sem outras queixas. A criança foi\nlevada pela avó materna, que se mostrou bastante preocupada, pois, além da febre, notou que a\ncriança apresenta manchas arrocheadas nos membros superiores e inferiores. A criança reside\ncom a mãe, um irmão de 5 anos de idade e o padrasto. Ao exame físico, ela mostra-se abatida e\nprostrada, mas está corada e hidratada. Constataram-se FC = 120 bpm, FR = 40 irpm, SatO2 =\n98% em AA, oroscopia sem petéquias, sem placas, sem lesões, otoscopia com membrana\ntimpânica translúcida, sem abaulamento, sem secreção, ausculta cardíaca BNF, RR, 2t, sem sopro\ne ausculta pulmonar MVUD, sem ruídos adventícios. Também foram observados abdome RHA+,\ndepressível, dor à palpação em baixo ventre, Blumberg e Murph negativos, sem sinais de\nmeningismo, membros inferiores com equimoses < 5 cm e membros superiores com equimoses > 5\ncm em braço esquerdo. Inicialmente foram solicitados exame qualitativo de urina com urocultura\n(via sondagem vesical; ainda sem resultado da urocultura) e radiografia de membro superior\nesquerdo. O exame qualitativo de urina pode ser verificado a seguir. Realizou-se, ainda, radiografia\nque evidenciou calo ósseo em rádio e ulna esquerda, conforme a imagem a seguir. Acerca desse\ncaso clínico e tendo em vista os conhecimentos médicos correlatos, julgue o item a seguir. O\ntrauma contuso, nas crianças mais novas, muitas vezes é consequência dos maus-tratos e do\nespancamento.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-305319","number":"305319","sourceNumber":"305319","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma adolescente procura a emergência com queixa de dores abdominais intensas. Ao\nser avaliada pelo pediatra de plantão, ela\nrelata que está ali por estar precisando de ajuda. Conta\nque tem sofrido, em casa, diversas formas de violência. Cita, entre elas: beliscões, tapas,\nxingamentos, constrangimentos perante as visitas e que, algumas vezes, já ficou de castigo sem\nalimentos ou água. É muito importante, para saber como acolher os pacientes nessas situações e\npara identificar os pacientes em risco, que o pediatra conheça as formas de violência. Quanto ao\ntema, informe se é verdadeiro (V) ou falso (F) o que se afirma a seguir e assinale a alternativa com\na sequência correta. ( ) Violência física é entendida como a ação infligida à criança ou ao\nadolescente que ofenda sua integridade ou saúde corporal ou que lhe cause sofrimento físico. ( ) A\nalienação parental é um tipo de violência psicológica. ( ) Conduta que constranja a criança ou o\nadolescente a presenciar conjunção carnal é considerada violência sexual. ( ) Violência\ninstitucional\né entendida como a praticada por instituição pública ou conveniada, inclusive quando gerar\nrevitimização. ( ) Expor a criança ou o adolescente a isolamento ou indiferença é uma forma de\nviolência psicológica.","options":{"A":"V - V - V - V - V","B":"V - F - V - V - F","C":"F - F - F - V - F","D":"F - V - V - F - V","E":"V - V - V - V - F"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-274381","number":"274381","sourceNumber":"274381","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O refluxo vesicoureteral é a entidade clínica em que ocorre o fluxo retrógrado de urina\nda bexiga em direção aos ureteres e rins. Referente ao tema, assinale a alternativa correta.","options":{"A":"Poucos pacientes apresentarão resolução espontânea.","B":"Pode evoluir para insuficiência renal crônica.","C":"O tratamento é bem estabelecido e exige, sempre, profilaxia com antibiótico de longo prazo.","D":"A cistouretrografia miccional permite o diagnóstico e a classificação, mas não avalia a anatomia\ndo trato urinário inferior.","E":"Pacientes com diagnóstico antenatal de hidronefrose têm indicação mandatória de\ncistouretrografia miccional, independente do grau do refluxo, ainda no período neonatal."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-274387","number":"274387","sourceNumber":"274387","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre as causas de parada cardiorrespiratória (PCR) na faixa etária pediátrica, assinale\na alternativa correta.","options":{"A":"Geralmente é um evento subido.","B":"Os ritmos cardíacos mais frequentes são a bradicardia e a assistolia.","C":"As arritmias ventriculares são muito comuns, principalmente em PCR extra-hospitalar.","D":"Costuma ser de origem cardíaca, sendo a fibrilação ventricular o ritmo mais comum.","E":"No ambiente hospitalar, as causas mais comuns são infarto agudo do miocárdio e miocardite."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-274391","number":"274391","sourceNumber":"274391","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual é a cardiopatia cianótica mais comum em recém-nascidos?","options":{"A":"Transposição de grandes artérias.","B":"Dupla via de saída do ventrículo direito.","C":"Drenagem anômala total das veias pulmonares.","D":"Comunicação interventricular.","E":"Defeito do septo atrioventricular total."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-262213","number":"262213","sourceNumber":"262213","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um paciente de 20 anos de idade queixa-se de distensão abdominal e diarreia quando\nexagera no consumo de alimentos ricos em\nleite de vaca ou derivados. Já fez o teste de tolerância\nà lactose e levou o resultado à consulta médica. Acerca desse caso clínico e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. Caso esse paciente insista em ingerir\nleite e derivados com lactose, pode desenvolver câncer de cólon.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-262214","number":"262214","sourceNumber":"262214","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um paciente de 20 anos de idade queixa-se de distensão abdominal e diarreia quando\nexagera no consumo de alimentos ricos em\nleite de vaca ou derivados. Já fez o teste de tolerância\nà lactose e levou o resultado à consulta médica. Acerca desse caso clínico e considerando os\nconhecimentos médicos correlatos, julgue o item a seguir. A hipovitaminose por cálcio pode ocorrer\ncaso sejam utilizados produtos lácteos sem lactose.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-261302","number":"261302","sourceNumber":"261302","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 1 ano e 4 meses de idade, com histórico de aleitamento materno\nexclusivo até os 6 meses, é levada a\natendimento pela mãe que referiu tosse, febre, hiperemia\nocular e aparecimento de \"manchas\" brancas em mucosa oral, com posterior aparecimento de\n\"manchas\" vermelhas no corpo. Ao exame, apresenta temperatura axilar de 38 ºC e exantema\nmaculopapular avermelhado, de progressão craniocaudal. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. A presença de pequenos pontos brancos\nem mucosa oral antecedendo o exantema é um sinal patognomônico dessa doença.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-261304","number":"261304","sourceNumber":"261304","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 1 ano e 4 meses de idade, com histórico de aleitamento materno\nexclusivo até os 6 meses, é levada a\natendimento pela mãe que referiu tosse, febre, hiperemia\nocular e aparecimento de \"manchas\" brancas em mucosa oral, com posterior aparecimento de\n\"manchas\" vermelhas no corpo. Ao exame, apresenta temperatura axilar de 38ºC e exantema\nmaculopapular avermelhado, de progressão craniocaudal. Com base nesse caso clínico e nos\nconhecimentos médicos correlatos, julgue o item a seguir. A transmissão dessa doença dá-se por\nmeio de aerossol e gotículas de secreção respiratória.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-250115","number":"250115","sourceNumber":"250115","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Acerca das patologias na infância, julgue o item a seguir. A criança com sarampo deve\nser tratada com vitamina A no mesmo dia do\ndiagnóstico, com a finalidade de reduzir a ocorrência\nde casos graves e fatais, pois, diferentemente da gripe (influenza), não existe tratamento\nantiviral e\na administração profilática com antibiótico é contraindicada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-255723","number":"255723","sourceNumber":"255723","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Determinado lactente de 6 meses de vida apresenta importante dispneia, sibilos na\nausculta pulmonar com saturação de 88%. O\npediatra avalia esse paciente, suspeita de bronquiolite\ne inicia o tratamento. Além disso, a criança apresentava uma quantidade importante de vômitos não\nbiliosos. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Oxigênio por cateter para manter saturação entre 90% e 92% pode ser uma medida\ntomada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-255725","number":"255725","sourceNumber":"255725","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Determinado lactente de 6 meses de vida apresenta importante dispneia, sibilos na\nausculta pulmonar com saturação de 88%. O\npediatra avalia esse paciente, suspeita de bronquiolite\ne inicia o tratamento. Além disso, a criança apresentava uma quantidade importante de vômitos não\nbiliosos. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o item a\nseguir. Até o momento, não há grandes estudos randomizados demonstrando superioridade no uso\nde CPAP contra a terapia de suplementação de oxigênio.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-255777","number":"255777","sourceNumber":"255777","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 11 meses de vida foi levada à unidade de saúde da família com história\nde tosse produtiva, febre há quatro dias e\ndificuldade respiratória. Além do quadro agudo, a mãe\ndemostrava preocupação pelo fato de a filha ainda não conseguir sentar sem apoio. Exame físico:\nbom estado geral; corada; hidratada; anictérica; acianótica; sem tiragem subcostal; presença de\nestertoração crepitante na base esquerda; FR = 68 irpm; FC = 118; SpO2 = 97%. Com base nesse\ncaso clínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Nessa faixa etária, o\nagente mais comum na pneumonia é o Streptococcus pneumoniae.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-211984","number":"211984","sourceNumber":"211984","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 2 anos de idade foi atendida na emergência com quadro de febre alta\nhá seis dias, acompanhado de gânglios no\npescoço, irritação nos olhos e rash cutâneo. Ao exame\nfísico, apresentava eritema de mãos e pés, eritema maculopapular polimorfo que se acentuava nas\nvirilhas, lábios secos e fissurados, língua em \"framboesa\", linfadenopatia cervical e conjuntivas\nhiperemiadas e congestas sem secreção, além de estar febril. Considerando esse caso clínico e os\nconhecimentos médicos correlatos, assinale a alternativa CORRETA.","options":{"A":"O quadro é compatível com gengivoestomatite herpética.","B":"Trata-se de varicela na primeira semana da doença, quando ainda não apareceram as\ncaracterísticas lesões vesiculobolhosas.","C":"A rubéola é bem característica nessa faixa etária, cursando com febre muito alta e língua em\n\"framboesa\".","D":"O quadro é de escarlatina, doença infecciosa febril estafilocócica característica dessa faixa\netária.","E":"Trata-se de uma vasculite febril da infância, conhecida como doença de Kawasaki."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-212009","number":"212009","sourceNumber":"212009","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um lactente de 11 meses de idade está internado na vigência de uma segunda\ninfecção do trato urinário. Nesse caso\nclínico, para realizar a investigação imagenológica, deve-se\nsolicitar:","options":{"A":"Uretrografia miccional durante a internação.","B":"Radiografia de tórax e abdome durante a internação.","C":"Ultrassonografia de rins e vias urinárias durante a internação.","D":"Urografia excretora durante a internação.","E":"Ressonância de abdome após a alta."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-196683","number":"196683","sourceNumber":"196683","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente de 6 meses e 20 dias de vida, nascido com 35 semanas de idade gestacional,\né levado a uma consulta de puericultura pela\nmãe. Recebe aleitamento materno, papas de frutas e\nduas papas principais. A mãe demonstra muita preocupação, pois o lactente não senta sem apoio e\nnão rola no leito. Com base nesse caso clínico e nos conhecimentos médicos correlatos, julgue o\nitem a seguir. Uma vez que o bebê ainda não rola no leito, não é necessário que durma em berço\ncom grades apropriadas, podendo ser estimulado o coleito.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-214481","number":"214481","sourceNumber":"214481","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Certo paciente de 12 meses de vida é levado ao pronto atendimento por histórico de\nsete dias de tosse e secreção nasal, com\nfebre que se iniciou há 48 horas. Ao exame físico,\nobservam-se amígdalas hiperemiadas e com secreção exsudativa bilateralmente, além de\nlinfonodomegalia cervical e baço palpável. Ao exame físico, verificam-se FC de 90 bpm, FR de 16\nirpm e saturação de oxigênio de 99%. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatados. julgue o item a seguir. O diagnóstico definitivo é de amigdalite bacteriana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-214487","number":"214487","sourceNumber":"214487","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Certo paciente de 12 meses de vida é levado ao pronto atendimento por histórico de\nsete dias de tosse e secreção nasal, com\nfebre que se iniciou há 48 horas. Ao exame físico,\nobservam-se amígdalas hiperemiadas e com secreção exsudativa bilateralmente, além de\nlinfonodomegalia cervical e baço palpável. Ao exame físico, verificam-se FC de 90 bpm, FR de 16\nirpm e saturação de oxigênio de 99%. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatados. julgue o item a seguir. O antibioticoterapia com penicilina é a principal opção\nterapêutica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-214523","number":"214523","sourceNumber":"214523","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Certo paciente de 12 meses de vida é levado ao pronto atendimento por histórico de\nsete dias de tosse e secreção nasal, com\nfebre que se iniciou há 48 horas. Ao exame físico,\nobservam-se amígdalas hiperemiadas e com secreção exsudativa bilateralmente, além de\nlinfonodomegalia cervical e baço palpável. Ao exame físico, verificam-se FC de 90 bpm, FR de 16\nirpm e saturação de oxigênio de 99%. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatados. julgue o item a seguir. A esplenectoma indicada nesse paciente, deve, se possível,\nser precedida por vacinação antipneumocócica, atimeningocócica e anti- Haemophilus tipo B.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-214496","number":"214496","sourceNumber":"214496","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Certo paciente de 12 meses de vida é levado ao pronto atendimento por histórico de\nsete dias de tosse e secreção nasal, com\nfebre que se iniciou há 48 horas. Ao exame físico,\nobservam-se amígdalas hiperemiadas e com secreção exsudativa bilateralmente, além de\nlinfonodomegalia cervical e baço palpável. Ao exame físico, verificam-se FC de 90 bpm, FR de 16\nirpm e saturação de oxigênio de 99%. Com base nesse caso clínico e nos conhecimentos médicos\ncorrelatados. julgue o item a seguir. Quando essa doença apresentar-se em escolares, e também\nhouver esplenomegalia, é prudente afastá-los da prática do esportes de contato.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-214429","number":"214429","sourceNumber":"214429","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma paciente de 11 anos de idade compareceu a consulta de pronto atendimento com\nqueixa de oito episódios de diarreia no dia de hoje, com fezes líquidas sem presença de elementos\npatológicos. Não ocorreram febre ou vômitos. Ao exame físico, verificaram-se olhos normais,\nmucosas úmidas e coradas, sinal da prega com desaparecimento rápido, pulsos cheios e simétricos\ne enchimento capilar com tempo de dois segundos. Constataram-se FC de 80 bpm, saturação de\noxigênio de 100% e frequência respiratória de 16 irpm. A paciente apresenta histórico de\ntratamento oncológico para linfoma, atualmente sem critérios para recidiva, e infecções urinárias\nfrequentes (de três a cinco episódios ao ano), desde os 2 anos de idade. Com base nesse caso\nclínico e nos conhecimentos médicos correlatos, julgue o item a seguir. Há indicação de hidratação\nvenosa nessa paciente.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-177637","number":"177637","sourceNumber":"177637","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"I.F.S., menino de 3 anos de idade em acompanhamento em serviço de referência por\ndiagnóstico de nefroblastoma, aguardando tratamento cirúrgico, é levado ao pronto atendimento,\npor sua mãe, devido a queixas de diarreia há um dia, com cinco episódios de evacuação líquidas\nsem produtos patológicos, diminuição da ingestão alimentar e discreta diminuição do volume\nurinário. Não refere vômitos ou febre. As mucosas estão úmidas e coradas. A criança está alerta\nbrincando pelo consultório. O exame abdominal revela discreto desconforto difuso, sem\nperitonismo, além da massa abdominal palpável. Aproveitando a oportunidade da consulta médica,\na mãe do paciente resolve tirar algumas dúvidas sobre o transporte dele no carro. Com base nas\ninformações apresentadas no caso clínico e conhecimentos correlatos, julgue o item a seguir. O\nnefroblastoma, ao contrário do neuroblastoma, costuma atravessar a linha média do abdômen.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-177657","number":"177657","sourceNumber":"177657","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"I.F.S., menino de 3 anos de idade em acompanhamento em serviço de referência por\ndiagnóstico de nefroblastoma, aguardando tratamento cirúrgico, é levado ao pronto atendimento,\npor sua mãe, devido a queixas de diarreia há um dia, com cinco episódios de evacuação líquidas\nsem produtos patológicos, diminuição da ingestão alimentar e discreta diminuição do volume\nurinário. Não refere vômitos ou febre. As mucosas estão úmidas e coradas. A criança está alerta\nbrincando pelo consultório. O exame abdominal revela discreto desconforto difuso, sem\nperitonismo, além da massa abdominal palpável. Aproveitando a oportunidade da consulta médica,\na mãe do paciente resolve tirar algumas dúvidas sobre o transporte dele no carro. Com base nas\ninformações apresentadas no caso clínico e conhecimentos correlatos, julgue o item a seguir.\n\nCrianças entre 1 e 4 anos de idade devem ser transportadas no carro, para prevenção de traumas,\ncom dispositivos denominados \"cadeirinhas\".","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-177664","number":"177664","sourceNumber":"177664","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"I.F.S., menino de 3 anos de idade em acompanhamento em serviço de referência por\ndiagnóstico de nefroblastoma, aguardando tratamento cirúrgico, é levado ao pronto atendimento,\npor sua mãe, devido a queixas de diarreia há um dia, com cinco episódios de evacuação líquidas\nsem produtos patológicos, diminuição da ingestão alimentar e discreta diminuição do volume\nurinário. Não refere vômitos ou febre. As mucosas estão úmidas e coradas. A criança está alerta\nbrincando pelo consultório. O exame abdominal revela discreto desconforto difuso, sem\nperitonismo, além da massa abdominal palpável. Aproveitando a oportunidade da consulta médica,\na mãe do paciente resolve tirar algumas dúvidas sobre o transporte dele no carro. Com base nas\ninformações apresentadas no caso clínico e conhecimentos correlatos, julgue o item a seguir. A\ncadeirinha deve ser necessariamente posicionada no sentido oposto ao do restante dos bancos dos\ncarros.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-177609","number":"177609","sourceNumber":"177609","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"C.A.S., filho de J.A.S., agora está com 9 meses de idade. A mãe, muito atarefada\ndevido às responsabilidades maternais\nassociadas à necessidade de prover o sustento da família,\nresolveu comprar um andador (aparelho com rodas no qual a criança fica suspensa, podendo se\npropulsionar para frente ou para os lados), para que o filho tivesse mais liberdade para\n\nlocomover-se pela casa antes de aprender a andar. A respeito do andador e da relação desse\nobjeto com os traumas infantis, julgue o item a seguir. O andador pode ser considerado um\ninstrumento para prevenção de traumas infantis.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289393","number":"289393","sourceNumber":"289393","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere hipoteticamente que chega ao consultório um lactente de 5 meses de idade.\nA mãe relata que o filho apresenta diarreia\nhá pelo menos quatro semanas, em alguns episódios\ncom presença de muco e raias de sangue. Na primeira semana, apresentou alguns episódios de\nvômito, que cederam com o decorrer dos dias. Recebeu aleitamento materno exclusivo até os três\nmeses, quando foi iniciada a complementação com fórmula para lactente de primeiro semestre.\n\nHouve pouco ganho ponderal no último mês, no entanto, o paciente encontra-se eutrófico,\nhidratado, em bom estado geral. Ao exame\nfísico, observam-se lesões eritematosas em áreas de\ndobras e na face, compatíveis com dermatite atópica. Não há assaduras no períneo, e o abdome\nencontra-se levemente distendido, sem alterações com a palpação. Em relação ao caso clínico\napresentado, julgue o item a seguir. No caso de teste terapêutico para intolerância a lactose,\ndeve-se orientar a mãe para substituir a fórmula mencionada por fórmula à base de proteína de\nsoja e suspender o aleitamento materno.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289395","number":"289395","sourceNumber":"289395","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere hipoteticamente que chega ao consultório um lactente de 5 meses de idade.\nA mãe relata que o filho apresenta diarreia\nhá pelo menos quatro semanas, em alguns episódios\ncom presença de muco e raias de sangue. Na primeira semana, apresentou alguns episódios de\nvômito, que cederam com o decorrer dos dias. Recebeu aleitamento materno exclusivo até os três\nmeses, quando foi iniciada a complementação com fórmula para lactente de primeiro semestre.\n\nHouve pouco ganho ponderal no último mês, no entanto, o paciente encontra-se eutrófico,\nhidratado, em bom estado geral. Ao exame\nfísico, observam-se lesões eritematosas em áreas de\ndobras e na face, compatíveis com dermatite atópica. Não há assaduras no períneo, e o abdome\nencontra-se levemente distendido, sem alterações com a palpação. Em relação ao caso clínico\napresentado, julgue o item a seguir. Na realização de teste terapêutico para alergia à proteína do\nleite de vaca, o tratamento de primeira escolha é a substituição da fórmula mencionada por fórmula\nà base de proteína de soja, e não há evidências da necessidade de alteração da dieta materna.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289398","number":"289398","sourceNumber":"289398","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere hipoteticamente que chega ao consultório um lactente de 5 meses de idade.\nA mãe relata que o filho apresenta diarreia\nhá pelo menos quatro semanas, em alguns episódios\ncom presença de muco e raias de sangue. Na primeira semana, apresentou alguns episódios de\nvômito, que cederam com o decorrer dos dias. Recebeu aleitamento materno exclusivo até os três\nmeses, quando foi iniciada a complementação com fórmula para lactente de primeiro semestre.\n\nHouve pouco ganho ponderal no último mês, no entanto, o paciente encontra-se eutrófico,\nhidratado, em bom estado geral. Ao exame\nfísico, observam-se lesões eritematosas em áreas de\ndobras e na face, compatíveis com dermatite atópica. Não há assaduras no períneo, e o abdome\nencontra-se levemente distendido, sem alterações com a palpação. Em relação ao caso clínico\napresentado, julgue o item a seguir. Ao optar-se por teste terapêutico tanto para intolerância a\nlactose quanto para alergia à proteína do leite da vaca, a conduta correta é a substituição da\nfórmula mencionada por fórmula de hidrolisado proteico sem lactose e a suspensão do leite\nmaterno.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289400","number":"289400","sourceNumber":"289400","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere hipoteticamente que chega ao consultório um lactente de 5 meses de idade.\nA mãe relata que o filho apresenta diarreia\nhá pelo menos quatro semanas, em alguns episódios\ncom presença de muco e raias de sangue. Na primeira semana, apresentou alguns episódios de\nvômito, que cederam com o decorrer dos dias. Recebeu aleitamento materno exclusivo até os três\nmeses, quando foi iniciada a complementação com fórmula para lactente de primeiro semestre.\n\nHouve pouco ganho ponderal no último mês, no entanto, o paciente encontra-se eutrófico,\nhidratado, em bom estado geral. Ao exame\nfísico, observam-se lesões eritematosas em áreas de\ndobras e na face, compatíveis com dermatite atópica. Não há assaduras no períneo, e o abdome\nencontra-se levemente distendido, sem alterações com a palpação. Em relação ao caso clínico\napresentado, julgue o item a seguir. Não se pode distinguir, apenas com as informações desse\ncaso clínico, se o paciente apresenta intolerância a lactose ou alergia à proteína do leite da vaca,\nde forma que a conduta mais adequada é a solicitação de exames laboratoriais específicos para\ncada uma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289402","number":"289402","sourceNumber":"289402","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere hipoteticamente que chega ao consultório um lactente de 5 meses de idade.\nA mãe relata que o filho apresenta diarreia\nhá pelo menos quatro semanas, em alguns episódios\ncom presença de muco e raias de sangue. Na primeira semana, apresentou alguns episódios de\nvômito, que cederam com o decorrer dos dias. Recebeu aleitamento materno exclusivo até os três\nmeses, quando foi iniciada a complementação com fórmula para lactente de primeiro semestre.\n\nHouve pouco ganho ponderal no último mês, no entanto, o paciente encontra-se eutrófico,\nhidratado, em bom estado geral. Ao exame\nfísico, observam-se lesões eritematosas em áreas de\ndobras e na face, compatíveis com dermatite atópica. Não há assaduras no períneo, e o abdome\nencontra-se levemente distendido, sem alterações com a palpação. Em relação ao caso clínico\napresentado, julgue o item a seguir. Embora se possa tentar tratar a intolerância a lactose ou a\nalergia à proteína do leite de vaca, é pouco provável que o paciente sofra de um deles, pois ambas\nteriam se apresentado ainda no período neonatal, na primeira exposição do paciente, de forma que\nse pode praticamente excluir ambas pela faixa etária dele, relatada no caso clínico.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-154344","number":"154344","sourceNumber":"154344","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente, 9 meses de idade, apresentou quadro agudo de febre alta durante quatro\ndias. Após a cessação desse quadro, apareceu\nabruptamente um exantema maculopapular róseo\nque desapareceu espontaneamente em dois dias, sem pigmentação nem descamação. Quanto a\nesse caso clínico, assinale a alternativa que corresponde ao diagnóstico mais provável desse\npaciente.","options":{"A":"Sarampo.","B":"Rubéola.","C":"Escarlatina.","D":"Eritema infeccioso.","E":"Exantema súbito."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289404","number":"289404","sourceNumber":"289404","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um lactente de 3 meses de idade, previamente hígido, nascido a termo, com peso\nadequado, sem intercorrências no período\nneonatal, chega à emergência trazido pela mãe, que\nrelata que, há dois dias, o filho apresentava quadro de rinorreia, espirros, tosse, febre, com\ntemperatura axilar máxima de 38,5 °C. Com o passar das horas, a tosse intensificou-se, e o\npaciente tornou-se irritado, com dificuldade de mamar em razão da taquidispneia. A mãe relata que,\nhá algumas horas, o filho apresenta \"chiado no peito\". Ao exame físico, observa-se agitação, FR >\n70, tiragem subcostal e batimento de asas do nariz, além de sibilos à ausculta. A mãe nega\nepisódios prévios de sibilância e história familiar de asma ou de alergias de pele. A respeito desse\ncaso clínico, julgue o item a seguir. Não há evidências do benefício da administração de corticoide\nsistêmico em pacientes como o do caso clínico apresentado.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289407","number":"289407","sourceNumber":"289407","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um lactente de 3 meses de idade, previamente hígido, nascido a termo, com peso\nadequado, sem intercorrências no período\nneonatal, chega à emergência trazido pela mãe, que\nrelata que, há dois dias, o filho apresentava quadro de rinorreia, espirros, tosse, febre, com\ntemperatura axilar máxima de 38,5 °C. Com o passar das horas, a tosse intensificou-se, e o\npaciente tornou-se irritado, com dificuldade de mamar em razão da taquidispneia. A mãe relata que,\nhá algumas horas, o filho apresenta \"chiado no peito\". Ao exame físico, observa-se agitação, FR >\n70, tiragem subcostal e batimento de asas do nariz, além de sibilos à ausculta. A mãe nega\nepisódios prévios de sibilância e história familiar de asma ou de alergias de pele. A respeito desse\ncaso clínico, julgue o item a seguir. É provável que a radiografia de tórax evidencie sinais de\nhiperinsuflação pulmonar, como aumento da transparência pulmonar e retificação dos arcos costais\ne do diafragma.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289409","number":"289409","sourceNumber":"289409","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um lactente de 3 meses de idade, previamente hígido, nascido a termo, com peso\nadequado, sem intercorrências no período\nneonatal, chega à emergência trazido pela mãe, que\nrelata que, há dois dias, o filho apresentava quadro de rinorreia, espirros, tosse, febre, com\ntemperatura axilar máxima de 38,5 °C. Com o passar das horas, a tosse intensificou-se, e o\npaciente tornou-se irritado, com dificuldade de mamar em razão da taquidispneia. A mãe relata que,\nhá algumas horas, o filho apresenta \"chiado no peito\". Ao exame físico, observa-se agitação, FR >\n70, tiragem subcostal e batimento de asas do nariz, além de sibilos à ausculta. A mãe nega\nepisódios prévios de sibilância e história familiar de asma ou de alergias de pele. A respeito desse\ncaso clínico, julgue o item a seguir. A frequência respiratória aumentada contraindica a nutrição\npor\nvia oral e, em casos de taquidispneia grave, mesmo a alimentação por sonda deve ser\ndescontinuada.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289411","number":"289411","sourceNumber":"289411","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um lactente de 3 meses de idade, previamente hígido, nascido a termo, com peso\nadequado, sem intercorrências no período\nneonatal, chega à emergência trazido pela mãe, que\nrelata que, há dois dias, o filho apresentava quadro de rinorreia, espirros, tosse, febre, com\ntemperatura axilar máxima de 38,5 °C. Com o passar das horas, a tosse intensificou-se, e o\npaciente tornou-se irritado, com dificuldade de mamar em razão da taquidispneia. A mãe relata que,\nhá algumas horas, o filho apresenta \"chiado no peito\". Ao exame físico, observa-se agitação, FR >\n70, tiragem subcostal e batimento de asas do nariz, além de sibilos à ausculta. A mãe nega\nepisódios prévios de sibilância e história familiar de asma ou de alergias de pele. A respeito desse\ncaso clínico, julgue o item a seguir. Os broncodilatadores são muito usados na prática clínica, mas\no real benefício deles nessa faixa etária ainda carece de comprovação científica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289413","number":"289413","sourceNumber":"289413","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um lactente de 3 meses de idade, previamente hígido, nascido a termo, com peso\nadequado, sem intercorrências no período\nneonatal, chega à emergência trazido pela mãe, que\nrelata que, há dois dias, o filho apresentava quadro de rinorreia, espirros, tosse, febre, com\ntemperatura axilar máxima de 38,5 °C. Com o passar das horas, a tosse intensificou-se, e o\npaciente tornou-se irritado, com dificuldade de mamar em razão da taquidispneia. A mãe relata que,\nhá algumas horas, o filho apresenta \"chiado no peito\". Ao exame físico, observa-se agitação, FR >\n70, tiragem subcostal e batimento de asas do nariz, além de sibilos à ausculta. A mãe nega\nepisódios prévios de sibilância e história familiar de asma ou de alergias de pele. A respeito desse\ncaso clínico, julgue o item a seguir. A infecção pelo vírus sincicial respiratório é a principal\ncausa de\nsibilância em crianças durante os três primeiros anos de vida, e pode contribuir para o\ndesenvolvimento de hiper-responsividade brônquica.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289415","number":"289415","sourceNumber":"289415","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere que um paciente de 9 anos de idade, do sexo masculino, há cinco dias,\napresentou um quadro de rinorreia,\nespirros, cefaleia, tosse e dor de garganta de leve intensidade.\nHá dois dias, evoluiu com febre alta, temperatura axilar > 39 oC, calafrios e queixas de ?cansaço?.\nNo momento da consulta, apresenta-se taquipneico, com retração subcostal leve. A ausculta\nrevelou murmúrio vesicular reduzido à direita, e a radiografia de tórax evidenciou opacificação no\nlobo inferior direito com velamento do seio costofrêncio. Não está em uso de nenhum esquema de\nantibioticoterapia. Com base no caso clínico apresentado, julgue o item a seguir. O derrame pleural\né a principal complicação das pneumonias bacterianas e deve sempre ser pesquisado, quando não\nhouver melhora clínica, após 72 horas de antibioticoterapia.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289418","number":"289418","sourceNumber":"289418","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere que um paciente de 9 anos de idade, do sexo masculino, há cinco dias,\napresentou um quadro de rinorreia,\nespirros, cefaleia, tosse e dor de garganta de leve intensidade.\nHá dois dias, evoluiu com febre alta, temperatura axilar > 39 oC, calafrios e queixas de ?cansaço?.\nNo momento da consulta, apresenta-se taquipneico, com retração subcostal leve. A ausculta\nrevelou murmúrio vesicular reduzido à direita, e a radiografia de tórax evidenciou opacificação no\nlobo inferior direito com velamento do seio costofrêncio. Não está em uso de nenhum esquema de\nantibioticoterapia. Com base no caso clínico apresentado, julgue o item a seguir. A penicilina é a\ndroga apropriada para tratamento do paciente em questão.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289420","number":"289420","sourceNumber":"289420","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere que um paciente de 9 anos de idade, do sexo masculino, há cinco dias,\napresentou um quadro de rinorreia,\nespirros, cefaleia, tosse e dor de garganta de leve intensidade.\nHá dois dias, evoluiu com febre alta, temperatura axilar > 39 oC, calafrios e queixas de ?cansaço?.\nNo momento da consulta, apresenta-se taquipneico, com retração subcostal leve. A ausculta\nrevelou murmúrio vesicular reduzido à direita, e a radiografia de tórax evidenciou opacificação no\nlobo inferior direito com velamento do seio costofrêncio. Não está em uso de nenhum esquema de\nantibioticoterapia. Com base no caso clínico apresentado, julgue o item a seguir. É indicado, nesse\ncaso, fazer nova radiografia de tórax após três dias de tratamento, para avaliar evolução.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289422","number":"289422","sourceNumber":"289422","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere que um paciente de 9 anos de idade, do sexo masculino, há cinco dias,\napresentou um quadro de rinorreia,\nespirros, cefaleia, tosse e dor de garganta de leve intensidade.\nHá dois dias, evoluiu com febre alta, temperatura axilar > 39 oC, calafrios e queixas de ?cansaço?.\nNo momento da consulta, apresenta-se taquipneico, com retração subcostal leve. A ausculta\nrevelou murmúrio vesicular reduzido à direita, e a radiografia de tórax evidenciou opacificação no\nlobo inferior direito com velamento do seio costofrêncio. Não está em uso de nenhum esquema de\nantibioticoterapia. Com base no caso clínico apresentado, julgue o item a seguir. Se o paciente\nfosse um lactente menor de dois meses, com diagnóstico de pneumonia, porém em bom estado\ngeral, apresentando apenas taquipneia leve, sem hipoxemia, ele poderia ser tratado\nambulatorialmente com antibioticoterapia oral, desde que pudesse ser reavaliado em 48 horas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-289424","number":"289424","sourceNumber":"289424","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere que um paciente de 9 anos de idade, do sexo masculino, há cinco dias,\napresentou um quadro de rinorreia,\nespirros, cefaleia, tosse e dor de garganta de leve intensidade.\nHá dois dias, evoluiu com febre alta, temperatura axilar > 39 oC, calafrios e queixas de ?cansaço?.\nNo momento da consulta, apresenta-se taquipneico, com retração subcostal leve. A ausculta\nrevelou murmúrio vesicular reduzido à direita, e a radiografia de tórax evidenciou opacificação no\nlobo inferior direito com velamento do seio costofrêncio. Não está em uso de nenhum esquema de\nantibioticoterapia. Com base no caso clínico apresentado, julgue o item a seguir. Se o derrame\npleural em questão for maior que 1 cm, ele deve ser puncionado para coleta e análise do líquido, e\no paciente deve ser internado para antibioticoterapia endovenosa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-131839","number":"131839","sourceNumber":"131839","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere hipoteticamente que determinado paciente de três anos de idade apresenta\nquadro de febre alta há três dias,\nassociado à coriza, espirros e tosse produtiva. Ao exame físico,\nobserva-se criança em bom estado geral, ativa; reativa; FR = 45 irpm e murmúrio vesicular reduzido\nà ausculta de hemitórax direito. A radiografia de tórax evidenciou infiltrado broncopneumônico em\nhemitórax direito, velamento de seio costofrênico à direita e leve desvio de traqueia para a\nesquerda. Foi realizado toracocentese com saída de secreção purulenta com pH de 7,1 e glicose\nde 36 mg/dl. Com base nesse caso, assinale a alternativa que indica a conduta CORRETA:","options":{"A":"Tratamento ambulatorial com uso de amoxicilina oral por dez dias com orientação de retorno em\n48 horas para reavaliação clínica.","B":"Internação hospitalar e antibioticoterapia parenteral.","C":"Internação hospitalar, antibioticoterapia parenteral, oxigenoterapia e drenagem torácica\nfechada.","D":"Internação hospitalar, antibioticoterapia parenteral, oxigenoterapia e nova toracocentese de\nalívio, se necessário.","E":"Internação hospitalar para observação clínica por, no mínimo, 24 horas e avaliação quanto à\nnecessidade de iniciar antibioticoterapia dependendo da evolução clínica do paciente."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-135076","number":"135076","sourceNumber":"135076","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Acerca de doença péptica ulcerosa gastroduodenal na infância, julgue o item a seguir.\nO tratamento antibacteriano é recomendado para\ncrianças sintomáticas com diagnóstico de H.\npylori.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"inferred","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-140749","number":"140749","sourceNumber":"140749","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A respeito das doenças infecciosas, julgue o seguinte item. Crianças com otite média\naguda bilateral associada ao quadro de conjuntivite purulenta apresentam maior probabilidade de\nter o Haemophilus inflluenzae como patógeno responsável pela infecção.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-105577","number":"105577","sourceNumber":"105577","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa que apresenta o agente causador e os sintomas da colite\ndisentérica aguda.","options":{"A":"Entamoeba histolytica: dor abdominal, diarreia com fezes líquidas contendo sangue e muco, às\nvezes tenesmo e febre ausente ou baixa.","B":"Giardíase: dor abdominal e diarreia com fezes líquidas com muco e sem sangue, às vezes\ntenesmo e febre ausente ou baixa.","C":"Escherichia coli enteropatogênica: dor abdominal e diarreia com fezes líquidas contendo muco e\nsangue e febre ausente ou baixa.","D":"Ancilostomíase: diarreia com muco, dores abdominais, febre baixa e vômitos.","E":"Estrongiloidíase: diarreia com muco, sangue e, às vezes, tenesmo. Pode ocorrer febre\nmoderada."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-105569","number":"105569","sourceNumber":"105569","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"As manifestações clínicas na hipersensibilidade alimentar são variadas e acometem\nvários órgãos. Em relação ao diagnóstico,\nassinale a alternativa CORRETA:","options":{"A":"As manifestações predominantemente respiratórias, como tosse e broncoespasmo, geralmente\nsão isoladas, o que dificulta muito o diagnóstico.","B":"As manifestações gastrointestinais incluem comumente diarreia aguda ou crônica, entretanto,\nraramente acarretam retardo do crescimento, dado\nimportante para o diagnóstico diferencial no\nacompanhamento do crescimento e desenvolvimento.","C":"As manifestações cutâneas são incomuns, sendo principal a dermatite atópica.","D":"Os principais alimentos responsáveis por alergia alimentar, nos dois primeiros anos de vida, são\no leite de vaca e o trigo, por isso o leite\nde soja tem sido amplamente indicado como substituto.","E":"A reação mais grave é a anafilaxia, ocorrendo logo após a ingestão do alimento, podendo levar\nao choque. Tem diagnóstico diferencial com aspiração broncopulmonar."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-105553","number":"105553","sourceNumber":"105553","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"As características mais frequentes do hemograma na coqueluche, que é causada pela\nBordetella pertussis, na forma clínica, com tosse intensa, são:","options":{"A":"Leucocitose intensa com linfocitose.","B":"Leucocitose intensa com neutrofilia.","C":"Leucocitose moderada com neutropenia.","D":"Leucopenia com linfocitose.","E":"Leucopenia com neutrofilia."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108231","number":"108231","sourceNumber":"108231","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Julgue o item que se segue, relativo as doenças infecciosas na infância e na\nadolescência. Suponha que um adolescente tenha\nprocurado uma unidade de pronto atendimento\nqueixando-se de mau hálito e dificuldade de ingerir alimentos havia quatro dias e que, no exame\nfísico, o médico tenha observado que o paciente apresentava acentuada halitose, gengivas\nedemaciadas, hiperemiadas e com úlceras entre os dentes sisos e segundos molares,\npseudomembrana em amigdalas e micropoliadenopatia cervical. Nesse caso, o diagnóstico do\npaciente é de monilíase oral, e o tratamento a ser adotado, além da higienização oral, consiste na\nadministração de nistatina por via oral.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108174","number":"108174","sourceNumber":"108174","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"No item abaixo é apresentado um caso clínico referente a doenças respiratórias na\ninfância, seguido de uma assertiva a ser\njulgada. Um escolar de nove anos de idade, com\ndificuldade para respirar, foi levado pela mãe a uma emergência pediátrica. A mãe informou que,\nhavia dois meses, esse quadro vinha se repetindo semanalmente, que os sintomas cediam\ntemporariamente com o uso de beta-2-adrenérgicos e que a atividade e o sono do paciente ficavam\nlimitados na vigência do quadro. O médico, após examiná-lo, admnistrou beta-2-adrenérigco por via\ninalatória e o encaminhou ao ambulatório para avaliação da função respiratória, que apresentou o\nseguinte resultado: volume expiratório forçado ao final do primeiro minuto (VEF1)\n\npré-broncodilatador = 85% do previsto com variação de VEF1 igual a 25%. Nesse caso, as\nDiretrizes Brasileiras para o Manejo da Asma\nrecomendam tratamento com beta-2-adrenérgico por\nvia inalatória para alívio dos sintomas e corticoide inalatório em baixa dosagem.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108188","number":"108188","sourceNumber":"108188","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"No item abaixo é apresentado um caso clínico referente a doenças respiratórias na\ninfância, seguido de uma assertiva a ser\njulgada. Um lactente de um mês de idade, nascido de\nparto vaginal, apresentava tosse seca havia uma semana. O exame físico do bebê constatou\ntemperatura axilar de 37°C, hiperemia, edema e secreção serosa em conjuntivas, leve taquipneia e\nmurmúrio vesicular rude com creptações disseminadas à ausculta pulmonar. Foi realizada\nradiografia do tórax, conforme ilustrado a seguir (VER IMAGEM). Nesse caso, o diagnóstico mais\nprovável é pneumonia por Chlamydia trachomatis, e o tratamento do paciente deve ser realizado\ncom azitromicina, na dose de 30 mg/kg por cinco dias.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108199","number":"108199","sourceNumber":"108199","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"No item abaixo é apresentado um caso clínico referente a doenças respiratórias na\ninfância, seguido de uma assertiva a ser\njulgada. Um menino de quatro anos de idade, morador de\numa instituição de apoio a menores abandonados, foi levado a uma emergência pediátrica com\nhistória de febre alta havia três dias. Nesse período, o quadro clínico evoluiu para dificuldade\nrespiratória e gemência. No exame físico da criança, foram constatados, além de febre e dificuldade\nrespiratória, palidez, aspecto toxêmico, sinais de desidratação e uma lesão pustulosa tensa no\nmembro inferior direito. A radiografia de tórax do paciente apresentou o seguinte aspecto (VER\nIMAGEM). Nesse caso, a criança deverá receber tratamento específico à base de oxacilina.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-108217","number":"108217","sourceNumber":"108217","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A mãe de um lactente de sete meses de idade queixa-se de que, desde que, há cerca\nde um mês, iniciou a alimentação\ncomplementar ao aleitamento materno - papa de frutas e\nlegumes, e leite de vaca - a criança passou a apresentar vômitos e diarreia com rajas de sangue.\nNo exame físico, o médico observou peso/idade no escore Z - 1; bom estado geral, hidratado,\ncorado e eritema descamativo em couro cabeludo e face. Com referência ao caso clínico acima\napresentado, julgue o próximo item: O diagnóstico clínico provável para o lactene em questão é\nintolerância à lactose.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-352324","number":"352324","sourceNumber":"352324","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Infecções urinárias (ITU) são a causa mais comum de DBG em crianças jovens, com\nrisco de lesão renal permanente. A\nprevalência de infecção urinária em crianças varia de 2 a 5%,\nmas há certos grupos nos quais esse risco é maior. Considerando o caráter informativo do texto, o\ntema abordado e os conceitos relacionados à Febre sem sinais localizatórios (FSSL), julgue o item\nTrata-se de doença altamente infecciosa transmitida pelo Paramyxovirus.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-352323","number":"352323","sourceNumber":"352323","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Infecções urinárias (ITU) são a causa mais comum de DBG em crianças jovens, com\nrisco de lesão renal permanente. A\nprevalência de infecção urinária em crianças varia de 2 a 5%,\nmas há certos grupos nos quais esse risco é maior. Considerando o caráter informativo do texto, o\ntema abordado e os conceitos relacionados à Febre sem sinais localizatórios (FSSL), julgue o item\nPneumonia é a principal complicação bacteriana.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-352322","number":"352322","sourceNumber":"352322","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Infecções urinárias (ITU) são a causa mais comum de DBG em crianças jovens, com\nrisco de lesão renal permanente. A\nprevalência de infecção urinária em crianças varia de 2 a 5%,\nmas há certos grupos nos quais esse risco é maior. Considerando o caráter informativo do texto, o\ntema abordado e os conceitos relacionados à Febre sem sinais localizatórios (FSSL), julgue o item\nDevido à sua prevalência na infância, a gravidade da doença tende a ser menor em adolescentes e\nadultos.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-352321","number":"352321","sourceNumber":"352321","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Infecções urinárias (ITU) são a causa mais comum de DBG em crianças jovens, com\nrisco de lesão renal permanente. A\nprevalência de infecção urinária em crianças varia de 2 a 5%,\nmas há certos grupos nos quais esse risco é maior. Considerando o caráter informativo do texto, o\ntema abordado e os conceitos relacionados à Febre sem sinais localizatórios (FSSL), julgue o item\nA prevenção é viável por meio de uma vacina contendo vírus vivo e atenuado, administrada a partir\ndo 12.° mês de vida, com uma dose de reforço recomendada entre 4 e 5 anos de idade, bem como\noutra dose durante a adolescência.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-343395","number":"343395","sourceNumber":"343395","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A cianose é um sinal encontrado na cardiopatia congênita denominada de:","options":{"A":"Coarctação da aorta.","B":"Persistência do canal arterial.","C":"Tetralogia de Fallot.","D":"Edema da flebite."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-343405","number":"343405","sourceNumber":"343405","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Com relação às cardiopatias congênitas, é INCORRETO afirmar:","options":{"A":"A Tetralogia de Fallot é uma cardiopatia cianogênita caracterizada pela presença de\ncomunicação interventricular, dextroposição da\naorta, estenose pulmonar e hipertrofia de ventrículo\ndireito.","B":"A Anomalia de Ebstein é uma cardiopatia congênita, caracterizada por uma malformação da\nválvula mitral, cuja abertura é deslocada em\ndireção ao ápice do ventrículo direito, o que causa uma\natrialização do mesmo.","C":"No diagnóstico da Coarctação de Aorta está presente o sinal clássico, que é a diferença de\npulso e pressão de membros superiores e inferiores.","D":"A Comunicação Interventricular é a cardiopatia congênita mais comum e caracteriza-se por uma\nabertura ou orifício na parede (septo) que divide os ventrículos (câmaras que bombeiam o sangue)\ndireito e esquerdo."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-343408","number":"343408","sourceNumber":"343408","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Choque é a situação em que há inadequado fluxo de sangue e oxigênio para suprir a\ndemanda metabólica. É sinal clínico de choque compensado:","options":{"A":"Pressão sistólica normal.","B":"Acidose metabólica.","C":"Pulsos centrais fracos.","D":"Taquipneia."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-334893","number":"334893","sourceNumber":"334893","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A parada cardiorrespiratória (PCR) é a cessação da atividade mecânica cardíaca eficaz,\nconfirmada pela tríade inconsciência, ausência de pulso central e de respiração. Muitas vezes, na\ninfância, ela está associada a uma condição reversível; dessa forma, o seu tratamento precoce e\nbem conduzido pode melhorar o prognóstico do atendimento da criança. O atendimento da PCR\ninicia-se com o suporte básico de vida (SBV). Quanto às recomendações de SBV em pediatria,\nassinale a alternativa correta.","options":{"A":"O evento cardíaco primário é causa mais comum de PCR em lactentes e crianças do que por\nhipoxemia grave.","B":"Deve-se atrasar o uso de epinefrina na PCR pediátrica, com o objetivo de aguardar a resposta\nàs compressões torácicas.","C":"Em lactentes até 1 ano de idade, o socorrista deve realizar as compressões torácicas com a\nmão espalmada em todo o tórax e com o braço estendido.","D":"As compressões torácicas e a ventilação devem ser sincronizadas. Em crianças, devem ser 2\ncompressões para 15 ventilações.","E":"A sequência do SBV deve ser C-A- B (compressão ? via aérea ? respiração) ao invés de de\nA-B-C (via aérea ? respiração ? circulação/compressão)."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-343419","number":"343419","sourceNumber":"343419","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Quanto ao sarampo, nas crianças imunossuprimidas, pode haver exantema petequial\nou purpúrico e são possíveis complicações graves\nsem associação à erupção, EXCETO:","options":{"A":"Hepatite.","B":"Espasmos.","C":"Pneumonia.","D":"Encefalite."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-307108","number":"307108","sourceNumber":"307108","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um paciente de 2 anos de idade apresenta quadro de febre persistente há sete dias,\neritema labial, hiperemia difusa de mucosa\norofaríngea e proeminência das papilas linguais, bem\ncomo hiperemia conjuntival bilateral, não purulenta, indolor. Além disso, tem também hiperemia\npalmar, edema de dorso de mãos e pés, exantema polimórfico, sem vesículas em tronco e períneo,\ne linfadenopatia cervical medindo 1,5 cm, unilateral. Exames laboratoriais indicaram leucocitose\ncom neutrofilia (> 15.000 mm³), trombocitose (> 450.000 mm³) e elevação de provas de atividade\ninflamatória (VHS e PCR). No que se refere ao melhor diagnóstico e à conduta nesse caso clínico,\nassinale a alternativa correta. Alternativas:","options":{"A":"Leucemia linfoblástica aguda ? Quimioterapia","B":"Eritema nodoso ? Gamaglobulina","C":"Púrpura de Henoch-Schönlein ? Corticosteroide","D":"Sarampo ? Tratamento de suporte","E":"Doença de Kawasaki ? Imunoglobulina humana intravenosa"},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-307111","number":"307111","sourceNumber":"307111","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação às imunodeficiências primárias que atualmente são denominadas erros\ninatos da imunidade, assinale a alternativa correta. Alternativas:","options":{"A":"Um episódio de molusco contagioso deve ser sempre investigado.","B":"A imunodeficiência combinada grave é uma deficiência da imunidade celular.","C":"Otite externa de repetição é um sinal de alerta.","D":"Atraso do desenvolvimento deve ser investigado no segundo ano de vida.","E":"Helmintíase isolada pode ser um sinal clínico."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-307112","number":"307112","sourceNumber":"307112","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 6 anos de idade apresenta quadro clínico de varicela, em seu estágio\ninicial, e febre de 38,7 ºC. A criança é\nportadora de uma pneumopatia crônica em acompanhamento\ne teve contato com sua irmã gestante não imunizada. A respeito da melhor conduta para esse caso\nclínico, assinale a alternativa correta. Alternativas:","options":{"A":"Prescrever aciclovir oral.","B":"Prescrever o uso de ácido acetilsalicílico para a febre.","C":"Orientar a irmã a procurar o posto de saúde para fazer imunização.","D":"Acalmar a irmã, pois a varicela não é infecciosa para o feto.","E":"Prescrever o uso de antibiótico profilático para evitar infecção secundária das lesões por\nfungos."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-301292","number":"301292","sourceNumber":"301292","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um RN com 18 dias de vida foi levado à emergência pela mãe. Ela relata que seu filho,\nalém de apresentar febre, tem mamado menos e está chorando mais que o habitual. Ao exame\nfísico, afere-se temperatura de 38,5 ºC, frequência cardíaca está um pouco aumentada, porém o\nrestante do exame físico encontra-se normal. Com base no caso clínico apresentado, julgue os\nitens de 47 a 51. A maioria das bactérias patogênicas cresce nas primeiras 24 horas a 36 horas\napós a coleta da cultura; por isso, a hospitalização, a observação clínica e a monitorização do RN\nsem antibioticoterapia é o preconizado atualmente e sem risco de ele desenvolver doença\nbacteriana grave.","options":{"A":"CERTO","B":"ERRADO"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-301293","number":"301293","sourceNumber":"301293","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um RN com 18 dias de vida foi levado à emergência pela mãe. Ela relata que seu filho,\nalém de apresentar febre, tem mamado menos e está chorando mais que o habitual. Ao exame\nfísico, afere-se temperatura de 38,5 ºC, frequência cardíaca está um pouco aumentada, porém o\nrestante do exame físico encontra-se normal. Com base no caso clínico apresentado, julgue os\nitens de 47 a 51. Caso esse RN apresente-se em estado geral bom, sugando bem, e se os exames\nrevelarem resultados normais, acompanhados de culturas negativas, ele poderá receber alta sem\nantibióticos. Caso seja feito diagnóstico de infecção do trato urinário (ITU), ele deverá continuar\ninternado com antibioticoterapia parenteral endovenosa.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-301294","number":"301294","sourceNumber":"301294","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um RN com 18 dias de vida foi levado à emergência pela mãe. Ela relata que seu filho,\nalém de apresentar febre, tem mamado menos e está chorando mais que o habitual. Ao exame\nfísico, afere-se temperatura de 38,5 ºC, frequência cardíaca está um pouco aumentada, porém o\nrestante do exame físico encontra-se normal. Com base no caso clínico apresentado, julgue os\nitens de 47 a 51. Uma grande preocupação dos pediatras é diferenciar se a febre de uma criança\ntrata-se de uma doença benigna autolimitada, daqueles poucos casos em que se pode ter como\ncausa uma infecção bacteriana grave (IBG). Pela dificuldade de avaliação clínica, menor função\nimunológica, imunização incompleta e maior frequência de IBG em RNs (neonatos com até 28 dias\nde vida), a maioria dos serviços tem adotado a prática de triar todos os RNs febris para avaliação\nde sepse, hospitalizar e iniciar antibioticoterapia empírica até a obtenção de resultados de\nculturas.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-273311","number":"273311","sourceNumber":"273311","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Marque a alternativa que corresponde a sinal de alerta para Imunodeficiência primária\nna criança:","options":{"A":"Três ou mais infecções virais de vias aéreas nos dois primeiros anos de vida.","B":"Duas pneumonias graves em um ano.","C":"Dengue grave com choque hemorrágico.","D":"Cicatriz vacinal após BCG."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-291460","number":"291460","sourceNumber":"291460","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um recém-nascido com 20 dias de vida dá entrada em serviço médico de urgência com\nhistória referida de queda da cama após ter rolado para fora dela há 6 horas. Pais referem\nhipoatividade desde então. Ao exame, está em regular estado geral e apresenta hematoma\nsubgaleal em região parietal. A fundoscopia evidencia hemorragia retiniana bilateral e a tomografia\nde crânio apresenta hemorragia subaracnóidea, sem sinais de fratura. Com base nos dados\napresentados, o diagnóstico mais provável é:","options":{"A":"Traumatismo crânio encefálico decorrente da queda da cama.","B":"Acidente vascular cerebral decorrente de malformação vascular.","C":"Síndrome de shaken baby (bebê sacudido) decorrente de maus-tratos.","D":"Tromboembolismo gorduroso resultante da queda."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-273318","number":"273318","sourceNumber":"273318","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 7 meses, apresentando história de febre alta há 4 dias (39 ? 40ºC). A mãe\nprocurou assistência médica por 3 dias consecutivos porque a febre retornava algumas horas após\no uso de antitérmicos. Refere que a criança manteve-se em BEG e aceitando bem a alimentação\ndurante esses dias, só ficando mais ?enjoadinha? em vigência da febre. Ao exame físico não foram\nencontradas alterações, mas após a terceira consulta, o médico resolveu prescrever Amoxicilina.\n\nNesse mesmo dia, a mãe refere que a febre desapareceu. Porém, 24 horas depois, a criança\napresentou um ?grosseirão? não pruriginoso em\ntronco. Ao exame físico, criança em BEG, com\npápulas eritematosas discretas no tronco, sem outras alterações. O diagnóstico clínico e a etiologia\nsão respectivamente:","options":{"A":"Farmacodermia induzida pela Amoxicilina.","B":"Exantema súbito; Herpes vírus tipo 6.","C":"Impetigo; Stafilococcus aureus.","D":"Síndrome de Stevens-Johnson induzida pela Amoxicilina."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-268904","number":"268904","sourceNumber":"268904","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma paciente de 2 anos de idade, procedente da zona rural, é atendida em um hospital\ncom febre alta (? 38,5 ºC), exantema maculopapular generalizado, tosse, coriza e conjuntivite. O\nquadro evoluiu com descamação leve. Na Caderneta da Criança, verifica-se ausência de várias\nvacinas. Considerando esse caso clínico e os conhecimentos médicos correlatos, assinale a\nalternativa correta.","options":{"A":"Trata-se de um quadro típico de varicela, sendo necessário antibioticoterapia oral.","B":"Esse quadro clínico poderia ter sido prevenido com o reforço da vacina tríplice bacteriana aos 18\nmeses de idade.","C":"No período toxêmico, são frequentes as complicações, principalmente nos menores de 2 anos\nde idade.","D":"A descamação da pele é restrita em mãos e pés.","E":"Os novos surtos ocorridos no Brasil aconteceram em razão dos longos intervalos entre as doses\nda vacina."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-268910","number":"268910","sourceNumber":"268910","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 4 anos de idade é internada na enfermaria em razão de quadro de\nfebre alta (40ºC), extrema irritabilidade há\nseis dias, conjuntivite não purulenta, língua em\nframboesa, eritema de orofaringe, fissuras e eritema labial, e edema de mãos e pés com\ndescamação periungueal. Apresenta precórdio hiperdinâmico com taquicardia e sopro pansistólico,\nFC = 120 bpm, TAX = 40ºC, SatO2 = 97% e FR = 32 irpm. No exame laboratorial, identifica-se\ntrombocitose. Nesse caso clínico, o diagnóstico mais provável é","options":{"A":"parotidite epidêmica.","B":"escarlatina.","C":"arterite de Takayasu.","D":"púrpura trombocitopênica.","E":"doença de Kawasaki."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-274623","number":"274623","sourceNumber":"274623","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Rubéola é uma infecção contagiosa causada por vírus e caracterizada por erupções\nvermelhas na pele. O período de incubação do vírus da rubéola é:","options":{"A":"2 a 10 dias.","B":"10 a 16 dias.","C":"14 a 21 dias.","D":"15 a 25 dias."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-291495","number":"291495","sourceNumber":"291495","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um lactente, de 6 meses de idade, comparece sem queixas ao consultório médico com\nhistória de internações devido a infecção urinária alta aos 20 dias e aos 3 meses. Com 5 meses,\napresentou quadro de febre intermitente, inapetência e vômitos, com exame qualitativo de urina\nque apontou nitrito (+), esterase leucocitária (+) e urocultura colhida por sondagem vesical com\nmais de 100 000 UFC/ml de E, coli, tendo completado o tratamento com antimicrobiano com\nremissão dos sintomas. Realizado ultrassonografia durante a última internação que não verificou\nalterações. Como forma de estender a investigação, assinale a alternativa correta quanto ao exame\npadrão-ouro para essa situação.","options":{"A":"Cintilografia renal com DMSA.","B":"Urografia excretora.","C":"Uretrocistografia miccional.","D":"Ressonância magnética de abdome."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-291496","number":"291496","sourceNumber":"291496","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um menino de 4 anos de idade, previamente hígido e com acompanhamento pediátrico\nregular, chega ao pronto atendimento com\nqueixa de febre (temperatura axilar superior a 38,5ºC em\ntodos os picos), há 6 dias, acompanhada de conjuntivite bilateral não exsudativa. Nega uso prévio\nde medicação nesses últimos dias, exceto o antitérmico habitual para controle da febre. Nega\nviagens recentes ou contato com indivíduos sabidamente doentes. Ao exame clínico, observa-se\nhiperemia de orofaringe sem exsudato ou ulcerações; presença de ressecamento, fissuras e\nhiperemia em lábios e proeminência das papilas linguais; gânglio cervical anterior à direita com\ncerca de 1,5 cm de diâmetro não doloroso; edema endurecido em dorso das mãos e pés com\neritema palmar e plantar difuso; e presença de exantema polimórfico mais intenso em tronco e\nperíneo. Sem outras alterações. Assinale a alternativa que contenha o diagnóstico provável para o\ncaso apresentado e uma complicação associada ao quadro.","options":{"A":"Escarlatina; glomerulonefrite difusa aguda.","B":"Doença de Kawasaki; aneurisma coronariano.","C":"Mononucleose; síndrome de Guillain-Barré.","D":"Sarampo; panencefalite esclerosante subaguda."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-274628","number":"274628","sourceNumber":"274628","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considerando a doença de escarlatina:","options":{"A":"Escarlatina é uma doença infectocontagiosa aguda, provocada pela bactéria Propionibacterium\nbeta-hemolítico do grupo A, que acomete especialmente as crianças em idade escolar (de 2 a 10\nanos).","B":"Escarlatina é uma doença infectocontagiosa aguda, provocada pela bactéria Staphylococcus\nque acomete especialmente as crianças em idade\nescolar (de 2 a 10 anos).","C":"Escarlatina é uma doença infectocontagiosa aguda, provocada pela bactéria Estreptococo\nbeta-hemolítico do grupo A, que acomete\nespecialmente as crianças em idade escolar (de 2 a 10\nanos).","D":"Escarlatina é uma doença infectocontagiosa aguda, provocada pela bactéria Estreptococo\nbeta-hemolítico do grupo B, que acomete\nespecialmente as crianças em idade escolar (de 2 a 10\nanos)."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-263389","number":"263389","sourceNumber":"263389","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança com 7 anos de idade, do sexo feminino, é atendida na Unidade Básica de\nSaúde devido à enurese noturna há cerca de 6\nmeses, com 2 a 3 episódios de perda involuntária\nde urina à noite por semana. A criança havia apresentado controle de esfíncter vesical à noite aos 5\nanos de idade. A mãe afirma que a queixa principal coincidiu com o nascimento de seu filho mais\nnovo, o que levou a mudanças na rotina da família, entre elas, a menina passou a ficar com os\navós durante o dia, só retornando para casa à noite. Nesse caso, qual deve ser a conduta inicial?","options":{"A":"Terapia com anticolinérgicos.","B":"Terapia com desmopressina.","C":"Terapia com amitriptilina.","D":"Terapia comportamental."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-263394","number":"263394","sourceNumber":"263394","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um pré-escolar com 4 anos de idade foi diagnosticado com COVID-19 há 30 dias, sem\ncomplicações na época. Há 5 dias, tem tido febre diária, 38 a 40 °C, persistente. No segundo dia de\nfebre, apresentou língua em framboesa, linfadenite cervical unilateral (3 cm), tendo recebido, na\nocasião, dose única de penicilina benzatina. Hoje, quinto dia, é atendido no pronto-socorro com\npersistência da febre. Ao exame físico, encontra-se clinicamente hidratado, com hiperemia\nconjuntival bilateral não purulenta, exantema escarlatiniforme, edema em mãos e pés. Em face\ndesse quadro clínico, o exame complementar e o tratamento indicados são, respectivamente,","options":{"A":"sorologia para Epstein-Baar; corticoterapia via oral.","B":"ecocardiograma; aplicação de gamaglobulina via endovenosa.","C":"IgG e IgM para sarampo; reposição de vitamina A via endovenosa.","D":"reação em cadeia da polimerase para espiroquetas; doxiciclina via oral."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-263406","number":"263406","sourceNumber":"263406","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança com 8 anos de idade é atendida na emergência com exantema. Segundo\nsua mãe, o quadro clínico iniciou-se há 2\ndias com febre alta, calafrios, vômitos, cefaleia,\nprostração e odinofagia. Há 1 dia, surgiu exantema em pescoço, axilas e virilhas, generalizando-se\na seguir. Ela nega antecedentes patológicos relevantes. Em exame físico, a criança apresenta\nestado geral regular, corada, hidratada; com amígdalas hiperemiadas, hipertrofiadas e recobertas\npor exsudato purulento. Ao redor da boca, observa-se palidez e, nas demais áreas da pele,\nexantema papular, eritematoso e áspero. Há linhas hiperpigmentadas em áreas de flexão da pele.\nPara esse caso, o exame laboratorial que confirma o diagnóstico é","options":{"A":"dosagem de anticorpos heterófilos.","B":"dosagem de imunoglobulinas.","C":"dosagem de antígenos NS1.","D":"cultura de orofaringe."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-263425","number":"263425","sourceNumber":"263425","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma lactente com 1 ano de idade foi levada à Unidade Básica de Saúde para\natendimento. A mãe relatou que a menina\napresentava uma tumoração na região inguinal direita\ndurante o banho, porém que tinha desaparecido no dia seguinte. Durante o exame físico, foi\nconfirmada uma nodulação na região inguinal direita, móvel, indolor, redutível e com\ntransiluminação negativa. Nesse caso, a suspeita diagnóstica e a conduta terapêutica corretas são","options":{"A":"adenomegalia inguinal e manter conduta expectante.","B":"hérnia inguinal e realizar tratamento operatório eletivo.","C":"hérnia inguinal e aguardar a regressão espontânea até os 5 anos de idade.","D":"cisto do canal de Nuck e aguardar a regressão espontânea até os 5 anos de idade."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-263434","number":"263434","sourceNumber":"263434","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma lactente com 1 ano e 10 meses de idade, previamente hígida, foi atendida no\npronto-socorro com quadro de febre e\nirritabilidade iniciado há 72 horas. Não foram encontradas\nalterações em exame físico realizado na criança. Procedeu-se, então, à coleta de urina tipo 1 por\nsondagem vesical e hemograma. A criança foi encaminhada ao ambulatório para verificação dos\nexames. O hemograma revelou Hb = 11,8 g/dl (valor de referência: 12,6 ± 1,5 g/dl), Ht = 38% (valor\nde referência: 37 a 40%), leucócitos = 18.000 mm³ (valor de referência: 5.000 a 15.000/mm³),\nplaquetas = 300.000 mm³ (valor de referência: 150.000 a 450.000/mm³), segmentados = 60%,\nlinfócitos = 37% e monócitos = 3%. O exame de urina tipo 1 apresentou densidade = 1.015 (valor\nde referência: 1.005 a 1.030), pH = 5,7 (valor de referência: 5,5 a 7,5), leucócitos = 180.000/ml\n(valor de referência: até 10.000/ml), hemácias = 10.000/ml (valor de referência: até 10.000/ml),\ncilindros piocitários raros, nitrito positivo e a bacterioscopia mostrou a presença de agente\n\nGram-negativo. Diante desse quadro clínico, a conduta médica indicada é:","options":{"A":"Encaminhar a criança para tratamento hospitalar com indicação de antibioticoterapia parenteral\nempírica.","B":"Solicitar urocultura com antibiograma e aguardar o resultado para orientação da\nantibioticoterapia adequada.","C":"Solicitar urocultura com antibiograma e iniciar antibioticoterapia domiciliar empírica, antes da\nobtenção do resultado do exame.","D":"Iniciar antibioticoterapia domiciliar empírica imediatamente, sem necessidade de outros exames,\ne reavaliar a criança em 24 horas."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-230562","number":"230562","sourceNumber":"230562","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa que NÃO apresenta medidas que podem auxiliar na prevenção\nda recorrência de ITU:","options":{"A":"Intervir ou prevenir a constipação intestinal.","B":"Encorajar o aumento do consumo hídrico.","C":"Consumir probióticos e suco de cranberry.","D":"Realizar micção dupla (fazer um novo esforço para esvaziar completemente a bexiga ao final do\nprimeiro jato urinário) e urinar a cada 2 ou 3 horas, se tiver controle esficteriano."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-244482","number":"244482","sourceNumber":"244482","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"No pronto-socorro, é admitida uma paciente de 11 meses de vida, previamente hígida,\ncom história de febre alta há quatro dias,\ntosse, coriza, vermelhidão e secreção nos olhos. No dia\nanterior, a mãe notou uma vermelhidão e secreção atrás das orelhas da criança, que hoje já se\nestendeu pelo corpo. Ao exame físico, a criança está em regular estado geral, febril, eupneica, sem\nvisceromegalias, e apresenta mancha esbranquiçada em mucosa jugal e exantema maculopapular\nmorbiliforme em tronco e pescoço e moderada hiperemia conjuntival bilateral com secreção clara.\nPossui antecedente de viagem há 10 dias. Frequenta creche domiciliar improvisada e tem esquema\nvacinal completo para idade equivalente a 5 meses. Considerando essa história\n\nclínico-epidemiológica, assinale a alternativa que apresenta a principal hipótese diagnóstica que\ndeve ser prontamente diagnosticada nesse caso\nclínico.","options":{"A":"Pneumonia pneumocócica","B":"Exantema súbito","C":"Sarampo","D":"Dengue","E":"Gripe"},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-230569","number":"230569","sourceNumber":"230569","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre a escolha da cânula de intubação orotraqueal usada na população pediátrica,\nassinale a alternativa CORRETA:","options":{"A":"O número deverá ser determinado a partir do tamanho do menor dedo da mão direita da criança.","B":"Não se deve utilizar fio guia no interior da cânula.","C":"As cânulas com cuff podem ser utilizadas em crianças, desde que a pressão seja mantida acima\nde 20cmH2O.","D":"Sempre que possível, deve-se utilizar caulas com cuff em crianças."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-230576","number":"230576","sourceNumber":"230576","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa que apresenta o número de canula de intubação orotraqueal\nMAIS adequado para uma criança de 4 anos de idade:","options":{"A":"4,5 com cuff.","B":"5,0 sem cuff.","C":"2,5 sem cuff.","D":"5,5 com cuff."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-203133","number":"203133","sourceNumber":"203133","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma lactente de 4 meses de vida com diagnóstico de imunodeficiência congênita\ncombinada grave precisa realizar atualização do\ncartão vacinal, pois não recebeu qualquer dose de\nvacina desde a alta da maternidade. Com base nesse caso clínico, assinale a alternativa que\napresenta as vacinas indicadas para essa paciente.","options":{"A":"Vacina poliomelite 1, 2, 3 inativada, pneumocócica 23-valente, meningocócica C.","B":"Tríplice bacteriana (DTPw), vacina poliomelite 1, 2, 3 inativada, rotavírus.","C":"Vacina poliomelite 1, 2, 3 inativada, rotavírus, meningocócica C.","D":"Tríplice bacteriana (DTPw), pneumocócica 23-valente, rotavírus.","E":"Tríplice bacteriana (DTPw), rotavírus, meningocócica C."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-203160","number":"203160","sourceNumber":"203160","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um recém-nascido de 2 meses de vida é atendido em um pronto-socorro infantil com\nhistórico de febre iniciada há um dia, de até 38°C, acompanhada de tosse seca e coriza hialina. A\nmãe refere que a criança apresentou um episódio de vômito após crise tussígena. Nega\ndesconforto respiratório, cianose ou outros sintomas associados. Ao exame físico, encontrava-se\nhemodinamicamente estável, com FR = 32 irpm e SpO? = 95% em ar ambiente. Ausculta pulmonar\ncom roncos de transmissão, sem sinais de desconforto respiratório. Foi realizada a radiografia de\ntórax apresentada. Considerando esse caso clínico, é correto afirmar que a seta apresentada na\nimagem é sugestiva de:","options":{"A":"Consolidação.","B":"Timo.","C":"Broncoaspiração.","D":"Atelectasia.","E":"Arco aórtico."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-206079","number":"206079","sourceNumber":"206079","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Durante o exame físico de um lactente, você nota um sopro sistólico discreto em bordo\nesternal esquerdo alto, desdobramento de segunda bulha, fígado a 2 cm do rebordo costal direito e\nbloqueio de ramo direito ao eletrocardiograma. Qual a cardiopatia congênita mais provável?","options":{"A":"Comunicação interventricular.","B":"Canal arterial amplo.","C":"Forame oval pérvio.","D":"Comunicação interatrial."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-206080","number":"206080","sourceNumber":"206080","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"RN sexo masculino, nasceu de parto normal, sem intercorrências na sala de parto,\nsendo encaminhado com a mãe para o alojamento\nconjunto. Com 14 horas de vida evolui com\nquadro de taquidispnéia, diaforese, irritabilidade intensa com dificuldade para amamentar. Foi\nlevado para berçário, apresentou piora da taquidispnéia com necessidade de ventilação mecânica.\nAo exame físico estava em mau estado geral, pálido, extremidades frias, saturação periférica de O2\nde 55%, precórdio calmo sem abaulamentos ou retrações, ausculta cardíaca sem sopros com 2a\nbulha única e hiperfonética no segundo espaço intercostal esquerdo. PA no MSE 63x22 mmHg e\nno MIE de 60x24mmHg. Qual a principal hipótese diagnóstica e a conduta imediata frente a este\nrecém-nascido?","options":{"A":"Tetralogia de Fallot com canal arterial restritivo e iniciar ibuprofeno.","B":"Interrupção do arco aórtico e iniciar prostaglandina endovenosa.","C":"Transposição das grandes artérias com forame oval restritivo e iniciar prostaglandina\nendovenosa.","D":"Comunicação interventricular e iniciar furosemida."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-206083","number":"206083","sourceNumber":"206083","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O sopro cardíaco inocente mais comum pode ser vibratório ou musical, traduzindo\nsopro de curta ejeção sistólica, ouvido ao\nlongo da parte média e inferior do bordo esternal\nesquerdo. De acordo com essas informações, assinale a opção CORRETA relativa às\ncaracterísticas do sopro inocente.","options":{"A":"Quadro infeccioso, febre ou ansiedade não alteram as características do sopro inocente.","B":"O sopro inocente é auscultado com maior frequência em crianças entre três e sete anos.","C":"O sopro inocente não se irradia para o ápice, mas para a base e região posterior do coração.","D":"A intensidade do sopro inocente não se modifica com a fase respiratória e nem com mudanças\nde posição da criança."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-177247","number":"177247","sourceNumber":"177247","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança foi levada ao hospital com quadro de pródromos discretos, com febre\nbaixa e sinais respiratórios leves. Em\nseguida, ela manifestou um exantema maculopapular rosado\ne mais claro. Considerando-se o mencionado quadro clínico e os conhecimentos médicos\nrelacionados a ele, é correto afirmar que a provável doença exantemática do paciente é","options":{"A":"dengue.","B":"exanterna súbito.","C":"febre maculosa.","D":"rubéola.","E":"sarampo."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-175112","number":"175112","sourceNumber":"175112","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A canulação intraóssea é um método relativamente simples e eficaz de estabelecer\nacesso vascular rapidamente, há indicação formal\nde realizar este procedimento quando não for\npossível obter acesso vascular periférico nas situações, EXCETO:","options":{"A":"Choque hipovolêmico","B":"Mal convulsivo.","C":"Insuficiência renal crônica","D":"Choque séptico."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-175113","number":"175113","sourceNumber":"175113","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"É contraindicado o acesso intraósseo:","options":{"A":"Quando já houve tentativa anterior de estabelecer acesso intraósseo.","B":"Em condições com ossos frágeis.","C":"Quando houver necessidade de acesso vascular com rapidez.","D":"Quando o paciente estiver em choque hemorrágico."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-175114","number":"175114","sourceNumber":"175114","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Isabelly, 3 meses, chega ao PSI com história de tosse há 4 dias, acompanhada de\nrinorréia e dispnéia, apresentou febre nos\n3 primeiros dias e desde então encontra-se afebril, porém\npiorou muito sua dispnéia. Ao exame físico de entrada, encontrase em MEG, cianótica, anictérica,\nafebril, em apnéia e arresponsiva. Rapidamente, você procura o dado do exame físico que falta\npara realizar a principal e imediata hipótese diagnóstica. A enfermagem monitorou a criança e há\nritmo sinusal no traçado eletrocardiográfico. Escolha a alternativa que corresponda ao dado do\nexame físico que você buscou e, considerando a sua negatividade, elabore o plano de tratamento:","options":{"A":"Pulso carotídeo, iniciar 15 massagens para 2 ventilações e administrar adrenalina 1 ml diluída\nem 9 ml de AD e administra-se 0,1ml/Kg da\ndiluição em bolus.","B":"Pulso carotídeo, iniciar 30 massagens para 2 ventilações e administrar adrenalina 1 ml diluída\nem 9 ml de AD e administra-se 0,01ml/Kg da\ndiluição em bolus.","C":"Pulso braquial, iniciar 15 massagens para 2 ventilações e administrar adrenalina 1 ml diluída em\n9 ml de AD e administra-se 0,1ml/Kg da\ndiluição em bolus.","D":"Pulso braquial, iniciar intubação orotraqueal, após hiperventilação e sequência rápida de\nintubação, com cânula número 3,5 sem cuff, já\nque a criança tem ritmo sinusal em monitorização\ncardíaca."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-175115","number":"175115","sourceNumber":"175115","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Tabata, 8 anos, 25Kg, é trazida pelo resgate, intubada, após queda da montanha russa,\ncom perda de consciência, em parque da\ncidade. Ao entrar na sala de emergência você pede para\nequipe monitorá-la. Considerando que você confirmou PCR durante o exame físico e o monitor\ncardiorrespiratório apresenta traçado de fibrilação ventricular, a maneira adequada para tratar a\npaciente é:","options":{"A":"Desfibrilar com 50J, usando pá de adulto e gel, na sequência, iniciar RCP por 2 minutos com 120\nmassagens por minuto e 10 ventilações por\nminuto, sem sincronismo.","B":"Desfibrilar com 50J, usando pá infantil e gel, na sequência, iniciar RCP por 2 minutos com 15\nmassagens para 2 ventilações, com sincronismo","C":"Desfibrilar com 4J/Kg, usando pá de adulto e gel, na sequência, iniciar RCP por 2 minutos com\n120 massagens por minuto e 10 ventilações por\nminuto, sem sincronismo.","D":"Desfibrilar com 100J, usando pá de adulto e gel, realizar na sequência RCP por dois minutos\ncom massagens e ventilações com o sincronismo de 15:2."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-158040","number":"158040","sourceNumber":"158040","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança apresenta exantema maculopapular rosada claro, que apareceu após\npródromos de febre baixa e sintomas\nrespiratórios leves. Quanto ao diagnóstico mais provável\ndesse caso clínico, assinale a alternativa CORRETA.","options":{"A":"Rubéola.","B":"Sarampo.","C":"Varicela.","D":"Dengue.","E":"Exantema súbito."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-154507","number":"154507","sourceNumber":"154507","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A aferição correta da pressão arterial (PA) em lactentes e crianças, capaz de indicar o\ndiagnóstico de HAS deve ser realizada com técnica adequada. A alternativa que contempla a\ntécnica correta e a interpretação correta dos valores é:","options":{"A":"Idealmente a criança deverá estar sentada, com as costas bem apoiadas e com o braço direito\nao nível do coração. Valores de PA abaixo do\npercentil 90 para sexo, peso e altura são\nconsideradas normais.","B":"A relação largura/comprimento do manguito deverá ser maior ou igual a 1:2. Valores de PA entre\nos percentis 90 e 95 são considerados pré-\nhipertensão.","C":"A relação largura/comprimento do manguito deverá ser maior ou igual a 1:2. Valores de PA entre\nos percentis 95 e 99 são considerados\nhipertensão grau I.","D":"Idealmente a criança deverá estar sentada, com as costas bem apoiadas e com o braço direito\nao nível do coração. Nos adolescentes,\nvalores de PA iguais ou acima de 120x80mmHg, porém\nabaixo do percentil 90 , são considerados normais.","E":"A relação largura/comprimento do manguito deverá ser menor ou igual a 1:2. Valores de PA\nentre os percentis 90 e 95 são considerados hipertensão leve."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-129019","number":"129019","sourceNumber":"129019","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Acerca de crises de sibilância na infância, é correto afirmar que","options":{"A":"São raras até os três anos de idade, entretanto passam a ser muito frequentes após essa idade\ndevido ao maior contato com agentes patológicos.","B":"As crianças sibilantes com atopia são aquelas cuja patologia é mediata por IgE, sendo a maioria\ndos casos até os três anos de idade.","C":"As crianças com crises de sibilância de díficil controle e de início precoce devem ser\nconsideradas asmáticas.","D":"As causas de sibilância são de origem exclusivamente pulmonar.","E":"A maioria das crianças que apresentam sibilância nos primeiros anos de vida evolui para\nresolução completa dos sintomas no sexto ano de vida."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-133985","number":"133985","sourceNumber":"133985","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de 1 ano e 6 meses de idade, com quadro de diarreia e vômitos nas últimas 24\nhoras, é levada ao pronto atendimento. Ao ser avaliada, observou-se que ela está hipoativa,\nhipocorada, olhos muito encovados e lágrimas ausentes. Considerando o grau de desidratação da\ncriança nessa situação hipotética, a melhor opção de conduta para o caso, de acordo com a\nclassificação do Ministério da Saúde, é o plano","options":{"A":"C: fase de expansão com solução fisiológica a 0,9% 20 mL/Kg de peso endovenosa, podendo\nser repetida até que a criança esteja\nhidratada.","B":"C: fase de expansão com solução glicosada a 5%, 100 mL/kg em 2 horas, com repetição de 50\nmL/kg em 2 horas caso a criança não apresente melhora.","C":"B: administrar solução de reidratação oral em unidade de saúde, continuamente, até que\ndesapareceram os sinais de desidratação.","D":"B: gastróclise, 20-30 mL/kg/hora, até desaparecerem os sinais de desidratação, seguido de\ntentativa de uso oral de solução de reidratação oral.","E":"A: líquidos ou soro de reidratação oral, ofertando 50-100 mL após cada episódio de vômito ou\ndiarreia."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-129072","number":"129072","sourceNumber":"129072","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Apesar dos avanços em prevenção e controle de doenças infecciosas no mundo, as\ndoenças diarreicas agudas ainda são consideradas\ncomo um dos principais problemas de saúde\npública. Acerca das diarreias causadas pelo rotavírus, assinale a alternativa CORRETA:","options":{"A":"A diarreia é profusa, sanguinolenta e, na maioria das vezes, acompanhada de cólicas\nabdominais.","B":"Os vômitos são intensos, incoercíveis e precedem a diarreia de um a dois dias, podendo\nmanifestar-se isoladamente e com duração prolongada.","C":"A febre é discreta e somente surge quando se instala a diarreia.","D":"Além de não gerar imunidade, nova contaminação por rotavírus acarretará episódios diarreicos\ngeralmente mais graves.","E":"Por ser diferente dos quadros relacionados a outros agentes, como a Escherichia coli\nenterotoxigênica, não é necessária a investigação laboratorial específica."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-133998","number":"133998","sourceNumber":"133998","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de 4 meses é levada ao pronto-socorro com queixa de tosse produtiva há dois\ndias, associada a rinorreia, obstrução nasal, dispneia e febre de 38°C. Ao exame, observa-se que\nela apresenta taquidispneia, FR: 49 ipm, SatO2: 96% em ar ambiente e ausculta pulmonar com\npresença de creptos, sibilos e roncos de ransmissão difusos. Realizou-se radiografia de tórax que\nindicou presença de hiperinsuflação pulmonar, sem outros achados. Quanto a esse caso clínico\nhipotético, o diagnóstico mais provável é de","options":{"A":"Infecção de vias aéreas superiores, e o tratamento sugerido seria sintomático e orientação\nquanto aos sinais de alarme que indiquem\nnecessidade de retorno.","B":"Pneumonia, e o tratamento sugerido é de oxigenioterapia e antibioticoterapia.","C":"Bronquiolite, e o tratamento sugerido é de suporte com oxigenioterapia, hidratação e teste\nterapêutico com broncodilatadores.","D":"Laringotraqueobronquite, e o tratamento sugerido seria de oxigenioterapia e nebulização com\nadrenalina.","E":"Epiglotite, e o tratamento sugerido seria a manutenção da perviedade de vias aéreas e\nantibioticoterapia."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-129004","number":"129004","sourceNumber":"129004","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A tríade clássica da fibrose cística ou mucoviscidose é:","options":{"A":"Doença pulmonar crônica, diarreia esteatorreica crônica e dificuldade de ganho ponderal e\nestatural.","B":"Doença pulmonar crônica, diarreia sanguinolenta crônica e anemia crônica.","C":"Doença pulmonar crônica, diarreia esteatorreica crônica e infecção urinária de repetição.","D":"Doença pulmonar recidivante, diarreia aquosa crônica e dificuldade de ganho ponderal e\nestatural.","E":"Doença pulmonar crônica e recidivante, diarreia esteatorreica aguda e dificuldade de ganho\nponderal e estatural."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-133989","number":"133989","sourceNumber":"133989","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"As parasitoses intestinais representam um grave problema de saúde pública no Brasil,\nprincipalmente nos estados mais pobres e nas periferias dos grandes centros urbanos,\nparticularmente na população pediátrica. A respeito das parasitoses intestinais, assinale a\nalternativa CORRETA:","options":{"A":"A Necator americanus, o Strongyloides stercoralis e o Ascaris lumbricoides possuem ciclo\npulmonar.","B":"O prolapso retal é um achado típico da enterobíase.","C":"A infecção do homem na estrongiloidiase decorre da ingestão de alimentos contaminados com\novos dos estrongilóides e pode ser tratado\ncom tiabendazol por três dias.","D":"A giardíase pode apresentar-se como diarreia aguda autolimitada ou diarreia crônica com\npresença de esteatorreia. Uma forma de\nprevenir essa parasitose é estimular a higiene pessoal e a\ncloração da água.","E":"A amebíase pode-se apresentar de diversas formas, desde o espectro assintomático até a forma\nextraintestinal. Na forma extraintestinal, o achado de abscesso renal é muito comum."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-133994","number":"133994","sourceNumber":"133994","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A Fibrose Cística (FC) é uma doença genética, cuja prevalência na população chega a\n1/2.500 nascidos vivos na etnia branca. Nas últimas duas décadas, avanços no diagnóstico e na\nterapêutica dos pacientes com FC propiciaram aumento da sobrevida e da qualidade de vida.\n\nAcerca da fibrose cística, assinale a alternativa correta.","options":{"A":"A doença não pode ser considerada como diagnóstico diferencial das diarreias crônicas, já que\nnão cursa com manifestação gastrointestinal.","B":"O teste de suor possui elevada sensibilidade e especificidade para o diagnóstico, e é\nconsiderado positivo quando a concentração do cloreto no suor for maior que 45 mEq/L.","C":"É uma doença de herança autossômica recessiva, que leva a alteração de um canal condutor de\ncloreto de transmembrana presente em diversos epitélios do organismo que atinge, principalmente\nas glândulas exócrinas.","D":"O paciente portador de fibrose cística não pode fazer uso de qualquer tipo de vacina.","E":"Não existe diferença na expressão fenotípica da doença, sendo que os portadores sempre\napresentam a forma grave e completa da patologia."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-104775","number":"104775","sourceNumber":"104775","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação à conduta na diarreia aguda da criança, além do uso de soro de reidratação\noral, assinale a alternativa que apresenta a\nindicação correta.","options":{"A":"Usar antieméticos.","B":"Usar adstrigentes.","C":"Manter dieta habitual.","D":"Usar lactobacilos e similares.","E":"Usar antiespasmódicos."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-104760","number":"104760","sourceNumber":"104760","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de nove anos de idade apresentou quadro de diarreia com eliminação de\nfezes líquidas, explosivas, fétidas, com muco e sem sangue, às vezes com resíduos de alimentos,\nassociando-se à anorexia, náuseas, dor tipo cólica, distensão abdominal e à flatulência.\n\nConsiderando esse caso hipotético, assinale a alternativa que apresenta o diagnóstico mais\nprovável:","options":{"A":"Infecção por rotavírus.","B":"Giardíase.","C":"Estrongiloidíase.","D":"Escherichia coli.","E":"Amebíase."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-104740","number":"104740","sourceNumber":"104740","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A adição de micronutriente, na solução de reidratação oral, tem sido proposta como\ntratamento da diarreia aguda, pois atua como antioxidante, protegendo as membranas celulares.\nCom base nessa informação, assinale a alternativa que apresenta esse micronutriente.","options":{"A":"Cálcio.","B":"Magnésio.","C":"Zinco.","D":"Vitamina D.","E":"Ferro."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-111353","number":"111353","sourceNumber":"111353","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente com 3 meses de idade dá entrada no PS com T= 38,3?C, FC = 132 bpm, FR =\n\n48 MRPM, batimento de aletas nasais, tiragem intercostal e retração esternal. MV simétrico e\nsibilos difusos. Início há 5 dias com coriza e febre, nega episódios anteriores. O diagnóstico e\netiologia mais provável são:","options":{"A":"Pneumonia por Clamídia.","B":"Asma por hipersensibilidade.","C":"Pneumonia por Streptoccocus pneumoniae.","D":"Bronquiolite viral aguda por vírus sincicial\nrespiratório.","E":"Pneumonia por Micoplasma."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-111267","number":"111267","sourceNumber":"111267","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O pediatra é chamado para atender um recém-nascido com 27 dias com queixas de\nvômitos, não biliosos, desde os 17 dias de vida. Evacuação 1 vez ao dia. Nasceu com 38 semanas,\npeso de 3 300 g. Aleitamento materno exclusivo. Peso atual 3 500 g. Ao exame físico, observa-se\ndistensão epigástrica, com ondas peristálticas visíveis e palpa-se tumoração cilíndrica, 3 x 2 cm,\nduro, elástica, no hipocôndrio direito, junto à borda do músculo reto abdominal. Qual é a doença\ncompatível com essa descrição e em qual sexo ela é mais prevalente?","options":{"A":"Atresia duodenal, masculino.","B":"Atresia duodenal, feminino.","C":"Estenose hipertrófica de piloro, masculino.","D":"Estenose hipertrófica de piloro, feminino.","E":"Hematoma duodenal, sem prevalência de sexo."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-111274","number":"111274","sourceNumber":"111274","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente com 3 meses de idade é levado ao Posto de Saúde com queixa de tosse\npersistente há 3 semanas, gemente e\ninapetente há 2 dias. Nega febre durante toda a doença.\nNascido de parto normal, a termo, peso adequado para idade gestacional, Apgar 9, 10. Consultas\nanteriores: aos 7 dias de vida, icterícia fisiológica e aos 30 dias de vida, conjuntivite. Leite\nmaterno\nexclusivo. Ao exame físico: Peso 5 100 g, comprimento 60 cm. BEG, FR 58 irpm, FC 120 bpm,\ntemperatura axilar 36,5 ° C. Ausculta pulmonar com MV presente e estertores subcrepitantes\ndisseminados. Restante do exame sem anormalidades. Radiografia de tórax mostra opacidade\nheterogênea no lobo superior direito. Hemograma: 10 g Hb, Leucócitos13 000 (bastonetes 1%,\nsegmentados 34%, eosinófilos 9%, basófilos 1%, linfócitos 40%, monócitos 5%). Qual o mais\nprovável diagnóstico para esse caso?","options":{"A":"Pneumonia por Chlamydia trachomatis.","B":"Pneumonia viral.","C":"Pneumonia por Streptococcus pneumoniae.","D":"Pneumonia por Mycoplasma pneumoniae.","E":"Pneumonia por aspiração, Refluxo Gástrico\nEsofágico."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-111282","number":"111282","sourceNumber":"111282","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em lactentes, o quadro clínico clássico da Doença Diarreica Aguda (DDA) causada pelo\nrotavírus é:","options":{"A":"Febre, vômitos e diarreia aquosa.","B":"Diarreia aquosa sem vômitos ou febre.","C":"Vômitos e diarreia aquosa.","D":"Febre e diarreia aquosa.","E":"Febre, vômitos e diarreia sanguinolenta."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-111312","number":"111312","sourceNumber":"111312","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação à reidratação da criança desidratada, assinale a alternativa CORRETA:","options":{"A":"A terapia de reidratação oral deve ser utilizada em todas as crianças desidratadas.","B":"A reidratação oral não deve ser utilizada em crianças que apresentam vômitos.","C":"A correção com soro fisiológico 0,9%, por via endovenosa, é sempre a maneira mais eficaz para\nqualquer grau de desidratação.","D":"As crianças com graus leves e moderados de desidratação, quando reidratadas por via\nendovenosa, têm o curso de sua doença abreviado.","E":"As crianças com graus leves e moderados de desidratação podem e devem ser reidratadas\ncom terapia de reidratação oral, sempre que\npossível."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-111265","number":"111265","sourceNumber":"111265","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Para diagnosticar definitivamente a doença celíaca (intolerância permanente às\nproteínas do glúten) em crianças menores de\ndois anos, além da história clínica, epidemiológica, do\nexame físico e dos testes sorológicos direcionados contra estas frações proteicas ou seus\nhomólogos, necessita-se de:","options":{"A":"Análise histopatológica da biópsia da mucosa\nintestinal.","B":"Dosagem de gordura fecal.","C":"Teste de absorção intestinal de D?xilose.","D":"Dosagem de alfa-1-antitripsina fecal.","E":"Teste de Lundh."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-354101","number":"354101","sourceNumber":"354101","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente do sexo masculino, 5 anos de idade, apresenta histórico de febre há 4 dias e\niniciou, hoje, lesão de pele. Ao exame apresenta bom estado geral, afebril e com eritema reticular\nem face (bochechas) e em membros superiores. O exame não revela outras alterações. O pediatra\nexplicou aos pais que, provavelmente, esse quadro seja devido a um agente viral específico.\n\nConsiderando a principal hipótese diagnóstica e o agente responsável por esse quadro, avalie as\nafirmações abaixo. I. Acometimento neonatal grave por esse tipo de vírus caracteriza-se por\ninfecção de múltiplos órgãos, principalmente coração, pulmões e cérebro. II. O vírus responsável\npelo quadro descrito pode acometer também a faringe posterior (com presença de vesículas e\núlceras) e causar herpangina. III. Infecções clinicamente aparentes como o caso descrito e a crise\naplástica transitória são quadros prevalentes em criança na idade escolar com esse tipo de doença.\n\nIV. Geralmente, esse quadro é benigno e autolimitado e raramente pode causar púrpura\ntrombocitopênica. V. Se a presença de artrite\nfor associada ao quadro descrito, deve-se fazer\ndiagnóstico diferencial com artrite reumatoide juvenil e lúpus. É correto apenas o que se afirma\nem:","options":{"A":"I, IV e V.","B":"II, III e IV.","C":"I e II.","D":"I, II, III e V.","E":"III, IV e V."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-359195","number":"359195","sourceNumber":"359195","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Correlacione a COLUNA II de acordo com a COLUNA I. COLUNA I; 1- Varicela. 2-\nImpetigo. 3- Rubéola. 4- Sarampo. 5- Exantema súbito. COLUNA II; ( ) Exantema máculopapular\nrósco atingindo face, tronco e membros em 24 a 48 horas. ( ) Exantema papulovesicular com\npolimorfismo regional. ( ) Febre alta de 3 a 5 dias e aparecimento do exantema após o declínio da\nfebre. ( ) GNDA é a complicação mais temida. ( ) A persistência da febre após o 4º dia sugere\ncomplicações bacterianas. Assinale a alternativa que apresenta a sequência CORRETA.","options":{"A":"3, 1, 5, 2, 4.","B":"1, 3, 4, 2, 5.","C":"5, 3, 2, 4, 1.","D":"2, 1, 3, 4, 5."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-351585","number":"351585","sourceNumber":"351585","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Ao se deparar com possível situação de maus-tratos a criança ou adolescente, é\nCORRETO afirmar que o médico deve:","options":{"A":"Conduzir minucioso processo de investigação antes de oferecer denúncia, uma vez que pode\nser legalmente penalizado por denunciação\ncaluniosa.","B":"Emitir ficha de notificação individual, garantir a continuidade do tratamento médico e acionar\nimediatamente conselho tutelar em casos em que haja risco emergencial à segurança do paciente.","C":"Registrar o caso detalhadamente em prontuário, emitindo ficha de notificação, apenas se há\nconfirmação da violência, solicitando também a confecção de boletim de ocorrência.","D":"Acionar imediatamente serviço policial independente do caso, ocupando-se somente da\navaliação clínica e garantia de continuidade do tratamento ambulatorial."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-368167","number":"368167","sourceNumber":"368167","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Um pediatra atende há dois anos uma paciente feminina de 12 anos de idade com\nestatura no percentil 50, e ela tem excesso\nde peso (IMC: percentil 90). A aferição da PA nas\núltimas três ocasiões mostrou os seguintes valores: 1) 126x84 mmHg; 2) 130x84 mmHg; 3) 128x80\nmmHg. Ela é assintomática e tem antecedentes familiares de hipertensão arterial (pai e avós\nmaternos). Sabe-se que os valores normais da tabela de PA são: P50: 108x62 mmHg, P90: 121x75\nmmHg, P95: 125x78 mmHg e P99: 137x90 mmHg. Nesse contexto, é correto afirmar:","options":{"A":"Essa paciente não precisa ser acompanhada quanto à sua pressão arterial porque não será\nnecessário o uso de medicamentos.","B":"Deve-se pesquisar a etiologia da hipertensão arterial com dosagens de renina sérica e ultrassom\nde artérias renais com Doppler.","C":"A adolescente tem diagnóstico de pré-hipertensão arterial, e o tratamento medicamentoso deve\nser instituído o mais breve possível.","D":"A adolescente deve ser investigada com relação a possível acometimento de órgãos-alvo\n(exame de fundo de olho, ecocardiograma,\nalbuminúria)."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-368169","number":"368169","sourceNumber":"368169","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Quanto às doenças exantemáticas, é correto afirmar:","options":{"A":"A escarlatina inicia-se abruptamente com febre alta, dor de garganta, anorexia, vômitos, cefaleia\ne, às vezes, dor abdominal. Após 12 a 48\nhoras, surge o exantema, que é típico: eritematoso,\nmicropapular e áspero como uma lixa.","B":"Na escarlatina, o exantema, que se inicia no tronco e evolui para pescoço e ombros, ocorre\nprincipalmente nas palmas das mãos e planta dos pés.","C":"No eritema infeccioso, as bochechas são avermelhadas, e a região perioral se apresenta pálida,\no que é conhecido como sinal de Filatov. O\nexantema é mais acentuado nas dobras cutâneas, e\nsurgem áreas de hiperpigmentação, com a formação de linhas transversais nas dobras de flexão,\ndenominado sinal de Pastia.","D":"A doença de Kawasaki é caracterizada por uma vasculite sistêmica que afeta artérias de\ngrandes calibres, como a aorta. A ruptura de\naneurisma da aorta é a complicação mais temida."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-345711","number":"345711","sourceNumber":"345711","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Assinale a alternativa correta sobre o tratamento do choque séptico em pediatria.","options":{"A":"O uso de protocolos no tratamento do choque séptico é capaz de melhorar o desfecho e pode\nsubstituir a avaliação clínica do médico.","B":"Uma importante ferramenta no tratamento do choque séptico pediátrico são os bundles, que\nconsistem em um conjunto de intervenções que podem gerar melhores desfechos.","C":"A dosagem de lactato sanguíneo é útil para avaliar casos de sepse com gravidade potencial ou\nque podem apresentar maior taxa de\nmortalidade, e os seus valores de corte são consenso na\nliteratura.","D":"O esforço individual se sobressai ao esforço coletivo no tratamento do choque séptico pediátrico,\npois a variedade de opiniões e interferências\ntem sido associada a desfechos negativos."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-320434","number":"320434","sourceNumber":"320434","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente, 1 ano e 5 meses, apresenta, desde os 7 meses de vida, otites de repetição (5\nepisódios, sendo três episódios com supuração). Seu crescimento pôndero-estatural é normal, mas\no pediatra encaminha para o imunologista por suspeita de imunodeficiência primária do tipo celular.\nEsse encaminhamento se justifica?","options":{"A":"Sim, mas a suspeita é de imunodeficiência primária do sistema complemento.","B":"Sim, mas a suspeita é de imunodeficiência primária humoral.","C":"Não, já que a hipogamaglobulinemia fisiológica é comum até? dois anos.","D":"Não, pois não veremos imunodeficiência primaria após os seis meses de vida.","E":"Não, pois é comum a criança nos dois primeiros anos de vida apresentar 10 ou mais infecções\nbacterianas"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-321172","number":"321172","sourceNumber":"321172","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Viroses exantemáticas são moléstias infecciosas nas quais a erupção cutânea é a\ncaracterística dominante. A análise do tipo da lesão, dos sinais e dos sintomas concomitantes e a\nepidemiologia são fundamentais para um diagnóstico preciso. Sobre as doenças exantemáticas, é\nCORRETO afirmar que:","options":{"A":"O sarampo pode ser diferenciado das demais doenças exantemáticas pela evolução\ncaracterística do exantema que se inicia na\nface, espalhando-se rapidamente para o pescoço e o\ntronco, e atingindo os membros já em 24 horas.","B":"Na rubéola, observa-se exantema maculopapular morbiliforme não confluente que se inicia na\nface e evolui para o tronco, além da acentuação dos sintomas catarrais e da temperatura\ncoincidindo com o início do exantema.","C":"No eritema infeccioso, dois sinais e sintomas clássicos associados são a fotossensibilidade e a\npiora no exantema com o uso de amoxicilina.","D":"Na roséola, observa-se exantema maculopapular cujo início coincide com queda da febre."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-345715","number":"345715","sourceNumber":"345715","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Com relação à medida da pressão arterial (PA), assinale a alternativa correta.","options":{"A":"A medida da PA por dispositivo oscilométrico é padrão ouro.","B":"A medida da PA por dispositivo oscilométrico deve ser preferencialmente realizada em membros\ninferiores.","C":"O valor da razão da largura do manguito pela circunferência do braço deve ser próximo de 0,5.","D":"A medida da PA por meio de cateter intra-arterial é uma técnica simples, sem complicações."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-321173","number":"321173","sourceNumber":"321173","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre os suportes básicos e avançados de vida em pediatria, é CORRETO afirmar que:","options":{"A":"Durante uma parada cardiorrespiratória independentemente do número de socorristas, deve-se\nrealizar 30 compressões seguidas de 2 ventilações.","B":"Para crianças de até 1 ano o pulso deve ser checado pela artéria braquial, enquanto para\nmaiores de 1 ano pela artéria carótida ou femoral.","C":"Em ritmos de fibrilação ventricular e taquicardia ventricular sem pulso é necessário\nadministração imediata de epinefrina.","D":"Para casos de assistolia, o primeiro choque deve ser de 2J/Kg."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-346857","number":"346857","sourceNumber":"346857","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de 1 ano e 6 meses, sexo masculino, previamente hígida, é levada a uma\nconsulta com pediatra por apresentar há 3 dias lesões pruriginosas, disseminadas pelo corpo,\nassociado a febre de 38°C. Exame físico realizado mostrou bom estado geral, mas com lesões\ndifusas pelo corpo, inclusive em mucosas, oral e genital, pruriginosas, em vários estágios, ora\nmáculas, pápulas, vesículas e algumas com crostas. De acordo com o caso apresentado, a\nMELHOR conduta para essa criança é:","options":{"A":"Administrar antitérmicos (paracetamol ou dipirona) + cuidados com limpeza das lesões e orientar\nem caso de sinais de complicações das\nlesões.","B":"Iniciar prednisolona por 5 dias.","C":"Iniciar cefalexina por 10 dias.","D":"Iniciar imunoglobulina venosa + Ácido Acetil Salicílico (AAS)."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-321176","number":"321176","sourceNumber":"321176","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O maior número de eventos traumáticos com crianças pequenas, até o fim da idade\nescolar, acontece no seu próprio domicílio. A\nprevenção de lesões que ocorrem no lar, segundo os\nespecialistas, apoia-se na orientação e na conscientização dos pais para que promovam mudanças\nno seu comportamento, no sentido de uma supervisão mais efetiva e da eliminação dos riscos\ndentro de casa. Nesse sentido, é CORRETO afirmar que:","options":{"A":"Manter os produtos em sua embalagem original e nunca reutilizar frascos são formas de prevenir\nintoxicações.","B":"Ligar mais de um aparelho em uma mesma tomada, evitando assim que estes fiquem\nespalhados pela casa, é uma forma de prevenir choques elétricos.","C":"Se o bebê tem um cercado, é necessário que a malha seja bem apertada, com buracos maiores\nque 2cm e menores que 5cm.","D":"Uso de andadores é uma forma de prevenir quedas."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-321177","number":"321177","sourceNumber":"321177","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"H.M.C. 14 anos, sexo masculino, comparece ao pediatra com queixa de disúria e febre.\nAo exame físico, encontrado sinal de Giordano\npositivo. Sobre esse paciente, é CORRETO afirmar\nque:","options":{"A":"O diagnóstico de infecção do trato urinário é confirmado pela bacteriúria significativa, que é a\npresença na urina de um número igual ou superior a 10.000 unidades formadoras de colônias de\numa única bactéria.","B":"A antibioticoterapia ideal para o caso seria com cefalosporinas de 3a geração (ceftriaxona ou\nceftazidima), via parenteral, na dosagem de 50 a 100mg/kg/dia, 1 ou 2 vezes ao dia.","C":"Deve-se investigar o histórico de infecções do trato urinário nesse paciente, uma vez que a\ninvestigação por imagens do trato urinário está indicada após o 2o episódio bem documentado de\ninfecção urinária, em qualquer idade e para ambos os sexos, sendo feita por ultrassonografia.","D":"A antibioticoterapia deve ser iniciada imediatamente após a coleta da urina, pois a demora para\ncomeçar o tratamento é fator de risco para o aparecimento de lesão renal."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-336278","number":"336278","sourceNumber":"336278","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 6 meses de idade, chega à sala de Emergência com relato materno de palidez,\ncansaço e sudorese fria iniciados há 3 dias. Buscou atendimento médico por dificuldade nas\nmamadas com piora do cansaço durante a sucção, o que vem comprometendo a ingesta alimentar\ndo menor. Informa que recentemente se recuperou de uma diarréia viral aguda tratada em\ndomicílio. Ao exame: acordado, irritado, mucosas hipohidratadas, pálido (3+/4+), TAX: 36,6°C,\nsudorese fria. Vias aéreas pérvias, Sat O2 de 88% em ar ambiente, FR: 80 irpm, tiragens\nintercostais e subcostais com batimento de aletas nasais, ausculta pulmonar com estertores\ncrepitantes. RCR 3T, bulhas hiperfonéticas, sopro sistólico, FC: 192 bpm, tempo de enchimento\ncapilar = 4 seg, PA: 88 x 52 mmHg. Abdome globoso, peristalse presente, fígado a 5cm do RCD.\nQual o diagnóstico sindrômico?","options":{"A":"Choque cardiogênico compensado","B":"Choque cardiogênico descompensado","C":"Choque séptico descompensado","D":"Choque séptico compensado"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-321179","number":"321179","sourceNumber":"321179","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre o suporte às vítimas de violência doméstica na pediatria, é CORRETO afirmar\nque:","options":{"A":"A síndrome de Munchausen por procuração é uma doença de difícil controle, definida como\nforma de violência na qual a criança ou o\nadolescente são levados para cuidados médicos de forma\ninsistente e em frequência acima do esperado.","B":"A notificação do diagnóstico ou suspeita de violência não é compulsória, e deve ser feita ou não\nsegundo decisão da vítima juntamente ao médico\nresponsável.","C":"Os pais e a família sempre são os melhores a cuidar de sua prole e, na consulta pediátrica, eles\nsempre falam a verdade e procurando o melhor para seus filhos.","D":"Todo ato sexual com adolescente ou criança menor de 16 anos é considerado crime de estupro\npelo Código Penal Brasileiro."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-337640","number":"337640","sourceNumber":"337640","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Exantemas de causa viral são extremamente frequentes na infância. Embora a maioria\nseja originária de doenças autolimitadas e benignas, alguns podem ser expressões de moléstias\nmais graves. Sobre as doenças exantemáticas, assinale a alternativa CORRETA:","options":{"A":"Em casos de sarampo, deve-se aplicar a vacina até 72 horas após o contágio, e após esse\nperíodo, até 6 dias, aplicar a imunoglobulina\nhumana normal na dose de 0,25mL/kg em crianças\nimunossuprimidas.","B":"A adenomegalia é um achado marcante da roséola infantil, ou exantema súbito que pode\nanteceder em até 7 dias o exantema.","C":"A mononucleose infecciosa é considerada uma síndrome. O vírus Epstein-Barr é o responsável\npor cerca de 80% dos casos, sendo a erupção\ncutânea o sintoma mais frequente associado.","D":"A varicela quando acomete uma gestante, faz com que o feto possa sofrer as consequências,\ndas quais as mais frequentes são focomelia,\ncoriorretinite, meningoencefalite, lesões cicatriciais na\npele, além de morte fetal e aborto."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-336281","number":"336281","sourceNumber":"336281","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente, 7 meses com quadro de diarréia grave e desidratação é admitido na\nemergência arresponsivo e sem pulso. Iniciada\nreanimação cardiopulmonar e o monitor cardíaco\nmostra o ritmo do ECG em anexo. O lactente é intubado, ventilado com O2 a 100%. Realizado\nacesso intraósseo. Qual terapêutica é a mais adequada para ser realizada a seguir:","options":{"A":"Amiodarona 5 mg/kg","B":"Solução fisiológica 20 ml/kg","C":"Desfibrilação com 2J/kg","D":"Adrenalina 0,1 mg/kg"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":["question_bank/media/medcurso/medcurso-pediatria-ped-5/336281.png"],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-337642","number":"337642","sourceNumber":"337642","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A Ressuscitação Cardiopulmonar (RCP) envolve um conjunto de medidas que visam a\nevitar ou reverter uma Parada Cardiorrespiratória (PCR) por meio do suporte ventilatório e\ncirculatório. As manobras de RCP estão indicadas na PCR e na bradicardia com sinais de\nhipoperfusão. Em casos de PCR na pediatria, é CORRETO afirmar que:","options":{"A":"Deve-se suspeitar de obstrução de vias aéreas por corpo estranho quando houver aparecimento\nabrupto de estridor, tosse, cansaço e\nbroncoespasmo na ausência de febre ou sintomas\nprodrômicos.","B":"A profundidade das compressões deve ser de 1/3 do diâmetro anteroposterior com profundidade\nde cerca de 10cm em crianças ou lactentes.","C":"A epinefrina pode ser usada na dose 0,01mg/kg (0,1mL/kg da solução 1:10.000) na criança com\nbradicardia sintomática que não responde com ventilação efetiva e suplementação de oxigênio,\npreferivelmente em via traqueal.","D":"Deve-se realizar as compressões abdominais (manobra de Heimlich) em pacientes de qualquer\nidade conscientes com obstrução das vias aéreas superiores, na região entre a cicatriz umbilical e\napêndice xifoide."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-336283","number":"336283","sourceNumber":"336283","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 2 anos, portador de Tetralogia de Fallot, chega a emergencia com relato de\ncianose generalizada persistente após crise de choro intensa iniciados há 20 minutos. TAX: 36,3°C;\nFC: 150 bpm , PA: 87x50 mmHg; SatO2 65%; FR 35 irpm. Qual medida farmacológica deve ser\nadotada na admissão deste paciente?","options":{"A":"Morfina","B":"Prostaglandina","C":"Dobutamina","D":"Milrinona"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-335106","number":"335106","sourceNumber":"335106","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente de um ano e 10 meses, sexo feminino, é levada pela mãe ao pediatra da\nUnidade Básica de Saúde, e relata febre,\npolaciúria, irritabilidade e vômitos muito frequentes.\nDesde o início do quadro, há 48 horas, não consegue comer quase nada, apresenta vômitos e está\nmais prostrada. Ao exame físico, apresenta-se desidratada, taquicárdica e com perfusão capilar =\n5?. Em relação a esse caso, assinale a alternativa que indica a conduta correta para a criança.","options":{"A":"Solicitar urina rotina, Gram e urocultura e aguardar o resultado de exames para definir o\ntratamento antimicrobiano de acordo com a sensibilidade do micro-organismo isolado.","B":"Encaminhar a criança para Unidade de Pronto Atendimento, pois encontra-se indicado o início\nimediato de tratamento com antimicrobiano venoso após coleta de urina para exames.","C":"Prescrever quimioprofilaxia por um período mínimo de um ano após tratamento para erradicar a\nbactéria, independentemente da investigação morfofuncional de vias urinárias.","D":"Realizar imediatamente o ultrassom de vias urinárias e a uretrocistografia miccional após o\ndiagnóstico de infecção do trato urinário ser confirmado pela urocultura."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-335107","number":"335107","sourceNumber":"335107","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Aaferição da pressão arterial na criança e no adolescente ainda não é um hábito na\nconsulta pediátrica e, portanto, muitos desses\npacientes hipertensos ficam por longo tempo sem\ndiagnóstico. Ademais, alguns pediatras desconhecem os métodos dessa aferição e / ou não\npossuem o instrumental adequado. Acerca da hipertensão arterial na infância, assinale a alternativa\ncorreta.","options":{"A":"A principal causa de hipertensão arterial em crianças pré-escolares e escolares é a hipertensão\nessencial.","B":"A definição de emergência hipertensiva contempla uma elevação da pressão arterial sistólica e\ndiastólica sem lesão de órgãos-alvo.","C":"A obesidade na criança e no adolescente só é considerada fator de risco para hipertensão\narterial se o paciente for obeso desde o\nnascimento.","D":"A hipertensão arterial em recém-nascidos e lactentes habitualmente está relacionada à doença\nrenal ou vascular."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-334758","number":"334758","sourceNumber":"334758","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O acometimento de crianças por doença exantemática é um dos quadros mais comuns\nda prática médica, impondo dificuldade\ndiagnóstica frequentemente. Nas doenças exantemáticas é\nCORRETO afirmar:","options":{"A":"Na rubéola ocorre prostração intensa, febre elevada (auge no aparecimento do exantema), tosse\nseca e intensa, coriza abundante e olhos\nhiperemiados, com lacrimejamento e fotofobia. O\nexantema é maculopapular morbiliforme confluente e pode apresentar manchas de Koplik.","B":"Na roséola infantil ou exantema súbito, o exantema inicia na face como maculopápulas que\nconfluem, tornando-se uma placa vermelho-rubra, concentrada, principalmente, na região das\nbochechas. Poupa a região perioral, a testa e o nariz.","C":"No eritema infeccioso, o exantema pode persistir por um período longo, até mais de 10 dias, e\nexacerbar-se ou reaparecer quando a criança é exposta ao sol, faz exercício ou quando há\nalterações de temperatura.","D":"No sarampo ocorre mal-estar, febre baixa e exantema maculopapular e morbiliforme não\nconfluente que inicia na face e evolui para o tronco. Apresenta adenopatia (retroauricular e\noccipital) e artralgia."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-335112","number":"335112","sourceNumber":"335112","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"As doenças exantemáticas são um grupo de doenças infecciosas na pediatria cuja\nprincipal característica é a erupção cutânea.\nEmbora a maioria sejam doenças autolimitadas e\nbenignas, algumas podem serexpressões de enfermidades mais graves. Nesse contexto, numere a\nCOLUNA II de acordo com a COLUNA I. COLUNA I 1. Varicela 2. Impetigo 3. Rubéola 4. Sarampo\n\n5. Exantema súbito COLUNA II ( ) Exantema maculopapular róseo atingindo face, tronco e\nmembros em 24 a 48 horas. ( ) Exantema\npapulovesicular com polimorfismo regional. ( ) Febre alta\nde três a cinco dias e aparecimento do exantema após o declínio da febre. ( ) GNDA é a\ncomplicação mais temida. ( ) A persistência da febre após o quarto dia sugere complicações\nbacterianas. Assinale a sequência correta.","options":{"A":"3 1 5 2 4","B":"1 3 4 2 5","C":"5 3 2 4 1","D":"2 1 3 4 5"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-291934","number":"291934","sourceNumber":"291934","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente sexo masculino de 2 meses e 4 dias, é admitido pela pediatria em um hospital\ndo Espírito Santo. Mãe se queixa que lactente\nestá muito magro, não consegue amamentá-lo\ncorretamente pois, segundo ela ?parece que ele não aguenta sugar por muito tempo, demora\ndemais a mamar?, além disso, ainda relata presença de gotas de suor no rosto do filho durante a\namamentação. Levando em consideração a insuficiência cardíaca congestiva na criança, é\nCORRETO afirmar que:","options":{"A":"A insuficiência cardíaca na criança, de um modo geral, pode estar relacionada à complicação\ndecorrente de glomerulonefrite difusa aguda pós-estreptocócica.","B":"A principal cardiopatia congênita relacionada à insuficiência cardíaca é a origem anômala de\ncoronária esquerda.","C":"No período neonatal até o primeiro ano de vida, as cardiopatias adquiridas estão mais\nrelacionadas ao desenvolvimento da insuficiência cardíaca do que as cardiopatias congênitas.","D":"O uso de diuréticos de alça está contraindicado, mesmo para aqueles pacientes com sinais de\ncongestão."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-306715","number":"306715","sourceNumber":"306715","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O uso apropriado de Prostaglandina venosa (PGE1), além de ser imprescindível para\nmanter a vida do recém-nascido em algumas cardiopatias congênitas, permite sua melhor\nestabilização clínica até a instituição de tratamento cirúrgico. Em que cardiopatia congênita\ndiagnosticada intra-útero, o uso de PGE1 está indicado?","options":{"A":"Transposição das grandes artérias.","B":"Comunicação interventricular","C":"Tronco arterial comum","D":"Defeito total do septo AV"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-291935","number":"291935","sourceNumber":"291935","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre a reanimação cardiopulmonar em pediatria, é CORRETO afirmar que:","options":{"A":"O socorrista deve deixar a criança e chamar pelo serviço médico de emergência no suporte\nbásico de vida pré-hospitalar com apenas um socorrista, caso a parada cardiorrespiratória não\ntenha sido presenciada.","B":"O uso de succinilcolina para intubação de crianças com doenças neuromusculares pode estar\nrelacionada à hipertermia maligna e hipercalemia.","C":"A bradipneia ou frequência respiratória irregular não podem ser considerados como sinais de\nparada cardiorrespiratória iminente na criança.","D":"As manobras vagais são proscritas para terapêutica de taquicardia supraventricular."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-291942","number":"291942","sourceNumber":"291942","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Exantemas de causa viral são muito frequentes na infância. Embora a maioria seja\noriginária de doenças autolimitadas e\nbenignas, algumas podem ser expressões de moléstias mais\ngraves. Sobre as doenças exantemáticas, é CORRETO afirmar que:","options":{"A":"No sarampo, o exantema se inicia atrás do pavilhão auricular, disseminando-se rapidamente\npara o pescoço, a face e o tronco e atinge a\nextremidade dos membros por volta do terceiro dia.\nComo regra, ele é maculopapular eritematoso e morbiliforme.","B":"Na rubéola, pode-se notar exantema maculopapular morbiliforme confluente que se inicia no\ntronco e evolui para a face.","C":"Na mononucleose, na maioria dos casos, não há alteração do exantema maculopapular após o\nuso de amoxicilina.","D":"Na varicela as manchas de Koplik são comumente encontradas em distribuição difusa pelo\ncorpo da criança."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-304872","number":"304872","sourceNumber":"304872","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sabemos que a orientação dos pais e dos pacientes sobre o tema segurança deve ser\nenfatizada na consulta pediátrica. Diante do exposto, avalie as alternativas abaixo e marque a\nincorreta.","options":{"A":"As crianças devem viajar no banco de trás do automóvel até a idade de 10 anos. A partir daí\npodemos viajar no banco da frente, com utilização correta do cinto de segurança independente da\nsua altura.","B":"Metade das mortes acidentais ocorridas em menores de 15 anos acontecem em casa, e os\nlocais de maior risco são escadas, banheiro e cozinha.","C":"Asfixia, afogamento e queda são as maiores causas externas de morbiletalidade em ambiente\ndoméstico em crianças até a idade escolar.","D":"O pediatra tem que conscientizar bem todo adolescente, assim como seus pais, acerca do fato\nalarmante de que 2/3 das mortes nessa idade se devem às violências e ao trânsito, com grande\nparticipação do álcool."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-306729","number":"306729","sourceNumber":"306729","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menina de 3 anos apresenta quadro de febre baixa, urgência miccional e disúria há dois\ndias. Exame físico: corada, hidratada, cooperativa ao exame, sem sinais meníngeos, ausculta\ncardiopulmonar sem alterações, dor discreta à palpação da região suprapúbica. Exame de urina:\npiócitos incontáveis, 12 hemácias por campo, flora bacteriana aumentada, nitrito negativo, corpos\ncetônicos ausentes, proteína ausente, glicemia ausente. A conduta indicada nesse momento\nconsiste em:","options":{"A":"Internar, colher urocultura, realizar ultrassonografia e iniciar tratamento com ceftriaxona.","B":"Colher urocultura e reavaliar em 72h, iniciando antimicrobiano de acordo com resultado.","C":"Colher urocultura e iniciar tratamento ambulatorial de imediato com cefalexina.","D":"Iniciar tratamento ambulatorial com amoxicilina sem necessidade de exame complementar."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-305026","number":"305026","sourceNumber":"305026","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere que duas crianças são trazidas ao hospital por suas mães com queixa de\nfebre e exantema com descamação, ao exame de oroscopia, são encontradas as seguintes\nalterações: São prováveis hipóteses diagnósticas das crianças A e B, respectivamente,","options":{"A":"escarlatina e sarampo.","B":"sarampo e rubéola.","C":"rubéola e exantema súbito.","D":"exantema súbito e escarlatina."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-305033","number":"305033","sourceNumber":"305033","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere que uma paciente de um ano e 10 meses de idade, sexo feminino, é levada\npela mãe ao pediatra da Unidade Básica de\nSaúde com relato de febre, polaciúria, irritabilidade e\nvômitos frequentes. Desde o início do quadro, há 48 horas, não consegue comer quase nada,\napresenta vômitos e está mais prostrada. Ao exame físico, apresenta-se desidratada, taquicárdica e\ncom perfusão capilar = 5?. Nesse caso, qual é a conduta correta a ser adotada?","options":{"A":"Solicitar exames: urina rotina, Gram e urocultura e aguardar o resultado para definir o\ntratamento\nantimicrobiano de acordo com a sensibilidade do micro-organismo isolado.","B":"Encaminhar a criança à Unidade de Pronto Atendimento, pois encontra-se indicado o início\nimediato de tratamento com antimicrobiano venoso após coleta de urina para exames.","C":"Prescrever quimioprofilaxia por um período mínimo de um ano após tratamento para erradicar a\nbactéria, independentemente da investigação morfofuncional de vias urinárias.","D":"Realizar imediatamente o ultrassom de vias urinárias e a uretrocistografia miccional após o\ndiagnóstico de infecção do trato urinário ser confirmado pela urocultura."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-305037","number":"305037","sourceNumber":"305037","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre as doenças exantemáticas, relacione a COLUNA I com a COLUNA II, associando\nas doenças às suas respectivas descrições.\nCOLUNA I; 1. Varicela; 2. Impetigo; 3. Rubéola; 4.\n\nSarampo; 5. Exantema súbito; COLUNA II; ( ) Exantema maculopapular róseo atingindo face,\ntronco e membros em 24 a 48 horas. ( )\nExantema papulovesicular com polimorfismo regional. ( )\nFebre alta de três a cinco dias e aparecimento do exantema após o declínio da febre. ( ) GNDA é a\ncomplicação mais temida. ( ) A persistência da febre após o quarto dia sugere complicações\nbacterianas. Assinale a sequência correta.","options":{"A":"3 1 5 2 4","B":"1 3 4 2 5","C":"5 3 2 4 1","D":"2 1 3 4 5"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-306743","number":"306743","sourceNumber":"306743","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 1ano e 6meses de idade portador de anisocoria em investigação é levado\nao oftalmologista após descartar alterações\nneurológicas. No exame oftalmoscópico é notado\nmúltiplas massas tumorais rosadas, vascularizadas, parcialmente calcificadas, preenchendo a\ncavidade vítrea. O provável diagnóstico da criança é:","options":{"A":"Tracoma","B":"Retinoblastoma","C":"Doença de Coats","D":"Toxoplasmose ocular"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-305040","number":"305040","sourceNumber":"305040","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Considere um paciente, sexo masculino, 13 anos de idade, estatura no percentil 50 e\npeso em excesso (IMC percentil 90)\nacompanhado há dois anos.Aaferição da PA, nas últimas três\nocasiões, mostrou os valores a seguir. 1. 126 x 84 mmHg; 2. 130 x 84 mmHg; 3. 128 x 80 mmHg. O\nadolescente é assintomático e tem antecedentes familiares de hipertensão arterial (pai e avós\npaternos). Sabe-se que os valores normais da tabela de PA são: P50 = 108 x 62 mmHg; P90 = 121\nx 75 mmHg; P95 = 125 x 78 mmHg. Nesse contexto, é correto afirmar:","options":{"A":"O adolescente tem diagnóstico de pré-hipertensão arterial e o tratamento medicamentoso deve\nser instituído o mais breve possível.","B":"O adolescente deve ser investigado com relação a possível acometimento de órgãos-alvo\n(exame de fundo de olho, ecocardiograma,\nalbuminúria).","C":"A etiologia da hipertensão arterial deve ser pesquisada com dosagens de renina sérica e\nultrassom de artérias renais com Doppler.","D":"O paciente não precisa ser acompanhado quanto à sua pressão arterial porque não será\nnecessário o uso de medicamentos."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-314081","number":"314081","sourceNumber":"314081","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual o patógeno mais associado à infecções do trato urinário na faixa etária pediátrica?","options":{"A":"Rotavírus.","B":"Candida.","C":"Streptococcus pneumoniae.","D":"Escherichia coli.","E":"Klebsiella pneumoniae."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-314082","number":"314082","sourceNumber":"314082","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual das doenças exantemáticas abaixo possui a seguinte apresentação? A doença\npossui três estágios: 1) exantema facial maculopapular em regiões malares (face esbofetada); 2)\nlesões maculopapulares em membros, de aspecto rendilhado; 3) desaparecimento do exantema\ncom recorrência induzida por irritantes cutâneos.","options":{"A":"Eritema infeccioso.","B":"Escarlatina.","C":"Impetigo.","D":"Varicela.","E":"Mononucleose infecciosa."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-314090","number":"314090","sourceNumber":"314090","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"As imunodeficiências primárias (IDP) são um grupo heterogêneo de doenças\ncongênitas, caracterizadas por disfunção de um ou\nmais componentes do sistema imunológico,\nocasionando infecções recorrentes, principal manifestação clínica dessas doenças. Em relação aos\nprincipais grupos de IDP, suas características, tipos de infecções e germes mais comuns, numerar\na 2ª coluna de acordo com a 1ª e, após, assinalar a alternativa que apresenta a sequência\nCORRETA: (1) Defeitos predominantemente de anticorpos. (2) Defeitos da imunidade celular\n(células T). (3) Defeitos de complemento. ( ) Predisposição para infecções graves causadas por\npatógenos intracelulares, como microbactérias, Salmonella sp, vírus, fungos, protozoários e germes\noportunistas como Pneumocystis jirovecii. Comorbidades podem frequentemente estar associadas,\ncomo rash neonatal, alterações neurológicas, diarreia persistente e falência de crescimento\nponderoestatural, especialmente nos casos de imunodeficiência combinada grave. ( ) Podem estar\nassociados a quadros autoimunes (vasculites, lúpus eritematoso sistêmico, entre outros) e\ninfecções por bactérias capsuladas. Deficiências dos componentes terminais do complemento (que\ncompõem o complexo de ataque à membrana) predispõem às infecções graves causadas por\nNeisseria sp, como meningites, artrites, uretrites e quadros sépticos. ( ) Suscetibilidade aumentada\npara infecções do trato respiratório (oto-sino-pulmonares) causadas por bactérias extracelulares\ncapsuladas, como Streptococcus pneumoniae, Haemophilus influenzae tipo b, Moraxella sp);\ninfecções gastrointestinais (diarreia crônica) causadas por enterovírus e Giardia lamblia; e outros\nsítios e patógenos, como artrites sépticas causadas por Mycoplasma sp.","options":{"A":"1 - 2 - 3.","B":"3 - 2 - 1.","C":"2 - 3 - 1.","D":"2 - 1 - 3.","E":"3 - 1 - 2."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-257354","number":"257354","sourceNumber":"257354","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação às cardiopatias fetais, assinale a alternativa CORRETA:","options":{"A":"O sistema cardiovascular composto pelo coração, vasos e sanguíneas origina-se da camada\ngerminativa endodérmica.","B":"O ?septo primum? divide o átrio totalmente, permitindo a separação dessas duas cavidades.","C":"As valvas aórtica e pulmonar são formadas entre a sétima e nona semana de gravidez,\ncompletando assim o circuito cardiorrespiratório.","D":"O sistema de condução do coração fetal está maduro ao redor da 16° semana de vida\nintrauterina."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-260684","number":"260684","sourceNumber":"260684","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente, 14meses, apresenta desde os cinco meses otites de repetição (5 episódios)\nsendo quatro episódios com supuração. O pediatra\nencaminha para o imunologista por suspeita de\nimunodeficiência primária do tipo celular. Esse encaminhamento se justifica:","options":{"A":"Não, já que a hipogamaglobulinemia fisiológica é comum até dois anos.","B":"Sim, mas a suspeita é de imunodeficiência primária humoral.","C":"Sim, mas a suspeita é de imunodeficiência primária do sistema complemento.","D":"Não, pois não veremos imunodeficiência primária após os seis meses de vida","E":"Não, pois não ocorreu nenhum episódio de infecção associado a internação hospitalar."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-257367","number":"257367","sourceNumber":"257367","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A causa mais comum de parada cardiorrespiratória em crianças é a:","options":{"A":"Fibrilação ventricular.","B":"Taquicardia ventricular sem pulso.","C":"Asfixia.","D":"Taquipneia."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-287352","number":"287352","sourceNumber":"287352","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Pré-adolescente, 10 anos, apresenta pressão arterial alterada (aferida 03 vezes, em\nintervalos de 02 a 03 semanas cada) e IMC (Índice de Massa Corpórea) acima do P95.\n\nCorrelacionado com sua altura e peso, evidenciou-se que todas as aferições da pressão arterial\nestavam superiores ao P95. Pai e mãe apresentam obesidade. Qual o provável diagnóstico e\norientações?","options":{"A":"Hipertensão arterial essencial. Deve ser orientado perda de peso, atividade física e tratamento\nmedicamentoso até nova avaliação.","B":"Hipertensão arterial secundária a lesão reno-vascular. Deve ser solicitado Ultrassonografia de\nartérias renais.","C":"Hipertensão arterial secundária a alterações endocrinológicas. Encaminhar ao Endocrinologista.","D":"Não há necessidade de se preocupar. Aguardar o estirão puberal que haverá normalização da\npressão arterial."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-257368","number":"257368","sourceNumber":"257368","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Você é chamado para atender uma Parada Cardiorrespiratória (PCR) na ala pediátrica.\nAo chegar você encontra um lactente de 17 meses\nrecebendo ventilações com máscara e\ncompressões torácicas em uma relação de 30 compressões: 2 ventilações. Ele já se encontra\nmonitorizado e você evidencia no monitor uma fibrilação ventricular. Nessas condições, sua\nRECOMENDAÇÃO seria de:","options":{"A":"Fazer amiodarona EV e manter relação compressão de 30:2.","B":"Fazer amiodarona EV e mudar relação de compressão para 15:2.","C":"Desfibrilar com 2J/Kg e manter relação de compressão 30:2.","D":"Desfibrilar com 2J/Kg e mudar relação de compressão para 15:2."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-287903","number":"287903","sourceNumber":"287903","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Conforme CAMPOS, BURNS e LOPEZ, a apresentação clínica da Infecção do Trato\nUrinário (ITU) varia de acordo com o grupo\netário e com a localização da infecção. Outros fatores\ninfluenciam as manifestações clínicas, como estado nutricional, presença de alterações anatômicas\ndo trato urinário, número de infecções anteriores e intervalo de tempo do último episódio\ninfeccioso.\nEm relação à ITU na pediatria, analisar os itens abaixo: I. A persistência de bexiga palpável após a\nmicção sugere processo obstrutivo ou disfunção do trato urinário inferior. II. A presença de uma ou\nmais bactérias (bastonetes Gram-negativos) em gota de urina não centrifugada corada pelo Gram\ncorrelaciona-se fortemente com bacteriúria significativa demonstrada pela urocultura. III.\nCateterismo vesical é um método invasivo que pode provocar ITU no caso de falha técnica no\nprocedimento, além de ser desconfortável para o paciente. Não deve ser usado de rotina para\ncoleta de material que é eliminado espontaneamente, como a urina. Está(ão) CORRETOS(S).","options":{"A":"Somente o item I.","B":"Somente o item II.","C":"Somente os itens I e III.","D":"Somente os itens II e III.","E":"Todos os itens."},"answer":"E","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-287910","number":"287910","sourceNumber":"287910","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação à febre em crianças, analisar a sentença a seguir: A expressão \"febre de\norigem indeterminada\" (FOI) deve ser reservada para crianças com febre documentada por\nprofissional de saúde e para a qual a causa não pode ser identificada após três semanas de\navaliação no ambulatório ou após uma semana de avaliação em hospital (1ª parte). As principais\ncausas de FOI em crianças são infecções e doenças reumatológicas (autoimunes ou do tecido\nconjuntivo) (2ª parte). Distúrbios neoplásicos devem ser seriamente considerados, embora a maior\nparte das crianças com doenças malignas não apresente febre como sinal clínico isolado (3ª parte)\nSe o paciente estiver recebendo qualquer droga, a possibilidade de febre medicamentosa sempre\ndeve ser considerada (4ª parte). A sentença está:","options":{"A":"Totalmente correta.","B":"Correta somente em suas 1ª e 3ª partes.","C":"Correta somente em suas 1ª e 4ª partes.","D":"Correta somente em suas 2ª, 3ª e 4ª partes.","E":"Totalmente incorreta."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-255617","number":"255617","sourceNumber":"255617","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Febre é uma queixa comum e corresponde a aproximadamente 25% de todas as\nconsultas na emergência de pediatria. Na maioria dos casos, é possível identificar a origem da\nfebre após anamnese detalhada e exame físico completo. Para definição de febre, é necessária\numa temperatura axilar acima de? MARQUE A CORRETA:","options":{"A":"37,8°","B":"38,0°","C":"38,3°","D":"38,5°"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-255620","number":"255620","sourceNumber":"255620","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O exantema é uma erupção cutânea associada a uma doença sistêmica, geralmente de\ncausa infecciosa. Em relação aos achados de\nexame físico da Escarlatina na infância MARQUE A\nCORRETA:","options":{"A":"Aparência de ?bochecha esbofeteada?","B":"Sinal de Filatow","C":"Manchas de Koplick","D":"Sinal de Berliner"},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-232110","number":"232110","sourceNumber":"232110","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"No sarampo, a ocorrência de superinfecção viral ou bacteriana é facilitada pelo(a):","options":{"A":"Comprometimento da resistência do hospedeiro à doença.","B":"Escurecimento do exantema antes do início da descamação furfurácia.","C":"Faixa etária mais avançada quando ele se torna mais grave.","D":"Fato de a doença ser aguda e RNA vírus.","E":"Devido o período de incubação ser de até 14 dias."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-246365","number":"246365","sourceNumber":"246365","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente, 12 meses de idade dá entrada no PS com relato de irritabilidade associado a\nquadro febril com temperatura aferida de 39,8ºC e episódio de convulsão tônico-clônica\ngeneralizada. Na investigação diagnóstica foram coletados os seguintes exames: Hb 11,5 / Htco\n36% / Leuco 9200 (NB 02 / NS 24 / E 02 / L 66 / M 6) PLQ 325.000; PCR: 0,8; LCR - leuco 0 /\n\nglicose 45 / proteína 29/ Hm 02). Como a febre persistiu por 72 horas, apesar do exame clínico\nnormal, foi iniciado amoxacilina. No dia\nseguinte ao início da antibioticoterapia, a criança\napresentou-se afebril e com exantema rosado maculopapular de início no tronco, não pruriginoso.\nQual o diagnóstico e agente etiológico mais provável?","options":{"A":"Sarampo, paramyxovírus.","B":"Rubéola, RNA-vírus.","C":"Exantema súbito, herpes-vírus humano 6 e 7.","D":"Escarlatina, Streptococcus pyogenes."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-246367","number":"246367","sourceNumber":"246367","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma gestante é admitida no hospital em trabalho de parto. Trata-se de um bebê do\nsexo masculino. A mãe traz um ultrassom,\nrealizado durante a gravidez, com evidências de\nmoderada dilatação de pelve renal bilateral e bexiga com paredes espessadas. Nos primeiros dias\napós o nascimento notou-se globo vesical palpável e jato urinário fino e entrecortado tipo\ngotejamento. Qual é a malformação do trato urinário mais provável?","options":{"A":"Estenose de junção ureteropélvica.","B":"Válvula de uretra posterior.","C":"Refluxo vesicoureteral.","D":"Megaureter congênito primário."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-227093","number":"227093","sourceNumber":"227093","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente de 3 anos, apresentando febre baixa, erupção vermelha no rosto que leva a\nimpressão que a criança recebeu um tapa no rosto. Apresenta também uma erupção em padrão de\nfiligrana nos braços, pernas e troncos. Considerando o caso descrito, é INCORRETO afirmar que:","options":{"A":"O agente etiológico mais comumente envolvido é o parvovírus B19.","B":"O tratamento da patologia requer uso de antibiótico em função do exantema presente na face.","C":"O tempo de incubação da doença é de 4 a 14 dias.","D":"A sorologia pode ser feita para confirmar o diagnóstico."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-227094","number":"227094","sourceNumber":"227094","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em todo o mundo, o sarampo infecta cerca de 20 milhões de pessoas por ano e causa\npor volta de 200.000 mortes, principalmente\nem crianças. Em relação ao sarampo, é INCORRETO\nafirmar que:","options":{"A":"O sarampo é causado por um paramixovírus e é uma doença humana sem reservatório animal\nconhecido e extremamamente contagiosa.","B":"O exantema do sarampo é do tipo maculopapular, de evolução centrípeta.","C":"O sarampo apesar de ser uma doença comum da infância, pode apresentar complicações\ngraves.","D":"O sarampo pode apresentar febre, tosse, conjuntivite e coriza como sintomas."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-234425","number":"234425","sourceNumber":"234425","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em uma consulta de pronto atendimento, mãe traz seu filho com relato de febre e\nexantema. Trata-se de criança do sexo\nfeminino, 1 ano e 1 mês de vida, que, apresenta febre,\ncoriza e tosse de 6 dias de evolução, hipertrofia e hiperemia de amígdalas sem exsudato,\nlinfonodos aumentados em cadeias cervical anterior e posterior e fígado palpável a 3,5cm do\nrebordo costal direito e baço palpável a 2cm do rebordo costal esquerdo. Mãe relata que no início\ndo quadro procurara atendimento médico sendo prescrito amoxicilina para tratamento de\namigdalite. Evoluiu durante todo quadro com persistência de sintomas e exantema morbiliforme\ndifuso. Realizou hemograma por conta própria com evidência de mais de 10% de linfócitos atípicos.\nSobre o quadro clínico descrito, é CORRETO afirmar que:","options":{"A":"A principal hipótese diagnóstica é a doença de Kawasaki, haja vista a idade da paciente, febre\nprolongada, bem como os achados do exame físico citados. Deve-se solicitar internação hospitalar,\niniciar ácido acetilsalicílico e solicitar ecocardiograma.","B":"A principal hipótese diagnóstica é escarlatina, haja vista a idade da paciente, febre prolongada,\nos achados do exame físico citados, bem como o\nhemograma típico. Deve-se ampliar o espectro de\nantibiótico associando clavulanato ao esquema utilizado.","C":"A principal hipótese diagnóstica é mononucleose, haja vista a presença de febre, os achados do\nexame físico citados, bem como o hemograma\ntípico. Deve-se suspender antibiótico, tratar com\nsintomáticos e acompanhar a evolução do quadro, podendo realizar sorologia.","D":"A principal hipótese diagnóstica é reação alérgica medicamentosa, haja vista a presença de\nfebre, os achados do exame físico citados, bem como o hemograma típico. Deve-se modificar o\nantibiótico para classe que não seja penicilina e tenha ação contra estreptococo."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-234426","number":"234426","sourceNumber":"234426","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em uma consulta de pronto atendimento mãe traz seu filho, 6 meses 10 dias, com\nquadro de febre de 3 dias de evolução,\nhiporexia de 7 dias de evolução e vômitos associados.\nRelata que antes do quadro se iniciar lactente estava clinicamente bem. Em consulta de\npuericultura realizada exatamente no dia em que fez 6 meses, apresentara 7,2kg. No pronto\natendimento paciente encontrava-se com 6,9kg, choroso, porém consolável, febril (Tax 39ºC),\ntaquicárdico e taquipneico (dados vitais melhoraram após febre ceder). Pediatra de plantão solicitou\nrevisão laboratorial (com evidência de hemograma com leucocitose sem desvio, proteína C reativa\nelevada, urina rotina com leucócito esterase e nitrito positivos 2+, flora bacteriana moderada, gram\nde gota sem visualização de bactérias, urocultura em andamento) e passou o caso para você. Com\nbase no quadro descrito, é CORRETO afirmar que:","options":{"A":"Trata-se de um provável quadro de enterovirose, haja visto que o paciente apresenta febre,\nvômitos e perda ponderal. Deve-se aguardar urocultura uma vez que a urina rotina não sugere\ninfecção e o gram de gota não evidenciou bactérias coráveis.","B":"Trata-se de um provável quadro de alergia à proteína do leite de vaca, haja visto que o paciente\napresenta febre, vômitos e perda ponderal. Deve-se aguardar urocultura uma vez que a urina rotina\nnão sugere infecção e o gram de gota não evidenciou bactérias coráveis.","C":"Trata-se de um provável quadro de infecção do trato urinário, haja visto que o paciente\napresenta febre, vômitos e perda ponderal.\nDeve-se aguardar urocultura uma vez que a urina rotina\nnão sugere infecção e o gram de gota não evidenciou bactérias coráveis.","D":"Trata-se de um provável quadro de infecção do trato urinário, haja visto que o paciente\napresenta febre, vômitos e perda ponderal.\nDeve-se iniciar antibioticoterapia imediatamente após\ncoleta de urocultura, uma vez que a urina rotina sugere infecção do trato urinário."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-232127","number":"232127","sourceNumber":"232127","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de nove meses apresentou febre elevada e irritabilidade durante 3 dias. No\nquarto dia da doença, surgiu exantema maculopapular na face e tronco, persistindo por 3 dias e\nnão sendo observado febre no período do exantema. A etiologia mais provável para o caso é","options":{"A":"estreptococo do grupo A.","B":"vírus da rubéola.","C":"parvovírus B19.","D":"herpes-vírus-humano tipo 6.","E":"coxsackievirus."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-232129","number":"232129","sourceNumber":"232129","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança, cinco anos de idade, chega ao pronto atendimento com a mãe, que relata ter\nsentido ?massa? na barriga do filho. Exame físico: regular estado geral, hipocorada+/4+, hidratada,\nmassa de consistência endurecida no andar superior do abdome, sem ultrapassar linha média. PA\nno percentil 99 para a idade e estatura. Exame de urina: hematúria microscópica. O diagnóstico\nmais provável e o exame a ser solicitado, respectivamente, são:","options":{"A":"tumor de Wilms; US abdominal total.","B":"linfoma; US abdominal total.","C":"glomerulonefrite difusa aguda; C3 e C4.","D":"púrpura de Henoch Schönlein; US abdominal total.","E":"Leucemia Mieloide Aguda; Hemograma e Mielograma."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-234429","number":"234429","sourceNumber":"234429","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A respeito das imunodeficiências primárias, é CORRETO afirmar que:","options":{"A":"A deficiência de IgA é a imunodeficiência mais comum e deve ser tratada com infusão\nendovenosa de imunoglobulina (IVIG).","B":"A maioria dos casos de infecção recorrente na infância têm relação com deficiências\nimunológicas identificáveis.","C":"A história de uma infecção bacteriana grave, como sepse e meningite, deve levar à suspeição\nclínica de imunodeficiência primária.","D":"O teste do pezinho oferecido pelo Sistema Único de Saúde realiza triagem para imunodeficiência\ncombinada grave."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-227102","number":"227102","sourceNumber":"227102","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A doença de Kawasaki é uma vasculite que, às vezes, envolve as artérias coronárias e\ntende a ocorrer em lactentes e crianças de 1 a 8 anos. Sobre a doença de Kawasaki, assinale a\nalternativa INCORRETA:","options":{"A":"O tratamento é feito com ácido acetilsalicílico e globulina imune intravenosa.","B":"A doença de Kawasaki é uma vasculite de artérias de tamanho grande.","C":"O diagnóstico é baseado em critérios clínicos, acompanhados de ecocardiograma.","D":"O diagnóstico é feito se a febre durou ? 5 dias associados a outros critérios como conjuntivite\nbilateral."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-243021","number":"243021","sourceNumber":"243021","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente quatro anos, inicia há três dias quadro de astenia, odinofagia, anorexia, febre\n(38ºc) e adenomegalias em região\nsuboccipital e pós auriculares bilaterais. Evoluiu com exantema\nmaculo-papular róseo claro, de início em face e pescoço, com distribuição crânio- caudal. Ao\nexame da orofaringe nota-se lesões pequenas, de coloração rósea e petéquias em palato mole. Em\nrelação ao quadro, o agente causal determinante é:","options":{"A":"rotavírus.","B":"norovírus.","C":"vírus da rubéola.","D":"vírus do sarampo.","E":"H1N1."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-243023","number":"243023","sourceNumber":"243023","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente de quatro anos levado ao pronto-socorro com relato da mãe de ter sentido nos\núltimos cinco dias, massa endurecida na barriga de sua filha. Nega febre ou outros sintomas. Ao\nexame físico, regular estado geral, hipocorada+/4+, hidratada, massa de consistência endurecida\nno andar superior do abdome sem ultrapassar linha média. Exame de urina: hematúria\nmicroscópica. O diagnóstico mais provável e o exame a ser solicitado, respectivamente, são:","options":{"A":"púrpura de Henoch Schönlein; US abdominal total.","B":"tumor de Wilms; US abdominal total.","C":"neuroblastoma; tomografia abdominal","D":"linfoma; US abdominal total.","E":"nenhuma das alternativas anteriores."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-243024","number":"243024","sourceNumber":"243024","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de 1 ano, apresenta febre alta, astenia, anorexia, tosse, coriza e conjuntivite\nnão exsudativa com fotofobia. Ao exame da cavidade\noral nota-se presença de pontos brancos\nazulados próximos aos molares. Qual a principal complicação bacteriana da patologia descrita:","options":{"A":"pneumonia.","B":"sinusite.","C":"otite.","D":"amigdalite.","E":"estomatite."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-227308","number":"227308","sourceNumber":"227308","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Nas viroses exantemáticas, a análise do tipo da lesão, dos sinais e dos sintomas\nconcomitantes e a epidemiologia, algumas\nvezes, permitem inferir o diagnóstico etiológico, sem a\nnecessidade de exames laboratoriais complementares. Nas doenças exantemáticas é CORRETO\nafirmar:","options":{"A":"O sarampo é uma doença exantemática, que, apesar dos pródromos, raramente complica. A\ndoença começa com febre, tosse, cefaleia e\nmal-estar que duram de 3 a 4 dias. O exantema é\nmaculopapular róseo não confluente, inicia nas extremidades e raramente atinge a face.","B":"A rubéola apresenta mal-estar e febre antecedendo 1 a 2 dias do exantema, que é\nmaculopapular róseo e se inicia nos membros\ninferiores, espalhando-se para o tronco e rosto em\n24 horas. A orofaringe fica hiperemiada e, na região oposta aos dentes molares, aparecem\nmanchas branco-azuladas, pequenas, de cerca de 1 mm de diâmetro, chamadas de manchas de\nKoplik.","C":"A roséola infantil, ou exantema súbito, apresenta febre por 3 a 4 dias e, quando a febre cessa\nbruscamente, aparece o exantema com lesões maculopapulares rosadas, que se iniciam no tronco\ne se disseminam para a cabeça e as extremidades, e duram de algumas horas a 2-3 dias. É\nconsiderada uma das causas mais comuns de convulsão febril.","D":"O eritema infeccioso é causado por um enterovírus e apresenta febre, mialgia e adinamia,\niniciada 4 a 5 dias antes do exantema, que se inicia nos membros e evoluem para a face. O\nexantema se apresenta como maculopápulas que confluem, tornando-se uma placa\n\nvermelho-rubra, concentrada, principalmente, na face e tronco. O exantema dura menos de 5 dias.\nUm achado marcante é a adenomegalia, retroauricular e occipital."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-227320","number":"227320","sourceNumber":"227320","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente, 10 anos, durante consulta de rotina observou-se hiperfonese de B1 e\ndesdobramento fixo de B2. Sopro sistólico +/6 em borda esternal esquerda. Pressão arterial e\npulsos normais. É uma criança saudável e joga futebol. Diante do relato, qual lesão cardíaca é a\nmais provável?","options":{"A":"Comunicação interatrial.","B":"Estenose de valva pulmonar.","C":"Persistência do canal arterial.","D":"Comunicação interventricular."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-246795","number":"246795","sourceNumber":"246795","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Pré-escolar de 4 anos de idade tem febre há uma semana, acompanhada de edema\npalpebral, exsudato nas amígdalas, adenomegalia cervical bilateral e hepatoesplenomegalia. O\nhemograma mostra leucocitose com linfocitose e linfócitos atípicos. O diagnóstico mais provável é:","options":{"A":"Citomegalovirose","B":"Doença de kawasaki","C":"Leishmaniose visceral","D":"Mononucleose infecciosa","E":"Escarlatina"},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-243069","number":"243069","sourceNumber":"243069","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente do sexo feminino, com 33 anos, vem à consulta devido a achado de sopro.\nRefere ser completamente assintomática e\nnega comorbidades e uso de medicações. Ao exame,\napresenta-se em bom estado geral, frequência cardíaca (FC) = 83 bpm; pressão arterial (PA)= 112\nx 58 mmHg, com ausculta de ritmo cardíaco regular e sopro regurgitativo +++ em foco mitral,\nmesotelessistólico, com irradiação para linha axilar média, sem outros achados ao exame clínico.\nTraz eletrocardiograma em ritmo sinusal e ecocardiograma transtorácico: átrio esquerdo de 36 mm,\nventrículo esquerdo = 48 x 31 mm, fração de ejeção de 65%, insuficiência mitral importante com\nprolapso de cúspide anterior, segmento A2 e A3, pressão sistólica da artéria pulmonar (PSAP) = 33\nmmHg. Assinale a conduta CORRETA para a paciente descrita:","options":{"A":"intervenção valvar mitral precoce com indicação de plástica mitral.","B":"tratamento clínico/medicamentoso com diuréticos e vasodilatadores (preferência por IECA ou\nBRA).","C":"intervenção valvar mitral precoce com indicação de troca valvar mitral por bioprótese.","D":"acompanhamento clínico e ecocardiográfico a cada 6 meses, orientando a paciente retornar ao\nconsultório em caso de surgimento de sintomas.","E":"intervenção valvar mitral precoce com indicação de MitraClip."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-202741","number":"202741","sourceNumber":"202741","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação à Febre do Nilo Ocidental, considerando seus hospedeiros e reservatórios,\né correto afirmar:","options":{"A":"No ciclo silvestre os primatas não humanos são os principais hospedeiros e amplificadores do\nvírus.","B":"O ciclo de transmissão do vírus envolve aves e mosquitos. Nos mosquitos, a transmissão vertical\ndo vírus favorece a sua manutenção na\nnatureza.","C":"No Brasil, os principais vetores e reservatórios são os carrapatos do gênero Amblyomma,\nentretanto,\n\npotencialmente, qualquer espécie de carrapato pode ser reservatório.","D":"Centenas de espécies de mamíferos (silvestres e domésticos) presentes em todos os biomas do\nBrasil podem ser consideradas reservatórios.","E":"Os animais sinantrópicos (roedores) e domésticos (canídeos, felídeos e equídeos) fazem parte\nda cadeia de transmissão. Com relação a esses\núltimos, seu papel na manutenção do parasito no\nmeio ambiente ainda não foi esclarecido."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-199564","number":"199564","sourceNumber":"199564","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente viajou para o Amazonas durante as férias e, após retorno, iniciou quadro de\nfebre, tosse seca e coriza. Fez uso de\ndipirona intermitente devido aos episódios febris. Após 3 dias\ndo início dos sintomas, associou-se um quadro de rash cutâneo. Esta paciente foi atendida no\npronto-socorro do Hospital Universitário Cassiano Antônio Moraes (HUCAM). Quais as hipóteses\ndiagnósticas prováveis nesse caso?","options":{"A":"Rubéola, varicela.","B":"Sarampo, toxoplasmose aguda.","C":"Febre amarela, influenza complicando com farmacodermia.","D":"Sarampo, influenza complicando com farmacodermia."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-202772","number":"202772","sourceNumber":"202772","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A respeito do transporte seguro de crianças e adolescentes em veículos automotores, é\ncorreto afirmar que:","options":{"A":"Crianças e adolescentes menores de 13 anos podem viajar no banco dianteiro, desde que\nutilizem cinto de três pontos e air bag desativado.","B":"Crianças e adolescentes com estatura inferior a 1,45 m devem utilizar assentos elevadores com\ncinto de três pontos no banco dianteiro.","C":"Não se aplica o uso de dispositivo restritivo de segurança para crianças ou adolescentes que\nnão tenham ainda a altura de 1,45 m.","D":"Crianças com estatura superior a 1,45 m (média aos 11 anos de idade) podem passar a usar o\ncinto de segurança de três pontos.","E":"Criança ou adolescente, independente de altura ou idade, não pode utilizar o banco dianteiro se\no air bag estiver ativado."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-202776","number":"202776","sourceNumber":"202776","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de oito meses, sexo feminino, com quadro de febre há sete dias apresenta\nvômitos incoercíveis há 20 horas. A mãe procura\nserviço médico de emergência pela terceira vez.\nDurante interrogatório sobre antecedentes pessoais, ela relata que a paciente teve infecção do trato\nurinário duas vezes, aos quatro e cinco meses. Exame físico: regular estado geral e palidez\nmoderada. Exame de urina (coletado por cateterismo vesical): leucocitúria: 50.000UFC/ml,\nhematúria: 15.000/ml; bacterioscopia: muitas bactérias. Faz-se o diagnóstico provável de ITU e\nsolicita-se urinocultura com teste de sensibilidade antimicrobiana (TSA). A conduta adequada é:","options":{"A":"Solicitar internação hospitalar, hidratação venosa, início imediato de antibioticoterapia\nvenosa.","B":"Solicitar internação hospitalar, hidratação venosa e aguardar resultado de urinocultura para\niniciar antibioticoterapia.","C":"Prescrever antibiotioterapia oral, anti-emético e liberada com orientações e encaminhamento\npara nefrologia pediátrica.","D":"Solicitar ultrassonografia de vias urinárias para descartar malformações, antibioticoterapia\noral e\nliberada com orientações.","E":"Aguardar parecer da nefrologia pediátrica para traçar a conduta, já que se trata de uma criança\ncom infecção urinaria de repetição."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-220319","number":"220319","sourceNumber":"220319","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança com 2 anos é internada por apresentar quadro de febre de 39°C há 6 dias, sem\nmelhora com o uso de antitérmicos. Recebeu avaliação médica por 2 vezes, com diagnóstico de\namigdalite viral. Exame físico mostrou criança com regular estado geral, prostrada, com\nlinfadenopatia cervical de 2,5 cm de diâmetro, exantema maculopapular difuso, edema de mãos e\npés, conjuntivite bilateral não supurativa e presença de hiperemia labial e de orofaringe com língua\nem framboesa. Hemograma com leucocitose com predomínio de neutrófilo, contagem de plaquetas\nnormais e provas de atividades inflamatórias aumentadas (VHS, proteína C reativa). Considerando\no caso descrito, assinale a alternativa que apresenta a PRINCIPAL hipótese diagnóstica:","options":{"A":"Doença de Kawasaki.","B":"Escarlatina.","C":"Artrite idiopática juvenil.","D":"Mononucleose infecciosa."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-220326","number":"220326","sourceNumber":"220326","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Sobre o refluxo vesicoureteral, assinale a alternativa CORRETA:","options":{"A":"O refluxo vesicoureteral pode ser classificado como primário, tendo como exemplo a disfunção\nneuropática e como secundário, tendo como exemplo as anomalias ureterais como orifício ectópico.","B":"O refluxo vesicoureteral se associa a uma incidência aumentada de pielonefrites e esse refluxo\npode ser encontrado em até 30 a 50% das crianças com ITU.","C":"O refluxo significativo é mais diagnosticado em homens quando comparado às mulheres.","D":"O estudo mais útil para essa condição de refluxo é a tomografia computadorizada."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215120","number":"215120","sourceNumber":"215120","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Os campos da imunologia e da oncologia estão ligados desde o final do século 19,\nquando o cirurgião William Coley relatou\nque uma injeção de bactérias mortas em locais de\nsarcoma poderia levar ao encolhimento do tumor. Desde então, os avanços exponenciais na\ncompreensão da interseção entre a vigilância imunológica e o crescimento e desenvolvimento do\ntumor levaram a amplos avanços terapêuticos que agora estão sendo estudados em todos os tipos\nde câncer, o que abrange o conceito de Imunoterapia. Uma resposta imune citotóxica eficiente e\nespecífica contra um tumor requer uma interação complexa e de rápida evolução entre vários tipos\nde células no sistema imune adaptativo e inato. Os tipos de células envolvidas diretamente no\nreconhecimento e rejeição de tumores são, EXCETO:","options":{"A":"Linfócitos CD8 + e CD4 +, tradicionalmente denominados células T citotóxicas e células T\nauxiliares.","B":"Células Natural Killer (NK) que não requerem apresentação de antígeno pelo complexo principal\nde histocompatibilidade (MHC) para atividade citotóxica.","C":"CD3, que codifica um complexo proteico transmembranar não variável com um componente de\nativação baseado em tirosina intracelular.","D":"FoxP3 + / CD25 + / CD4 + / T regulatório (Treg) e células supressoras derivadas de mielóides\n(MDSCs) que inibem em grande parte a atividade dos linfócitos T citotóxicos.","E":"Macrófagos M1, que liberam interferon (IFN) gama e são responsáveis pela fagocitose, e\nmacrófagos M2, que liberam citocinas como IL-4, IL-10, fator de crescimento transformador beta\n(TGF- beta)."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-199572","number":"199572","sourceNumber":"199572","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Você está fazendo compras no shopping e encontra escolar, aparentando ter entre 8 a\n9 anos de idade, deitado no chão e parece\ninconsciente. Diante desse cenário, seguindo as\nDiretrizes de Ressuscitação Cardiopulmonar (RCP) 2015, deve-se:","options":{"A":"Chamar por ajuda (192) e solicitar desfibrilador externo automático (DEA), afastar curiosos da\ncena, checar pulso carotídeo e logo após checar respiração e, se ausentes, iniciar compressões\ntorácicas: ventilações (CT:V = 30:2).","B":"Avaliar a responsividade da vítima. Se não responde, chamar por ajuda (192) e solicitar DEA,\nchecar pulso carotídeo e respiração simultaneamente e, se ausentes, iniciar compressões\ntorácicas: ventilações (CV:T = 30:2).","C":"Afastar curiosos da cena, checar pulso carotídeo e logo após checar respiração e, se presentes,\nsolicitar ajuda para quem tem carro,\ntransportar a vítima para o carro do ajudante e levá-la\nimediatamente para o pronto-socorro mais próximo.","D":"Avaliar a responsividade da vítima. Se não responde, chamar por ajuda (192) e solicitar DEA,\nchecar pulso carotídeo e respiração de modo simultâneo e, se ausentes, iniciar compressões\ntorácicas: ventilações (CT: V = 15:2), se você tiver dispositivo de barreira. Se não possuir esse\ndispositivo, manter somente compressões torácicas 100 a 120/minuto."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-212936","number":"212936","sourceNumber":"212936","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual o agente etiológico mais comum e qual a respectiva manifestação clínica mais\nfrequente na infecção urinária aguda de um lactente de 1 ano do sexo feminino?","options":{"A":"Escherichia coli / disúria, polaciúria e enurese.","B":"Escherichia coli / febre, irritabilidade, recusa alimentar.","C":"Staphylococcus aureus / disúria, polaciúria e enurese.","D":"Staphylococcus aureus / febre, irritabilidade, recusa alimentar.","E":"Klebsiella / disúria, polaciúria e enurese."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-196728","number":"196728","sourceNumber":"196728","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"As situações de violência e maus tratos a criança e ao adolescente certamente geram\nsequelas em curto e em longo prazo no indivíduo agredido e em toda sociedade. Os profissionais\nde saúde precisam estar sempre atentos para o diagnóstico precoce de violência infantil. Marque a\nafirmativa correta:","options":{"A":"É aceitável que bater em crianças ou adolescentes em condições limitadas não configura abuso,\na menos que acarrete lesões com fraturas,\nhematomas, etc.","B":"Todas as crianças sob acolhimento institucional tem direito a avaliação completa de saúde\nmental assim como a indicação ao uso de medicamentos psicotrópicos.","C":"A remoção da criança de um lar caótico é sempre bem recebido pelas crianças e adolescentes\ncom a sensação de alivio imediato.","D":"A maneira mais simples de reconhecer a possibilidade de violência intrafamiliar é observar\nregularmente os pais e as crianças."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-196741","number":"196741","sourceNumber":"196741","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Médicos da assistência primária devem sempre considerar a hipótese de alteração do\nsistema imunológico diante de algumas especificidades na anamnese e exame físico da criança.\nDessa forma, a capacitação e atualização sistemática para as imunodeficiências primárias é\nessencial. Marque a afirmativa correta.","options":{"A":"A produção de anticorpos pelas células B deve ser avaliado pelos níveis séricos de\nimunoglobulina e linfócitos T","B":"A exclusão inicial de defeitos imunológicos é dispendiosa e demorada, quase sempre realizadas\nem laboratórios especializados","C":"A avaliação da função imunológica deve ser iniciada nos casos de lactentes e crianças com\ndesordens imunológicas especificas e em todos os casos com infecções raras, crônicas ou de\nrepetição","D":"Quando os resultados de triagem inicial forem normais, para os pacientes com infecções\nbacterianas de repetição e pouco frequentes,\ntorna-se desnecessária a investigação de células\nfagocitárias e de células T"},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-196768","number":"196768","sourceNumber":"196768","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Mãe leva seu filho de 7 anos de idade à unidade de pronto atendimento com queixa de\nestar, há 48 horas, com quadro de febre alta persistente, calafrios, cefaleia intensa e dor de\ngarganta. No dia da consulta, paciente apresentando exantemas formados por pequenas pápulas\neritematosas muito próximas umas das outras, muito mais concentradas em regiões de dobras\ncutâneas. Além disso, rubor facial bem evidente, exceto por palidez ao redor da boca evidente. O\ndiagnóstico mais provável é:","options":{"A":"Escarlatina.","B":"Mononucleose infecciosa.","C":"Eritema infeccioso.","D":"Exantema súbito."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-212894","number":"212894","sourceNumber":"212894","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual a alteração laboratorial mais frequente na mononucleose infecciosa?","options":{"A":"Leucopenia com neutropenia.","B":"Trombocitose e leucopenia.","C":"Leucocitose com linfocitose e presença de linfócitos atípicos.","D":"Anemia hemolítica e eosinofilia.","E":"Leucopenia com anemia hemolítica."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-212903","number":"212903","sourceNumber":"212903","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O achado de pulso femoral ausente ou fraco e pulso radial vigoroso sugere o\ndiagnóstico de:","options":{"A":"Transposição de grandes vasos da base.","B":"Persistência do canal arterial.","C":"Coarctação da aorta.","D":"Comunicação interatrial.","E":"Comunicação interventricular."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-199640","number":"199640","sourceNumber":"199640","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"O Traumatismo Cranioencefálico (TCE) é o acidente mais prevalente nas crianças\nmenores de 5 anos, em especial nas menores de\n1 ano. Ainda que a grande maioria dos casos se\napresente como casos leves, de baixa complexidade, o reconhecimento dos casos de risco e a\npronta intervenção neles é papel importante do profissional que cuida de crianças e adolescentes.\nNo traumatismo cranioencefálico na criança é CORRETO afirmar:","options":{"A":"A classificação TCE baseia-se na escala de coma de Glasgow e é considerado TCE leve a\nescala de coma de Glasgow de 14 ou 15; TCE\nmoderado escala de coma de Glasgow entre 5 e 13\ne TCE grave a escala de coma de Glasgow igual ou menor que 4.","B":"A clássica síndrome do bebê sacudido (shaken baby) caracteriza-se por ausência de sinais\nexternos de traumatismo, com hemorragia subdural ou subaracnóidea bilateral e hemorragia\nretiniana.","C":"Hematoma subdural é caracterizado por presença aguda de sangue no espaço subdural.\n\nForma-se por sangramento arterial, espalhando-se sobre o hemisfério cerebral. Todos os casos são\ncirúrgicos, com elevados índices de morbimortalidade.","D":"A contusão cerebral ocorre diametralmente oposta ao local do impacto, pela inércia (lesão de\ncontragolpe). O tratamento geralmente é cirúrgico."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-212920","number":"212920","sourceNumber":"212920","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente de 2 meses dá entrada no serviço de emergência com hipotonia generalizada\ne crise convulsiva. A convulsão rapidamente\ncedeu com o uso de diazepam. O pai relata que, antes\ndo início da convulsão, o filho chorava muito. Fundoscopia evidenciou hemorragia retiniana bilateral\ndifusa. Foi submetida a exame do líquido cefalorraquidiano que foi hemorrágico, e a tomografia de\ncrânio mostrou hemorragia inter- hemisférica na região de seio longitudinal superior e \"swelling\"\ncerebral. Raio X de crânio normal. A principal hipótese diagnóstica é:","options":{"A":"Intoxicação exógena.","B":"Coagulopatia adquirida.","C":"Deficiência de piridoxina.","D":"Síndrome do bebê sacudido.","E":"Acidúria glutárica tipo 1."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-212943","number":"212943","sourceNumber":"212943","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente de 3 anos de idade, do sexo masculino, branco, é levado pelos pais para\nconsulta com pediatra. Tem história de que há\ndois meses tem dor abdominal e sudorese noturna.\nAo exame físico está em regular estado geral, tem extremidades mais frias no lado direito do corpo\ne hipertensão arterial, protrusão de globo ocular direito e equimose periorbitária direita, e\nextensa\ntumoração em loja renal direita, de limites imprecisos, atravessando a linha média do abdome.\n\nManifestou choro intenso à palpação de membros inferiores. Pensando que pode ser um tumor\nabdominal maligno, qual seria sua hipótese diagnóstica mais provável?","options":{"A":"Neuroblastoma.","B":"Tumor de Wilms.","C":"Linfoma não Hodgkin.","D":"Rabdomiossarcoma.","E":"Carcinoma de suprarrenal."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-196796","number":"196796","sourceNumber":"196796","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Quais são as doenças entre as opções abaixo que causam febre no viajante? Marque a\nCORRETA:","options":{"A":"Febre amarela, peste bubônica e leishmaniose visceral","B":"Hepatite B, Hepatite A e esquistossomose","C":"Hanseníase, tuberculose e sífilis","D":"Sífilis, gonorréia e Infecção aguda pelo HIV"},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-196816","number":"196816","sourceNumber":"196816","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual grupo populacional e faixa etária mais afetada pela Síndrome mão-pé-boca\n(SMPB) ? Marque a CORRETA.","options":{"A":"Adultos jovens entre 25 e 29 anos","B":"Crianças entre 10 anos e 12 anos de idade","C":"Crianças abaixo dos 10 anos de idade","D":"Adolescentes entre 16 e 18 anos"},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215132","number":"215132","sourceNumber":"215132","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino de 4 anos é internado por apresentar febre de 39°C por 6 dias, conjuntivas\nhiperemiadas, sem secreções, exantema polimorfos, fissuras labiais, edemas de mãos e pés,\nfissuras labiais e adenopatia cervical. O tratamento visa prevenir qual complicação?","options":{"A":"Endocardite bacteriana.","B":"Aneurisma de coronária.","C":"Insuficiência hepática.","D":"Edema cerebral.","E":"Estenose de valva mitral."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215159","number":"215159","sourceNumber":"215159","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Qual doença tem maior correlação com a ataxia cerebelar aguda na faixa etária\npediátrica?","options":{"A":"Infecção pelo vírus da varicela.","B":"Infecção pelo Epstein-Barr.","C":"Infecção pelo vírus da hepatite A.","D":"Infecção pelo Herpes vírus.","E":"Infeção por Legionella."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215163","number":"215163","sourceNumber":"215163","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino, 3 anos, apresenta subitamente irritabilidade, salivação excessiva, tosse e\ndesconforto respiratório enquanto brincava no trabalho de seu pai que é relojoalheiro. É levado\npelos responsáveis ao pronto atendimento pediátrico que referem que a criança é previamente\nhígida, não tem alergias e nunca ficou internado. Negam sinais e sintomas prévios ao evento atual.\nMarque a alternativa que tenha a principal hipótese diagnóstica e conduta a ser tomada.","options":{"A":"Aspiração não acidental de corpo estranho ? Endoscopia Digestiva Alta (EDA).","B":"Aspiração acidental de corpo estranho ? Radiografia de pescoço, tórax e abdome.","C":"Aspiração acidental de corpo estranho ? Endoscopia Digestiva Alta (EDA).","D":"Broncoaspiração ? Broncoscopia.","E":"Broncoaspiração ? Rx de tórax."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-215170","number":"215170","sourceNumber":"215170","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Paciente de 10 anos é levado ao Pronto socorro pediátrico arresponsivo, sem\nrespiração e sem pulso. Após monitorização\nvocê visualiza o ritmo abaixo. Qual a conduta imediata\nde acordo com o ritmo em questão?","options":{"A":"Acesso venoso, intubação com sequência rápida e monitorização.","B":"Acesso venoso, ventilação com pressão positiva com bolsa-válvula-máscara e reservatório e\ncompressão torácica.","C":"Acesso venoso, adrenalina e compressão torácica.","D":"Acesso venoso, ventilação com pressão positiva e choque.","E":"Acesso venoso, monitorização, intubação orotraqueal e choque."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":["question_bank/media/medcurso/medcurso-pediatria-ped-5/215170.png"],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-187510","number":"187510","sourceNumber":"187510","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Menino de 4 anos de idade foi levado ao pediatra porque têm febre há 9 dias. Ao\nexame físico nota-se hiperemia conjuntival\nbilateral não purulenta, palmas das mãos e plantas dos\npés com eritema e edema indurado, fissuras labiais, \"rash\" maculo-papular eritematoso em tronco e\nmembros, e adenopatia cervical à esquerda (de 2 cm de diâmetro). Exames laboratoriais\nmostraram leucocitose com neutrofilia, trombocitose, VHS= 55 mm/h, PCR= 10 mg/dl, TGO = 80\nU/L e TGP= 60 U/L, hipoalbuminemia, hiponatremia. Qual o diagnóstico mais provável?","options":{"A":"Difteria.","B":"Doença de Lyme.","C":"Artrite reumatoide.","D":"Doença de Kawasaki.","E":"Lúpus eritematoso sistêmico."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-187513","number":"187513","sourceNumber":"187513","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"A causa mais comum de obstrução do trato urinário inferior em meninos é a:","options":{"A":"Estenose uretral.","B":"Válvula de uretra posterior.","C":"Divertículo uretral.","D":"Hipospádia.","E":"Litíase uretral."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-174367","number":"174367","sourceNumber":"174367","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Pré-escolar, sexo feminino, é levada ao pediatra por ter apresentado sangue na urina.\nMãe relata um episódio de infecção urinária corretamente tratado há cinco meses. Relata ainda\nconstipação intestinal. Exame físico: sinais vitais normais. Abdome: levemente distendido, discreta\nflatulência, peristalse normal e presença de pequena tumoração palpável em quadrante superior\ndireito, EAS: positivo para proteínas e sangue. O quadro sugere:","options":{"A":"Nefroma cístico.","B":"Tumor de Willms.","C":"Neuroblastoma.","D":"Nefroma mesoblastico.","E":"Nova infecção urinária."},"answer":"B","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-187512","number":"187512","sourceNumber":"187512","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Lactente portador de comunicação interventricular (CIV) pequena apresenta:","options":{"A":"Difícil elucidação diagnóstica através do ecocardiograma.","B":"Indicação de cirurgia cardíaca de urgência logo após o nascimento.","C":"Alto risco de evoluir com insuficiência cardíaca logo após o nascimento.","D":"Evolução assintomática na maioria dos casos, com possibilidade de fechamento espontâneo da\nCIV.","E":"Necessidade de confirmação diagnóstica através do cateterismo cardíaco."},"answer":"D","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-187464","number":"187464","sourceNumber":"187464","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Em relação à enurese na infância, assinale a opção incorreta:","options":{"A":"A enurese noturna é mais comum em crianças do sexo feminino, em todas as faixas etárias.","B":"A causa da enurese provavelmente envolve fatores biológicos, emocionais e de aprendizagem.","C":"A enurese monossintomática raramente está associada a anormalidades orgânicas subjacentes\nsignificativas.","D":"A enurese noturna refere-se à ocorrência de micção involuntária após os 5 anos de idade.","E":"O tratamento da enurese noturna inclui terapia motivacional, terapia de condicionamento e\nterapia farmacológica."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-187469","number":"187469","sourceNumber":"187469","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Uma criança de 3 anos está há 10 dias com varicela e afebril. Há um dia, a criança não\nestá conseguindo andar e não está conseguindo ficar de pé por muito tempo. Tem alteração da\nlinguagem, nistagmo, tremores, mas seu estado geral é bom. O diagnóstico mais provável para\nesse quadro é o de:","options":{"A":"Ataxia cerebelar.","B":"Mielite transversa.","C":"Meningite bacteriana.","D":"Poliomielite.","E":"Síndrome convulsiva."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-172543","number":"172543","sourceNumber":"172543","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Criança de 3 anos iniciou há 6 dias febre alta, hiperemia conjuntival bilateral não\nsecretiva, ressecamento dos lábios, eritema de língua, gânglios palpáveis à esquerda de região\ncervical (não palpável à direita) e exantema maculopapular difuso. Sobre essa doença NÃO\npodemos afirmar:","options":{"A":"Trata-se de uma doença de vasos de médio calibre, etiopatogenia viral, autolimitada, requerendo\napenas tratamento com corticosteroides e\nsintomáticos.","B":"Diagnóstico é clínico, não sendo necessária a biópsia de gânglio.","C":"Ecocardiograma basal deve ser realizado no momento da doença aguda e repetido após, no\nseguimento periódico na avaliação cardiovascular.","D":"Os objetivos do tratamento são reduzir a inflamação e evitar a formação de aneurismas\ncoronarianos."},"answer":"A","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-172512","number":"172512","sourceNumber":"172512","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Escolar apresentando febre há 48h, odinofagia, vômitos, cefaleia e dor abdominal. Ao\nexame: orofaringe hiperemiada e com placas, língua saburrosa, exantema maculopapular em todo\no corpo exceto em região perioral. Pode-se afirmar sobre o quadro descrito acima, EXCETO:","options":{"A":"Doença de etiologia bacteriana, sendo o tratamento indicado a penicilina benzatina dose única.","B":"A transmissão começa desde os pródromos até o desaparecimento da febre, ou após 24h\npós-início do tratamento.","C":"O exantema caracteriza-se por: evoluir em três estágios e possuir caráter recorrente.","D":"Na segunda/terceira semana evolui com descamação laminar (pés e mãos)."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true},{"id":"medcurso-pediatria-ped-5-172840","number":"172840","sourceNumber":"172840","collectionBlock":"medcurso:medcurso-pediatria-ped-5","collectionLabel":"Medcurso · PED 5","documentBlock":"","area":"Pediatria","specialty":"Pediatria","topic":"PED 5","subtopic":"","stem":"Viroses exantemáticas são moléstias infecciosas nas quais a erupção cutânea é a\ncaracterística dominante. A análise do tipo da lesão, dos sinais e dos sintomas concomitantes e da\nepidemiologia, algumas vezes, permitem inferir o diagnóstico etiológico sem a necessidade de\nexames laboratoriais complementares. Associe as viroses exantemáticas com os sinais e sintomas\ne em seguida, marque a alternativa correta. 1. Sarampo; 2. Rubéola; 3. Eritema infeccioso; 4.\n\nExantema súbito; ( ) Manchas de Koplik, toxemia, fotofobia, tosse, febre; ( ) Exantema\nmaculopapular com início coincidindo com a\nqueda da febre; ( ) Geralmente não há pródromos e o\nprimeiro sinal costuma ser o exantema, que se inicia na face; ( ) Adenopatia retroauricular e\noccipital, artralgia.","options":{"A":"1-2-3-4.","B":"3-2-1-4.","C":"1-4-3-2.","D":"4-3-1-2."},"answer":"C","source":"Pediatria/PED 5/PED 5.txt","sourceLabel":"Medcurso · PED 5","images":[],"optionImages":{},"commentImages":[],"tags":["Pediatria","PED 5","Medcurso"],"answerSource":"explicit","commentDeferred":true}]};
